-- 設問の取り込み（import_cbt_basic_2026、2/2本目、176問）。
-- 元のデータ: cbt_batch_basic_2026.json
-- status は pending（審査待ち）で入り、人の医学的レビューで公開するまで学習者には出ない。
-- 何度流しても結果は同じ（すでにある問題は入れない）。本数が複数あるときは全部流す。順番は問わない。
-- 最後に「追加した問題／すでにあった問題」の表が出る。
-- scripts/build_question_import_sql.py で作り直せる。
WITH v (category, topic, difficulty, exam_type, question_text, choices, correct_choice_key, explanation, choice_explanations, visibility, question_type, blueprint_code, class_group, status, source) AS (VALUES
('基礎医学', '抗原受容体の多様性', 2, 'CBT', 'ヒトは限られた数の遺伝子から、きわめて多様な抗原に対応するB細胞受容体とT細胞受容体をつくり出す。この多様性を生み出す主な仕組みはどれか。', '[{"key": "A", "text": "選択的スプライシングだけによる多様化"}, {"key": "B", "text": "翻訳後の糖鎖修飾による多様化"}, {"key": "C", "text": "抗原に合わせて蛋白質の立体構造が変わること"}, {"key": "D", "text": "リンパ球ごとに異なる遺伝暗号を使うこと"}, {"key": "E", "text": "V(D)J遺伝子再構成"}]'::jsonb, 'E', 'リンパ球の分化の過程で、多数あるV、D、J遺伝子断片から1つずつがRAG1/RAG2などの酵素によって選ばれてつながり、つなぎ目に塩基の挿入や欠失も加わって、膨大な種類の受容体ができる。重鎖と軽鎖の組合せでさらに多様性が増す。B細胞では抗原刺激のあと体細胞超変異で親和性が高まる。RAGの欠損ではT細胞もB細胞もできず、重症複合免疫不全症となる。', '{"A": "主な仕組みではない。", "B": "抗原結合部位の多様性を生む主な仕組みではない。", "C": "抗原に合わせて受容体がつくり替えられるわけではない。", "D": "遺伝暗号はすべての細胞で共通である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '二次免疫応答', 2, 'CBT', 'ワクチンは、決められた間隔で複数回接種することで効果が高まる。同じ抗原に2回目にさらされたときの抗体の応答として正しいのはどれか。', '[{"key": "A", "text": "初回より速やかに、大量のIgGが産生される"}, {"key": "B", "text": "初回と同じ速さで、同じ量のIgMが産生される"}, {"key": "C", "text": "初回より遅れて、少量のIgMだけが産生される"}, {"key": "D", "text": "抗体は産生されず、T細胞だけが反応する"}, {"key": "E", "text": "抗原との親和性が初回より低い抗体が産生される"}]'::jsonb, 'A', '初回の応答（一次応答）では、抗原に出会ってから抗体が出るまでに1週間ほどかかり、主にIgMが産生される。その過程で記憶B細胞と記憶T細胞ができるため、2回目（二次応答）には数日で大量のIgGが産生され、親和性も高い。追加接種（ブースター）はこの記憶を利用して、長く続く高い抗体価を得るために行う。', '{"B": "記憶細胞のため、2回目は速く大量に反応する。", "C": "2回目の応答は速く、主にIgGが産生される。", "D": "記憶B細胞から形質細胞が速やかに生じて抗体が産生される。", "E": "親和性成熟により、親和性はむしろ高まる。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '弱毒ワクチンの禁忌', 2, 'CBT', '妊婦や、高用量の副腎皮質ステロイドを使用している患者には、原則として接種しないワクチンがある。接種すると病原体そのものによる感染症を起こすおそれがあるため、これらの人に接種しないワクチンはどれか。', '[{"key": "A", "text": "破傷風トキソイド"}, {"key": "B", "text": "麻疹風疹混合ワクチン"}, {"key": "C", "text": "インフルエンザHAワクチン"}, {"key": "D", "text": "B型肝炎ワクチン"}, {"key": "E", "text": "肺炎球菌莢膜多糖体ワクチン"}]'::jsonb, 'B', '麻疹、風疹、水痘、おたふくかぜ、BCGなどのワクチンは、弱毒化した生きた病原体を用いる。細胞性免疫を含む強い免疫が得られる一方で、免疫が低下した人では病原体が増殖して感染症を起こしうるため、妊婦や免疫抑制状態の人には原則として接種しない。風疹ワクチンの接種後は2か月間の避妊が勧められる。病原体の成分や無毒化した毒素を用いるワクチンは、このような人にも接種できる。', '{"A": "無毒化した毒素を用いたもので、妊婦にも接種できる。", "C": "ウイルスの成分を用いたワクチンで、妊婦にも接種できる。", "D": "組換えの抗原蛋白を用いたワクチンで、増殖する病原体を含まない。", "E": "菌の成分を用いたワクチンで、増殖する病原体を含まない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '受動免疫', 2, 'CBT', '免疫は、自分の体で抗体やリンパ球をつくる能動免疫と、他者がつくった抗体を受け取る受動免疫に分けられる。受動免疫に当たるものはどれか。', '[{"key": "A", "text": "B型肝炎ワクチンの3回接種"}, {"key": "B", "text": "乳児期のBCG接種"}, {"key": "C", "text": "抗破傷風ヒト免疫グロブリンの投与"}, {"key": "D", "text": "破傷風トキソイドの接種"}, {"key": "E", "text": "麻疹に自然に感染して回復し、免疫を得ること"}]'::jsonb, 'C', '受動免疫は抗体を外から与えるもので、効果がすぐに現れるが、記憶は残らず数週間から数か月で消える。破傷風のおそれがある汚染創では、トキソイドに加えて抗破傷風ヒト免疫グロブリンを投与することがある。B型肝炎ウイルス陽性の母親から生まれた児には、HBs抗原に対する免疫グロブリンとワクチンを併用する。胎盤を通るIgGや母乳のIgAは自然の受動免疫である。', '{"A": "自分の体で抗体をつくらせる能動免疫である。", "B": "自分の体の細胞性免疫を誘導する能動免疫である。", "D": "自分の体で抗体をつくらせる能動免疫である。", "E": "自然感染による能動免疫である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '超急性拒絶反応', 2, 'CBT', '腎移植で、血流を再開した直後から数分〜数時間のうちに移植腎が暗紫色になり、機能しなくなった。この拒絶反応の主な原因はどれか。', '[{"key": "A", "text": "移植片に含まれるドナーのT細胞"}, {"key": "B", "text": "長期にわたる慢性の血管障害"}, {"key": "C", "text": "免疫抑制薬による腎毒性"}, {"key": "D", "text": "移植前からもっていた抗ドナー抗体"}, {"key": "E", "text": "移植後に新たに感作された受容者のT細胞"}]'::jsonb, 'D', '超急性拒絶反応は、受容者が輸血、妊娠、以前の移植などでドナーのHLAやABO血液型抗原に対する抗体をすでにもっている場合に、移植片の血管内皮に抗体が結合して補体を活性化し、血栓で移植片が壊死するものである。移植前にABO血液型を確認し、ドナーのリンパ球と受容者の血清を反応させる交差適合試験（クロスマッチ）で予防する。', '{"A": "移植片対宿主病の原因である。", "B": "数か月〜数年かけて進む慢性拒絶反応の機序である。", "C": "拒絶反応ではなく薬剤による障害である。", "E": "数日〜数週後に起こる急性拒絶反応の主な機序である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '輸血後移植片対宿主病', 2, 'CBT', '輸血後移植片対宿主病は、輸血の1〜2週後に発熱、紅斑、肝障害、汎血球減少をきたし、ほぼ致死的な合併症である。この病態の原因となる細胞はどれか。', '[{"key": "A", "text": "受容者自身の制御性T細胞"}, {"key": "B", "text": "血液製剤に含まれる供血者の赤血球"}, {"key": "C", "text": "血液製剤に含まれる供血者の血小板"}, {"key": "D", "text": "受容者の血漿中の抗HLA抗体"}, {"key": "E", "text": "供血者のT細胞"}]'::jsonb, 'E', '血液製剤に含まれる供血者のT細胞が受容者の体内で排除されずに増殖し、受容者の組織を異物として攻撃する。受容者の免疫が低下しているときや、供血者と受容者のHLAが一方向に似ているとき（近親者からの輸血など）に起こりやすい。骨髄が攻撃されるため汎血球減少となり、治療は困難である。血液製剤にあらかじめ放射線を当ててリンパ球の増殖能を失わせることで予防する。', '{"A": "受容者の細胞が原因となる病態ではない。", "B": "赤血球はこの病態の原因ではない。", "C": "血小板はこの病態の原因ではない。", "D": "抗体による反応ではなく、供血者のリンパ球による反応である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'HLAの遺伝', 2, 'CBT', '造血幹細胞移植のドナーを探すとき、まず患者のきょうだいのHLAを調べる。HLAの遺伝の特徴として正しいのはどれか。', '[{"key": "A", "text": "同胞とHLAが一致する確率は1/4である"}, {"key": "B", "text": "父親のHLAだけを受け継ぎ、同胞とは必ず一致する"}, {"key": "C", "text": "HLAは個人差がほとんどなく、他人とも一致しやすい"}, {"key": "D", "text": "X染色体上にあり、男性は母親からだけ受け継ぐ"}, {"key": "E", "text": "一卵性双生児どうしでも一致しない"}]'::jsonb, 'A', 'HLA遺伝子は6番染色体短腕に密に並び、一組のまとまり（ハプロタイプ）として両親から1つずつ受け継がれる。そのため同胞とHLAが完全に一致する確率は1/4、半分一致する確率は1/2、まったく一致しない確率は1/4である。非血縁者で一致する確率は低いため、骨髄バンクで多くの登録者から探す。HLAは特定の疾患のなりやすさとも関連する（強直性脊椎炎とHLA-B27など）。', '{"B": "両親から1組ずつ受け継ぎ、同胞と必ず一致するわけではない。", "C": "HLAはきわめて多型性に富み、他人と一致する確率は低い。", "D": "HLA遺伝子は6番染色体の短腕にある。", "E": "一卵性双生児はHLAが完全に一致する。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'X連鎖無γグロブリン血症', 2, 'CBT', '生後6か月ごろから中耳炎や肺炎などの細菌感染を繰り返す男児で、血清のIgG、IgA、IgMがいずれも著しく低く、末梢血のB細胞がほとんどいない。この疾患について正しいのはどれか。', '[{"key": "A", "text": "ウイルス感染にだけ弱く、細菌感染には強い"}, {"key": "B", "text": "BTK遺伝子の異常でB細胞の分化が止まる"}, {"key": "C", "text": "胸腺の低形成でT細胞が欠損する"}, {"key": "D", "text": "NADPHオキシダーゼの欠損で殺菌能が低下する"}, {"key": "E", "text": "生後すぐから感染を繰り返すことが多い"}]'::jsonb, 'B', 'X連鎖無γグロブリン血症（Bruton型）は、Brutonチロシンキナーゼ（BTK）の遺伝子異常でB細胞の分化が止まり、すべてのクラスの免疫グロブリンが著しく低下する。母親由来のIgGが減る生後数か月から、肺炎球菌やインフルエンザ菌などによる中耳炎、肺炎、髄膜炎を繰り返す。リンパ節や扁桃が小さい。定期的な免疫グロブリンの補充で治療する。', '{"A": "主に莢膜をもつ細菌による感染を繰り返す。", "C": "22q11.2欠失症候群などの病態である。", "D": "慢性肉芽腫症の病態である。", "E": "母親から移行したIgGがあるため、生後数か月は感染が目立たない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '慢性肉芽腫症', 2, 'CBT', '幼少期から黄色ブドウ球菌やアスペルギルスによる膿瘍や肺炎を繰り返す男児がいる。好中球は正常な数あるが、殺菌能が低下していた。この疾患で欠損している酵素はどれか。', '[{"key": "A", "text": "グルコース6-リン酸脱水素酵素"}, {"key": "B", "text": "ブルトンチロシンキナーゼ"}, {"key": "C", "text": "NADPHオキシダーゼ"}, {"key": "D", "text": "ミエロペルオキシダーゼ"}, {"key": "E", "text": "アデノシンデアミナーゼ"}]'::jsonb, 'C', '慢性肉芽腫症は食細胞のNADPHオキシダーゼの欠損で、貪食した微生物を殺すための活性酸素（スーパーオキシド）をつくれない疾患で、多くはX連鎖性である。カタラーゼを産生する黄色ブドウ球菌や真菌（アスペルギルス）は自ら過酸化水素を分解するため、とくに感染を起こしやすい。殺しきれない微生物の周りに肉芽腫ができる。ジヒドロローダミン試験で診断する。', '{"A": "赤血球の酸化ストレスへの弱さの原因となり、主に溶血をきたす。", "B": "欠損するとB細胞が分化せず、無γグロブリン血症となる。", "D": "欠損しても症状は軽いことが多く、この病態の主な原因ではない。", "E": "欠損すると重症複合免疫不全症となる。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '結核に対する免疫', 2, 'CBT', '結核菌はマクロファージに貪食されても、その中で生き延びて増殖することができる。結核菌に対する防御で中心となる免疫の仕組みはどれか。', '[{"key": "A", "text": "補体の膜侵襲複合体による溶菌"}, {"key": "B", "text": "IgEとマスト細胞による排除"}, {"key": "C", "text": "好酸球の顆粒蛋白による傷害"}, {"key": "D", "text": "IFN-γによるマクロファージの活性化"}, {"key": "E", "text": "中和抗体が菌の毒素に結合して無毒化すること"}]'::jsonb, 'D', '細胞内に寄生する結核菌の排除には細胞性免疫が必要である。Th1細胞が産生するインターフェロンγとTNF-αでマクロファージが活性化され、殺菌能が高まり、肉芽腫をつくって菌を封じ込める。HIV感染症でCD4陽性T細胞が減ったり、TNF-α阻害薬を使ったりすると、潜伏していた結核が再燃しやすいため、TNF-α阻害薬の開始前には結核の感染を調べる。', '{"A": "結核菌は厚い脂質の細胞壁をもち、溶菌されにくい。", "B": "寄生虫などに対する反応で、結核菌への主な防御ではない。", "C": "寄生虫に対する防御の中心である。", "E": "結核菌は主に細胞内にいるため、抗体の役割は小さい。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '好酸球', 2, 'CBT', '海外旅行から帰国した患者で、末梢血の好酸球が著しく増えていた。寄生虫感染で増加し、顆粒に含まれる主要塩基性蛋白などで蠕虫を傷害する細胞はどれか。', '[{"key": "A", "text": "好中球"}, {"key": "B", "text": "単球"}, {"key": "C", "text": "好塩基球"}, {"key": "D", "text": "血小板"}, {"key": "E", "text": "好酸球"}]'::jsonb, 'E', '好酸球は大きすぎて貪食できない蠕虫に対し、IgEやIgGを介して結合し、主要塩基性蛋白や好酸球陽イオン蛋白などの顆粒の内容物を放出して傷害する。Th2細胞のIL-5で分化と動員が促される。好酸球の増加は寄生虫感染のほか、アレルギー疾患、薬剤アレルギー、好酸球性多発血管炎性肉芽腫症、副腎不全などでもみられる。', '{"A": "主に細菌や真菌を貪食して殺菌する。", "B": "組織でマクロファージとなり、貪食や抗原提示を担う。", "C": "IgEを表面に結合し、ヒスタミンなどを放出する。", "D": "止血に働く細胞片である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'ハプテン', 2, 'CBT', 'ペニシリンのような低分子の薬剤でも、アレルギーの原因になることがある。単独では抗体産生を誘導できないが、体内の蛋白質に結合すると抗体産生を誘導できるようになる低分子はどれか。', '[{"key": "A", "text": "ハプテン"}, {"key": "B", "text": "アジュバント"}, {"key": "C", "text": "スーパー抗原"}, {"key": "D", "text": "トキソイド"}, {"key": "E", "text": "サイトカイン"}]'::jsonb, 'A', 'ハプテンは抗体と結合する性質（抗原性）はあるが、単独では免疫応答を起こす力（免疫原性）がない低分子である。体内の蛋白質（担体）と結合すると、担体の部分がT細胞の助けを引き出し、ハプテンに対する抗体がつくられる。ペニシリンが赤血球膜や血清の蛋白質に結合して起こる薬剤アレルギーや、金属イオンによる接触皮膚炎がその例である。', '{"B": "ワクチンなどで一緒に投与して免疫応答を強める物質で、抗原そのものではない。", "C": "MHCクラスII分子とT細胞受容体を直接つなぐ毒素で、低分子ではない。", "D": "毒素を無毒化して抗原性を保ったものである。", "E": "細胞間の情報伝達を担う蛋白質で、抗原ではない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '抗体依存性細胞傷害', 2, 'CBT', '抗CD20抗体のリツキシマブは、B細胞リンパ腫の細胞に結合して、免疫の細胞に腫瘍細胞を攻撃させる。抗体が結合した標的細胞を、NK細胞がFc受容体で認識して傷害する仕組みはどれか。', '[{"key": "A", "text": "免疫複合体の組織への沈着"}, {"key": "B", "text": "抗体依存性細胞傷害（ADCC）"}, {"key": "C", "text": "補体依存性の食作用だけによる排除"}, {"key": "D", "text": "MHCクラスIを介した細胞傷害性T細胞の反応"}, {"key": "E", "text": "IgEによるマスト細胞の脱顆粒"}]'::jsonb, 'B', '標的細胞に結合したIgGのFc部分を、NK細胞のFcγ受容体（CD16）が認識し、パーフォリンとグランザイムで標的細胞を殺す。これを抗体依存性細胞傷害（ADCC）という。リツキシマブ、トラスツズマブ、セツキシマブなどの抗体医薬は、ADCCや補体依存性の細胞傷害などを介して腫瘍細胞を傷害する。', '{"A": "III型アレルギーの仕組みである。", "C": "補体による反応で、NK細胞がFc受容体で認識する仕組みではない。", "D": "抗体に依存しない、T細胞受容体による認識である。", "E": "I型アレルギーの仕組みである。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'オプソニン', 2, 'CBT', '莢膜をもつ細菌は、そのままでは好中球やマクロファージに貪食されにくい。細菌の表面を覆って食細胞による貪食を促す働き（オプソニン作用）をもつ分子の組合せはどれか。', '[{"key": "A", "text": "ヒスタミンとロイコトリエン"}, {"key": "B", "text": "インターロイキン2とインターフェロンγ"}, {"key": "C", "text": "IgGとC3b"}, {"key": "D", "text": "IgEとC5a"}, {"key": "E", "text": "IgMとC5b-9"}]'::jsonb, 'C', 'IgGは細菌の表面に結合し、Fc部分が食細胞のFc受容体に結合することで貪食を促す。補体の活性化で生じたC3bも細菌の表面に結合し、食細胞の補体受容体に認識される。両方がそろうと貪食の効率は大きく高まる。脾臓はオプソニン化された細菌の除去の場として重要で、脾摘後には莢膜をもつ細菌の感染が重症化しやすい。', '{"A": "マスト細胞が放出する化学伝達物質である。", "B": "リンパ球などが産生するサイトカインである。", "D": "IgEはマスト細胞に結合し、C5aは走化とアナフィラトキシンの作用をもつ。", "E": "IgMは補体を活性化するが、C5b-9は膜侵襲複合体で、オプソニンではない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '形質細胞', 2, 'CBT', '骨髄腫の患者では、単一の細胞に由来する大量の免疫グロブリン（M蛋白）が血中に出現する。抗体を大量に産生して分泌する、B細胞の最終分化した細胞はどれか。', '[{"key": "A", "text": "マクロファージ"}, {"key": "B", "text": "マスト細胞"}, {"key": "C", "text": "樹状細胞"}, {"key": "D", "text": "形質細胞"}, {"key": "E", "text": "記憶B細胞"}]'::jsonb, 'D', '形質細胞は、抗原刺激を受けたB細胞が分化した細胞で、粗面小胞体とゴルジ装置がよく発達し、核の染色質が車軸状に見える。1つの形質細胞は1種類の抗体だけを大量に分泌する。主に骨髄やリンパ節の髄索、粘膜固有層にいる。多発性骨髄腫は形質細胞の腫瘍で、骨病変、貧血、腎障害、高カルシウム血症をきたす。', '{"A": "貪食と抗原提示を担う細胞で、抗体はつくらない。", "B": "IgEを表面に結合し、ヒスタミンなどを放出する細胞である。", "C": "抗原を提示してT細胞を活性化する細胞である。", "E": "再び抗原に出会ったときに速やかに反応するための細胞で、大量の抗体は分泌しない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'IL-2とカルシニューリン阻害薬', 2, 'CBT', '臓器移植後の拒絶反応の予防には、シクロスポリンやタクロリムスが用いられる。これらの薬剤がT細胞で産生を抑える、T細胞の増殖を促す主なサイトカインはどれか。', '[{"key": "A", "text": "インターロイキン5"}, {"key": "B", "text": "インターロイキン10"}, {"key": "C", "text": "エリスロポエチン"}, {"key": "D", "text": "顆粒球コロニー刺激因子"}, {"key": "E", "text": "インターロイキン2"}]'::jsonb, 'E', 'T細胞受容体からの刺激で細胞内カルシウムが増えると、カルシニューリンが転写因子NFATを脱リン酸化して核に移行させ、インターロイキン2の遺伝子の転写が起こる。インターロイキン2はT細胞自身に作用して増殖を促す。シクロスポリンとタクロリムスはカルシニューリンを阻害してこの過程を止める。副作用として腎障害、高血圧、耐糖能異常に注意が要る。', '{"A": "主にTh2細胞が産生し、好酸球の分化と活性化を促す。", "B": "免疫応答を抑える方向に働くサイトカインである。", "C": "腎臓でつくられ、赤血球の産生を促すホルモンである。", "D": "好中球の産生を促すサイトカインである。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '定常状態までの時間', 2, 'CBT', 'ある薬物を一定の間隔と用量で繰り返し投与すると、血中濃度は上下しながら一定の範囲に落ち着く。血中濃度がほぼ定常状態に達するまでの時間の目安はどれか。', '[{"key": "A", "text": "消失半減期の約4〜5倍"}, {"key": "B", "text": "消失半減期と同じ時間"}, {"key": "C", "text": "消失半減期の約2倍"}, {"key": "D", "text": "消失半減期の10倍以上の長い時間"}, {"key": "E", "text": "投与間隔と同じ時間"}]'::jsonb, 'A', '一次速度で消失する薬物を一定の間隔で投与すると、1半減期で定常状態の50%、2半減期で75%、3半減期で87.5%、4〜5半減期で90数%に達する。定常状態に達する時間は投与量や投与間隔によらず、半減期だけで決まる。半減期の長い薬物で早く効果を得たいときは、はじめに負荷投与を行う。投与を中止したときも、同じく4〜5半減期でほぼ体内から消失する。', '{"B": "1半減期では定常状態の約50%にしか達しない。", "C": "2半減期では定常状態の約75%にとどまる。", "D": "10倍もかけなくても、4〜5倍でほぼ定常状態に達する。", "E": "定常状態に達する時間は投与間隔ではなく半減期で決まる。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '負荷投与量', 2, 'CBT', 'ジゴキシンやアミオダロンのように半減期の長い薬物では、効果を早く得るために初回に多めの量を投与することがある。目標とする血中濃度をすぐに得るための負荷投与量を決める主な因子はどれか。', '[{"key": "A", "text": "血漿蛋白結合率だけ"}, {"key": "B", "text": "分布容積"}, {"key": "C", "text": "全身クリアランス"}, {"key": "D", "text": "投与間隔"}, {"key": "E", "text": "生物学的利用率だけ"}]'::jsonb, 'B', '負荷投与量は、目標とする血中濃度に分布容積を掛けて求める（経口ではさらに生物学的利用率で割る）。体内の薬物量を一気に目標の量まで満たすためである。維持投与量は、目標濃度に全身クリアランスを掛けた量を投与間隔ごとに補う。分布容積の大きい薬物ほど、負荷投与量は大きくなる。', '{"A": "負荷投与量を決める主な因子ではない。", "C": "定常状態の血中濃度を保つための維持量を決める因子である。", "D": "維持投与の計画に関わるが、負荷投与量を決める主な因子ではない。", "E": "経口投与では補正に用いるが、主に決めるのは分布容積である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '分布容積', 2, 'CBT', '分布容積は、体内の薬物の量を血漿中の濃度で割って求めた、見かけの体液の容積である。分布容積が非常に大きい薬物の特徴として正しいのはどれか。', '[{"key": "A", "text": "血液透析で容易に除去される"}, {"key": "B", "text": "分布容積は体重にかかわらず一定の値をとる"}, {"key": "C", "text": "脂溶性が高く組織に広く移行する"}, {"key": "D", "text": "血漿蛋白との結合が強く、血管内にとどまる"}, {"key": "E", "text": "水溶性が高く、細胞外液にだけ分布する"}]'::jsonb, 'C', 'ヘパリンのように血管内にとどまる薬物は分布容積が血漿量に近く小さい。脂溶性が高い薬物や組織に強く結合する薬物（アミオダロン、三環系抗うつ薬など）は、体内総水分量をはるかに超える見かけの分布容積を示す。こうした薬物の中毒では、血中にある量がわずかなため、血液透析の効果は乏しい。', '{"A": "分布容積が大きい薬物は血中にわずかしかなく、透析で除去しにくい。", "B": "分布容積は体格や体組成によって変わる。", "D": "血管内にとどまる薬物は分布容積が小さい。", "E": "分布容積は細胞外液量程度にとどまる。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '腎排泄型の薬物', 2, 'CBT', '高齢者や慢性腎臓病の患者では、腎から排泄される薬物がたまりやすく、中毒を起こしやすい。腎機能が低下した患者で投与量や投与間隔の調節が最も必要な薬物はどれか。', '[{"key": "A", "text": "ワルファリン"}, {"key": "B", "text": "リファンピシン"}, {"key": "C", "text": "ミダゾラム"}, {"key": "D", "text": "ゲンタマイシン"}, {"key": "E", "text": "プロプラノロール"}]'::jsonb, 'D', 'アミノグリコシド系抗菌薬はほとんど代謝されずに腎から排泄されるため、腎機能が落ちると血中濃度が上がり、腎毒性や聴器毒性が出やすくなる。クレアチニンクリアランスに応じて投与間隔を延ばし、血中濃度を測定して調節する（治療薬物モニタリング）。バンコマイシン、ジゴキシン、リチウム、多くのβ-ラクタム系も腎機能に応じた調節が必要である。', '{"A": "主に肝で代謝されて消失する。", "B": "主に肝で代謝され、胆汁中に排泄される。", "C": "主に肝のCYP3A4で代謝される。", "E": "主に肝で代謝されて消失する。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '非線形の薬物動態', 2, 'CBT', 'てんかんの患者で、ある抗てんかん薬の投与量を少し増やしただけで、血中濃度が大きく上がり、眼振と運動失調が出現した。代謝が飽和して、このような非線形の動態を示しやすい薬物はどれか。', '[{"key": "A", "text": "ゲンタマイシン"}, {"key": "B", "text": "ワルファリン"}, {"key": "C", "text": "炭酸リチウム"}, {"key": "D", "text": "レベチラセタム"}, {"key": "E", "text": "フェニトイン"}]'::jsonb, 'E', '多くの薬物は一次速度（血中濃度に比例した速度）で消失するが、代謝酵素が飽和すると一定の速度でしか消失しなくなる（0次速度）。フェニトインは治療域でこの飽和が起こるため、わずかな増量で血中濃度が不釣り合いに上がり、眼振、運動失調、意識障害などの中毒症状が出る。血中濃度を測定しながら少しずつ調節する。エタノールやアスピリンの大量摂取でも飽和が起こる。', '{"A": "腎から排泄され、通常の用量では線形の動態を示す。", "B": "通常の用量では線形の動態を示す。", "C": "腎から排泄され、飽和による非線形の動態は典型ではない。", "D": "主に腎から排泄され、線形の動態を示す。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '血漿蛋白結合', 2, 'CBT', '薬物の多くは血中でアルブミンなどの血漿蛋白と結合しており、結合していない遊離型だけが作用を示す。蛋白結合率の高い薬物を使っている患者で、低アルブミン血症が進んだときに起こりやすい変化はどれか。', '[{"key": "A", "text": "遊離型が増えて作用が強まる"}, {"key": "B", "text": "結合型の割合が増え、作用が弱まる"}, {"key": "C", "text": "すべての薬物で総濃度と作用が変わらない"}, {"key": "D", "text": "薬物が腎から排泄されなくなる"}, {"key": "E", "text": "薬物の分布容積が必ず小さくなる"}]'::jsonb, 'A', 'ワルファリンやフェニトインは蛋白結合率が高く、アルブミンが低下したり、結合部位を奪い合う薬が併用されたりすると遊離型の割合が増える。フェニトインでは測定した総濃度が治療域でも遊離型が多く、中毒を起こすことがある。高齢者、ネフローゼ症候群、肝硬変、低栄養の患者では蛋白結合の変化に注意する。', '{"B": "アルブミンが減ると結合できる場が減り、遊離型が増える。", "C": "遊離型の割合が変わるため、同じ総濃度でも作用が異なりうる。", "D": "低アルブミン血症で排泄が止まるわけではない。", "E": "遊離型が組織に移行しやすくなり、分布容積はむしろ大きくなりうる。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '治療薬物モニタリング', 2, 'CBT', '有効な血中濃度と中毒を起こす血中濃度が近い薬物は、血中濃度を測定しながら投与量を調節する。治療域が狭く、血中濃度の測定が特に重要な薬物はどれか。', '[{"key": "A", "text": "ロスバスタチン"}, {"key": "B", "text": "炭酸リチウム"}, {"key": "C", "text": "アムロジピン"}, {"key": "D", "text": "ファモチジン"}, {"key": "E", "text": "アセトアミノフェン"}]'::jsonb, 'B', '炭酸リチウムは双極性障害の治療薬で、治療域と中毒域が近い。腎から排泄され、脱水、減塩、サイアザイド系利尿薬、NSAIDs、ACE阻害薬の併用で血中濃度が上がると、振戦、運動失調、意識障害などの中毒症状をきたす。ジゴキシン、テオフィリン、フェニトイン、バンコマイシン、アミノグリコシド系、免疫抑制薬なども治療薬物モニタリングの対象となる。', '{"A": "血中濃度ではなく脂質の値で効果を評価する。", "C": "治療域が比較的広く、日常的に血中濃度を測定する薬物ではない。", "D": "治療域が比較的広く、日常的に血中濃度を測定する薬物ではない。", "E": "通常量では血中濃度を測定しない。中毒の評価では測定する。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '酵素誘導', 2, 'CBT', '結核の治療を始めた患者で、併用していた経口避妊薬やワルファリンの効果が弱まった。肝の代謝酵素を誘導して、多くの併用薬の血中濃度を下げる薬物はどれか。', '[{"key": "A", "text": "シメチジン"}, {"key": "B", "text": "エリスロマイシン"}, {"key": "C", "text": "リファンピシン"}, {"key": "D", "text": "クラリスロマイシン"}, {"key": "E", "text": "イトラコナゾール"}]'::jsonb, 'C', 'リファンピシンは核内受容体（PXR）を介してCYP3A4などの代謝酵素やP糖蛋白の発現を増やし、多くの併用薬の代謝を速めて効果を弱める（酵素誘導）。効果が現れるまでに1〜2週かかり、中止後もしばらく続く。カルバマゼピン、フェニトイン、セイヨウオトギリソウ（セント・ジョーンズ・ワート）も酵素誘導を起こす。酵素阻害は数日以内に現れる点で異なる。', '{"A": "複数のCYPを阻害し、併用薬の血中濃度を上げる。", "B": "CYP3A4を阻害し、併用薬の血中濃度を上げる。", "D": "CYP3A4を阻害し、併用薬の血中濃度を上げる。", "E": "CYP3A4を強く阻害し、併用薬の血中濃度を上げる。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '妊娠中に避ける降圧薬', 2, 'CBT', '高血圧のある女性が妊娠した。胎児の腎障害、羊水過少、頭蓋骨の低形成などをきたすおそれがあるため、妊娠中は使用しない降圧薬はどれか。', '[{"key": "A", "text": "ラベタロール"}, {"key": "B", "text": "ニフェジピン"}, {"key": "C", "text": "ヒドララジン"}, {"key": "D", "text": "ACE阻害薬"}, {"key": "E", "text": "メチルドパ水和物"}]'::jsonb, 'D', 'レニン-アンジオテンシン系は胎児の腎の発達と機能に必要で、ACE（アンジオテンシン変換酵素）阻害薬やアンジオテンシンII受容体拮抗薬を妊娠中期以降に使うと、胎児の腎不全、羊水過少、肺の低形成、頭蓋骨の低形成などをきたす。妊娠を希望する女性や妊娠がわかった女性では、これらを中止してメチルドパ、ラベタロール、ニフェジピン、ヒドララジンなどに切り替える。', '{"A": "妊娠中の高血圧に用いられるαβ遮断薬である。", "B": "妊娠20週以降の高血圧に用いられる。", "C": "妊娠中の高血圧に用いられる血管拡張薬である。", "E": "妊娠中の高血圧に古くから用いられている。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'アトロピンの作用', 2, 'CBT', '徐脈の治療や、ある種の中毒の治療にアトロピンが用いられる。アトロピンを投与したときに生じる作用として正しいのはどれか。', '[{"key": "A", "text": "心拍数の減少と縮瞳"}, {"key": "B", "text": "汗腺からの発汗の増加"}, {"key": "C", "text": "気道分泌の増加"}, {"key": "D", "text": "腸管の蠕動の亢進"}, {"key": "E", "text": "心拍数の増加と散瞳"}]'::jsonb, 'E', 'アトロピンはムスカリン受容体の競合的拮抗薬で、副交感神経の作用を遮断する。心拍数の増加、散瞳と調節麻痺、唾液・気道分泌と発汗の減少、腸管運動と排尿の抑制が起こる。有機リン中毒でのムスカリン作用の拮抗、症候性の徐脈の治療に用いる。閉塞隅角緑内障や前立腺肥大症では症状を悪化させるおそれがあり、中毒では口渇、皮膚の紅潮、高体温、せん妄がみられる。', '{"A": "ムスカリン受容体を刺激したときの作用である。", "B": "汗腺のムスカリン受容体が遮断され、発汗は減る。", "C": "気道の分泌は減る。", "D": "腸管の運動は抑えられる。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'β2受容体', 2, 'CBT', '気管支喘息の発作時には、気管支平滑筋を速やかに弛緩させる吸入薬を用いる。刺激すると気管支平滑筋が弛緩するアドレナリン受容体はどれか。', '[{"key": "A", "text": "β2受容体"}, {"key": "B", "text": "α1受容体"}, {"key": "C", "text": "α2受容体"}, {"key": "D", "text": "β1受容体"}, {"key": "E", "text": "β3受容体"}]'::jsonb, 'A', 'β2受容体はGs蛋白質と共役し、cAMPを増やして気管支平滑筋を弛緩させる。短時間作用性β2刺激薬は喘息発作の治療に、長時間作用性β2刺激薬は吸入ステロイドとの併用で長期管理に用いる。子宮平滑筋を弛緩させる作用は切迫早産の治療に使われる。副作用として動悸、振戦、低カリウム血症がある。', '{"B": "刺激すると血管平滑筋が収縮する。", "C": "刺激すると交感神経終末からのノルアドレナリンの放出が抑えられる。", "D": "主に心臓にあり、刺激すると心拍数と収縮力が増す。", "E": "膀胱の排尿筋や脂肪組織にあり、気管支拡張の主な受容体ではない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'β遮断薬の禁忌', 2, 'CBT', '非選択的β遮断薬のプロプラノロールは、高血圧、狭心症、頻脈性不整脈、片頭痛の予防などに用いられる。プロプラノロールの投与が禁忌となる疾患はどれか。', '[{"key": "A", "text": "本態性振戦"}, {"key": "B", "text": "気管支喘息"}, {"key": "C", "text": "本態性高血圧症"}, {"key": "D", "text": "労作性狭心症"}, {"key": "E", "text": "甲状腺機能亢進症の頻脈"}]'::jsonb, 'B', '非選択的β遮断薬は気管支のβ2受容体も遮断するため、気管支を収縮させて喘息発作を誘発しうる。そのため気管支喘息には禁忌で、β1選択性の薬でも慎重に扱う。そのほか、高度の徐脈や房室ブロック、非代償性の心不全にも使用しない。糖尿病の患者では低血糖時の動悸などの警告症状を隠すことがある。', '{"A": "振戦を抑える目的で用いられる。", "C": "β遮断薬の適応となる疾患である。", "D": "心筋の酸素需要を減らすため、β遮断薬の適応となる。", "E": "動悸や頻脈を抑える目的で用いられる。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'ネオスチグミン', 2, 'CBT', '重症筋無力症の診断や治療に、コリンエステラーゼ阻害薬が用いられる。ネオスチグミンが神経筋接合部の伝達を改善する機序として正しいのはどれか。', '[{"key": "A", "text": "自己抗体の産生を抑える"}, {"key": "B", "text": "ナトリウムチャネルを開いて筋を直接脱分極させる"}, {"key": "C", "text": "アセチルコリンの分解を抑える"}, {"key": "D", "text": "アセチルコリン受容体の数を増やす"}, {"key": "E", "text": "神経終末からのアセチルコリンの放出を増やす"}]'::jsonb, 'C', 'ネオスチグミンやピリドスチグミンはアセチルコリンエステラーゼを可逆的に阻害し、シナプス間隙のアセチルコリンを増やして、減った受容体でも伝達が起こりやすくする。過量ではムスカリン作用による徐脈、下痢、分泌過多や、ニコチン作用による筋の脱力（コリン作動性クリーゼ）をきたす。ムスカリン作用を抑えるためにアトロピンを併用することがある。', '{"A": "免疫抑制薬や副腎皮質ステロイドの作用である。", "B": "ネオスチグミンの作用ではない。", "D": "受容体を増やす作用はない。", "E": "放出を増やすのはアミファンプリジンなどの作用である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'D2受容体遮断の副作用', 2, 'CBT', '統合失調症の治療でハロペリドールを内服している患者に、手指の振戦、筋強剛、動作の緩慢さが現れた。この副作用の原因として正しいのはどれか。', '[{"key": "A", "text": "視床下部のヒスタミンH1受容体の遮断"}, {"key": "B", "text": "末梢のムスカリン受容体の遮断"}, {"key": "C", "text": "末梢のα1受容体の遮断"}, {"key": "D", "text": "黒質線条体路のD2受容体遮断"}, {"key": "E", "text": "中脳辺縁系のセロトニン受容体の刺激"}]'::jsonb, 'D', '抗精神病薬は中脳辺縁系のD2受容体を遮断して幻覚や妄想を抑えるが、黒質線条体路の遮断で錐体外路症状（薬剤性パーキンソニズム、急性ジストニア、アカシジア、遅発性ジスキネジア）を、漏斗下垂体路の遮断で高プロラクチン血症を起こす。まれに高熱、筋強剛、意識障害、CK上昇を示す悪性症候群が起こる。第二世代の抗精神病薬は錐体外路症状が少ない。', '{"A": "眠気や体重増加の原因となる。", "B": "口渇や便秘、尿閉の原因となる。", "C": "起立性低血圧の原因となる。", "E": "この錐体外路症状の主な原因ではない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'ACE阻害薬の空咳', 2, 'CBT', '高血圧の治療でACE阻害薬を始めた患者が、痰を伴わない咳が続くと訴えた。ACE阻害薬で空咳が起こる機序として正しいのはどれか。', '[{"key": "A", "text": "アンジオテンシンIIが増えて気道が収縮する"}, {"key": "B", "text": "β2受容体が遮断されて気管支が収縮する"}, {"key": "C", "text": "ヒスタミンの産生が増えて気道が収縮する"}, {"key": "D", "text": "アルドステロンが増えて気道の粘膜が浮腫になる"}, {"key": "E", "text": "ブラジキニンの分解が抑えられる"}]'::jsonb, 'E', 'アンジオテンシン変換酵素は、アンジオテンシンIをIIに変えるとともに、ブラジキニンを分解する酵素（キニナーゼII）でもある。ACE阻害薬でブラジキニンなどが蓄積すると、空咳や、まれに血管性浮腫が起こる。咳が続く場合はブラジキニンの分解に影響しないアンジオテンシンII受容体拮抗薬に切り替える。高カリウム血症にも注意する。', '{"A": "ACE阻害薬ではアンジオテンシンIIは減る。", "B": "β遮断薬の作用で、ACE阻害薬の機序ではない。", "C": "ACE阻害薬の咳の主な機序ではない。", "D": "ACE阻害薬ではアルドステロンは減る。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'スタチンの作用', 2, 'CBT', '高LDLコレステロール血症の患者にスタチンを投与すると、血中のLDLコレステロールが大きく下がる。スタチンが血中のLDLを下げる機序として正しいのはどれか。', '[{"key": "A", "text": "肝のLDL受容体を増やす"}, {"key": "B", "text": "腸管でのコレステロールの吸収を阻害する"}, {"key": "C", "text": "胆汁酸と結合して便中への排泄を増やす"}, {"key": "D", "text": "リポ蛋白リパーゼを活性化して中性脂肪を分解する"}, {"key": "E", "text": "PCSK9に結合してLDL受容体の分解を防ぐ"}]'::jsonb, 'A', 'スタチンはコレステロール合成の律速酵素であるHMG-CoA還元酵素を競合的に阻害する。肝細胞内のコレステロールが減ると、転写因子SREBP2が活性化されてLDL受容体が増え、血中のLDLの取り込みが増える。副作用として筋肉痛やCKの上昇、まれに横紋筋融解症があり、フィブラート系やCYP3A4阻害薬との併用で起こりやすくなる。', '{"B": "エゼチミブの作用機序である。", "C": "陰イオン交換樹脂の作用機序である。", "D": "主にフィブラート系の作用である。", "E": "抗PCSK9抗体の作用機序である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '硝酸薬との併用禁忌', 2, 'CBT', '狭心症でニトログリセリンを使用している男性が、勃起障害の治療薬を希望した。硝酸薬との併用で過度の血圧低下を起こすため、併用が禁忌となる薬はどれか。', '[{"key": "A", "text": "メトホルミン"}, {"key": "B", "text": "シルデナフィル"}, {"key": "C", "text": "アムロジピン"}, {"key": "D", "text": "アスピリン"}, {"key": "E", "text": "アトルバスタチン"}]'::jsonb, 'B', '硝酸薬は一酸化窒素を放出してcGMPを増やし、血管平滑筋を弛緩させる。シルデナフィルなどのホスホジエステラーゼ5阻害薬はcGMPの分解を抑えるため、併用するとcGMPが過剰にたまって重い血圧低下をきたす。そのため併用は禁忌である。ホスホジエステラーゼ5阻害薬は肺動脈性肺高血圧症の治療にも用いられる。', '{"A": "糖尿病の治療薬で、硝酸薬との併用は問題とならない。", "C": "併用で血圧は下がりうるが、禁忌とはされていない。", "D": "抗血小板薬で、硝酸薬との併用は一般的である。", "E": "脂質異常症の治療薬で、硝酸薬との併用は問題とならない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'ジゴキシン', 2, 'CBT', '心房細動の心拍数の調節にジゴキシンを使っている高齢者で、食欲不振、悪心、視覚異常が出現した。ジゴキシンの作用機序と中毒について正しいのはどれか。', '[{"key": "A", "text": "ホスホジエステラーゼ3を阻害し、cAMPを増やす"}, {"key": "B", "text": "カリウムチャネルを遮断し、活動電位を延長させる"}, {"key": "C", "text": "Na+,K+-ATPaseを阻害し、低K血症で中毒しやすい"}, {"key": "D", "text": "β1受容体を直接刺激し、高カリウム血症で中毒が起こりやすくなる"}, {"key": "E", "text": "L型カルシウムチャネルを遮断し、心筋の収縮力を下げる"}]'::jsonb, 'C', 'ジゴキシンは心筋のNa+,K+-ATPaseを阻害して細胞内ナトリウムを増やし、Na+/Ca2+交換を介して細胞内カルシウムを増やして収縮力を高める。迷走神経の緊張を高めて房室伝導を遅らせる作用もある。ジゴキシンはカリウムと結合部位を競合するため、低カリウム血症では作用が強まって中毒が起こりやすい。腎機能の低下や高齢も中毒の危険因子である。', '{"A": "ミルリノンなどの作用である。", "B": "アミオダロンなどのⅢ群抗不整脈薬の作用である。", "D": "ジゴキシンはβ1受容体を刺激しない。", "E": "カルシウム拮抗薬の作用である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'サイアザイド系とカルシウム', 2, 'CBT', 'カルシウム結石を繰り返す患者や骨粗鬆症の患者では、尿中へのカルシウムの排泄を減らす利尿薬が役立つことがある。尿中へのカルシウムの排泄を減らす利尿薬はどれか。', '[{"key": "A", "text": "炭酸脱水酵素阻害薬"}, {"key": "B", "text": "浸透圧利尿薬"}, {"key": "C", "text": "バソプレシンV2受容体拮抗薬"}, {"key": "D", "text": "サイアザイド系利尿薬"}, {"key": "E", "text": "ループ利尿薬"}]'::jsonb, 'D', 'サイアザイド系利尿薬は遠位曲尿細管のNa+-Cl-共輸送体を阻害する。細胞内のナトリウムが減ると基底側膜のNa+/Ca2+交換が進み、カルシウムの再吸収が増えて尿中への排泄が減る。そのためカルシウム結石の予防に使われる一方、高カルシウム血症をきたすことがある。低ナトリウム血症、低カリウム血症、高尿酸血症、耐糖能の悪化にも注意する。', '{"A": "尿をアルカリ化してリン酸カルシウム結石の危険を高める。", "B": "カルシウムの排泄を減らす作用はない。", "C": "水だけを排泄させる薬で、カルシウムの排泄を減らす作用はない。", "E": "Henleループでのカルシウムの再吸収を減らし、尿中への排泄を増やす。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'スピロノラクトンの副作用', 2, 'CBT', '心不全の患者にスピロノラクトンを追加したところ、血清カリウム値が上昇し、男性では乳房の腫大も現れた。スピロノラクトンの作用機序として正しいのはどれか。', '[{"key": "A", "text": "Na+-K+-2Cl-共輸送体を阻害する"}, {"key": "B", "text": "Na+-Cl-共輸送体を阻害する"}, {"key": "C", "text": "炭酸脱水酵素を阻害する"}, {"key": "D", "text": "バソプレシンV2受容体を遮断する"}, {"key": "E", "text": "鉱質コルチコイド受容体を遮断する"}]'::jsonb, 'E', 'スピロノラクトンは集合管の鉱質コルチコイド受容体でアルドステロンと競合し、ナトリウムの再吸収とカリウムの分泌を抑える。カリウムを体内に保つため、腎機能障害やACE阻害薬、ARBとの併用では高カリウム血症に注意する。アンドロゲン受容体も遮断するため、女性化乳房や月経異常をきたしうる。選択性の高いエプレレノンではこの副作用が少ない。心不全や原発性アルドステロン症の治療に用いる。', '{"A": "ループ利尿薬の作用機序である。", "B": "サイアザイド系利尿薬の作用機序である。", "C": "アセタゾラミドの作用機序である。", "D": "トルバプタンの作用機序である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'ワルファリンと食品', 2, 'CBT', 'ワルファリンを内服している患者に、食事について指導している。ワルファリンの効果を弱めるため、摂取を控えるよう指導する食品はどれか。', '[{"key": "A", "text": "納豆"}, {"key": "B", "text": "グレープフルーツ"}, {"key": "C", "text": "牛乳"}, {"key": "D", "text": "白米"}, {"key": "E", "text": "緑茶を少量飲むこと"}]'::jsonb, 'A', 'ワルファリンはビタミンKエポキシド還元酵素を阻害し、ビタミンK依存性凝固因子の産生を抑える。納豆は納豆菌が腸内でビタミンK2を産生し続けるため、少量でもワルファリンの効果を大きく弱める。クロレラや青汁も控える。緑黄色野菜は極端に増減させず一定量をとるよう指導する。効果はPT-INRで評価し、過量で出血したときはビタミンKを投与する。', '{"B": "主にCYP3A4で代謝される薬の濃度を上げるが、ワルファリンへの影響は小さい。", "C": "一部の抗菌薬の吸収を妨げるが、ワルファリンの効果を弱める食品ではない。", "D": "ワルファリンの効果に影響しない。", "E": "通常の量では効果に大きく影響しない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '直接経口抗凝固薬', 2, 'CBT', '非弁膜症性心房細動の患者の脳梗塞予防に、ワルファリンに代わって直接経口抗凝固薬が広く用いられる。第Xa因子を直接阻害する薬はどれか。', '[{"key": "A", "text": "クロピドグレル"}, {"key": "B", "text": "アピキサバン"}, {"key": "C", "text": "ダビガトラン"}, {"key": "D", "text": "ワルファリン"}, {"key": "E", "text": "ヘパリン"}]'::jsonb, 'B', 'リバーロキサバン、アピキサバン、エドキサバンは活性化第X因子を、ダビガトランはトロンビンを直接阻害する。ワルファリンと比べて食事の影響が少なく、効果の発現と消失が速く、定期的な凝固検査による調節が要らない。一方で、腎機能に応じた用量の調節が必要で、機械弁置換後や中等度以上の僧帽弁狭窄症の患者には用いない。', '{"A": "ADP受容体を遮断する抗血小板薬である。", "C": "トロンビンを直接阻害する経口抗凝固薬である。", "D": "ビタミンK依存性凝固因子の産生を抑える薬である。", "E": "アンチトロンビンを介して作用する注射薬である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '低用量アスピリン', 2, 'CBT', '心筋梗塞の再発予防に、低用量のアスピリンが用いられる。低用量アスピリンが血小板の凝集を抑える機序として正しいのはどれか。', '[{"key": "A", "text": "ビタミンK依存性凝固因子の産生を抑える"}, {"key": "B", "text": "ホスホジエステラーゼ3を阻害してcAMPを増やす"}, {"key": "C", "text": "COXを不可逆的に阻害しTXA2を減らす"}, {"key": "D", "text": "血小板のADP受容体を不可逆的に遮断する"}, {"key": "E", "text": "血小板膜のGPIIb/IIIaを遮断する"}]'::jsonb, 'C', 'アスピリンはシクロオキシゲナーゼ（主にCOX-1）をアセチル化して不可逆的に阻害する。核のない血小板は酵素を新たにつくれないため、その寿命（7〜10日）の間ずっとトロンボキサンA2の産生が抑えられる。血管内皮は酵素を再合成できるため、低用量ではプロスタサイクリンの産生は比較的保たれる。手術の前には出血の危険を考えて休薬を検討する。', '{"A": "ワルファリンの作用機序である。", "B": "シロスタゾールの作用機序である。", "D": "クロピドグレルなどの作用機序である。", "E": "静注の抗血小板薬の作用機序である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'クロピドグレル', 2, 'CBT', '冠動脈ステント留置後の患者では、アスピリンに加えてADP受容体の遮断薬を併用する。クロピドグレルについて正しいのはどれか。', '[{"key": "A", "text": "トロンビンを直接阻害する"}, {"key": "B", "text": "血小板のシクロオキシゲナーゼを阻害する"}, {"key": "C", "text": "凝固因子の産生を抑える"}, {"key": "D", "text": "プロドラッグで、P2Y12受容体を不可逆的に遮断する"}, {"key": "E", "text": "そのままの形で活性をもち、肝での代謝をまったく受けない"}]'::jsonb, 'D', 'クロピドグレルはプロドラッグで、肝のCYP2C19などで活性代謝物となり、血小板のADP受容体（P2Y12）を不可逆的に遮断して凝集を抑える。CYP2C19の活性が遺伝的に低い人（日本人に多い）では効果が弱まることがある。プラスグレルやチカグレロルは代謝の影響を受けにくい。ステント留置後は、ステント血栓症を防ぐため一定期間アスピリンと併用する（抗血小板薬2剤併用療法）。', '{"A": "ダビガトランの作用機序である。", "B": "アスピリンの作用機序である。", "C": "ワルファリンの作用機序である。", "E": "プロドラッグで、肝のCYP2C19などで活性体となる。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'β-ラクタム系の作用機序', 2, 'CBT', 'ペニシリン系やセファロスポリン系の抗菌薬は、増殖中の細菌に対して殺菌的に作用する。β-ラクタム系抗菌薬の作用機序として正しいのはどれか。', '[{"key": "A", "text": "リボソームの30Sサブユニットに結合して蛋白質の合成を阻害する"}, {"key": "B", "text": "DNAジャイレースを阻害してDNAの複製を妨げる"}, {"key": "C", "text": "葉酸の合成を阻害する"}, {"key": "D", "text": "細胞膜のエルゴステロールに結合する"}, {"key": "E", "text": "ペニシリン結合蛋白に結合して細胞壁の合成を阻害する"}]'::jsonb, 'E', 'β-ラクタム系はペニシリン結合蛋白（ペプチドグリカンの架橋を行うトランスペプチダーゼなど）に結合し、細胞壁の合成を妨げて細菌を溶かす。ヒトの細胞には細胞壁がないため選択毒性が高い。β-ラクタマーゼによる分解、ペニシリン結合蛋白の変化、外膜の透過性の低下が耐性の主な機序である。アナフィラキシーなどのアレルギーに注意する。', '{"A": "アミノグリコシド系やテトラサイクリン系の作用機序である。", "B": "キノロン系の作用機序である。", "C": "サルファ剤やトリメトプリムの作用機序である。", "D": "アムホテリシンBの作用機序で、真菌に作用する。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'アミノグリコシド系', 2, 'CBT', '緑膿菌による重症感染症の治療で、アミノグリコシド系抗菌薬を併用することになった。アミノグリコシド系抗菌薬の作用機序と主な副作用の組合せとして正しいのはどれか。', '[{"key": "A", "text": "30Sの阻害 — 腎障害と聴器障害"}, {"key": "B", "text": "50Sリボソームの阻害 — QT延長"}, {"key": "C", "text": "細胞壁の合成阻害 — アナフィラキシー"}, {"key": "D", "text": "DNAジャイレースの阻害 — アキレス腱障害"}, {"key": "E", "text": "葉酸の合成阻害 — 高カリウム血症"}]'::jsonb, 'A', 'アミノグリコシド系は30Sリボソームに結合して蛋白質の合成を妨げ、濃度依存的に殺菌作用を示す。好気性のグラム陰性桿菌に強く、嫌気性菌には効かない。腎の近位尿細管と内耳の有毛細胞に蓄積しやすく、腎障害と、しばしば不可逆な聴力障害や平衡障害をきたす。1日1回の投与と血中濃度の測定で副作用を減らす。神経筋遮断作用もある。', '{"B": "主にマクロライド系の組合せである。", "C": "主にβ-ラクタム系の組合せである。", "D": "キノロン系の組合せである。", "E": "スルファメトキサゾール・トリメトプリム（ST合剤）の組合せである。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'マクロライド系', 2, 'CBT', 'マイコプラズマ肺炎の治療にクラリスロマイシンを使うときは、併用薬との相互作用に注意する。マクロライド系抗菌薬の作用機序として正しいのはどれか。', '[{"key": "A", "text": "細菌の細胞膜に孔をあける"}, {"key": "B", "text": "50Sサブユニットに結合する"}, {"key": "C", "text": "ペニシリン結合蛋白に結合して細胞壁の合成を阻害する"}, {"key": "D", "text": "細胞壁の前駆体のD-Ala-D-Alaに結合する"}, {"key": "E", "text": "DNAジャイレースを阻害してDNAの複製を妨げる"}]'::jsonb, 'B', 'マクロライド系は50Sサブユニットに結合してペプチド鎖の伸長を妨げ、主に静菌的に作用する。細胞内への移行がよく、マイコプラズマ、クラミジア、レジオネラなどに有効である。クラリスロマイシンやエリスロマイシンはCYP3A4を阻害して併用薬の血中濃度を上げる。QT延長にも注意する。ヘリコバクター・ピロリの除菌にも用いられる。', '{"A": "ポリミキシンやダプトマイシンなどの作用に近い。", "C": "β-ラクタム系の作用機序である。", "D": "バンコマイシンの作用機序である。", "E": "キノロン系の作用機序である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'キノロン系', 2, 'CBT', '高齢者の尿路感染症にニューキノロン系抗菌薬を処方する。キノロン系抗菌薬について正しいのはどれか。', '[{"key": "A", "text": "小児では骨の成長を促すため積極的に使う"}, {"key": "B", "text": "腱の障害を起こすことはない"}, {"key": "C", "text": "DNAジャイレースとトポイソメラーゼIVを阻害する"}, {"key": "D", "text": "30Sリボソームに結合して蛋白質の合成を阻害する"}, {"key": "E", "text": "マグネシウムやアルミニウムを含む制酸薬と同時に内服すると吸収が増える"}]'::jsonb, 'C', 'キノロン系は細菌のII型トポイソメラーゼであるDNAジャイレースとトポイソメラーゼIVを阻害し、DNAの複製を妨げて殺菌的に作用する。経口での吸収がよいが、マグネシウム、アルミニウム、鉄、カルシウムを含む製剤と同時に内服するとキレートをつくって吸収が落ちる。副作用として腱障害、QT延長、けいれん（NSAIDsとの併用で増える）、血糖異常がある。', '{"A": "動物実験で関節軟骨の障害がみられ、小児では使用が制限される。", "B": "アキレス腱炎や腱断裂を起こすことがあり、高齢者やステロイド併用で起こりやすい。", "D": "アミノグリコシド系などの作用機序である。", "E": "金属イオンとキレートをつくり、吸収が低下する。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'バンコマイシン', 2, 'CBT', 'MRSAによる菌血症の治療にバンコマイシンを用いる。バンコマイシンの作用機序として正しいのはどれか。', '[{"key": "A", "text": "リボソームの30Sサブユニットに結合する"}, {"key": "B", "text": "DNAジャイレースを阻害する"}, {"key": "C", "text": "細菌の葉酸合成を阻害する"}, {"key": "D", "text": "D-Ala-D-Ala末端に結合する"}, {"key": "E", "text": "ペニシリン結合蛋白に結合してペプチドグリカンの架橋を阻害する"}]'::jsonb, 'D', 'バンコマイシンはグリコペプチド系で、細胞壁の前駆体のペプチド末端D-Ala-D-Alaに結合して、ペプチドグリカンの合成を妨げる。分子が大きく外膜を通れないため、グラム陰性菌には効かない。経口ではほとんど吸収されないため、クロストリディオイデス・ディフィシル腸炎には経口で用いる。腎障害や、急速に点滴すると顔や上半身の紅潮（red man症候群）が起こる。血中濃度を測定して投与量を調節する。', '{"A": "アミノグリコシド系などの作用機序である。", "B": "キノロン系の作用機序である。", "C": "ST合剤の作用機序である。", "E": "β-ラクタム系の作用機序で、MRSAにはこの薬が効かない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'テトラサイクリン系', 2, 'CBT', '8歳未満の小児や妊婦には、原則としてテトラサイクリン系抗菌薬を使わない。その理由として正しいのはどれか。', '[{"key": "A", "text": "腎の尿細管に沈着して尿路結石を多発させる"}, {"key": "B", "text": "胎盤を通過せず、胎児の感染症に効かない"}, {"key": "C", "text": "小児では腸管から吸収されない"}, {"key": "D", "text": "網膜に沈着して視力障害を起こす"}, {"key": "E", "text": "歯や骨に沈着して歯を着色させる"}]'::jsonb, 'E', 'テトラサイクリン系は30Sサブユニットに結合して蛋白質の合成を妨げる静菌的な抗菌薬で、リケッチア、クラミジア、マイコプラズマなどに有効である。カルシウムと結合しやすく、発育中の歯や骨に沈着して歯の着色やエナメル質の形成不全を起こす。カルシウム、マグネシウム、鉄と同時に内服すると吸収が落ちる。光線過敏症にも注意する。', '{"A": "テトラサイクリン系を避ける主な理由ではない。", "B": "胎盤を通過し、胎児の歯や骨に沈着する。", "C": "吸収されるため、歯や骨に沈着する。", "D": "テトラサイクリン系を避ける主な理由ではない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'メトロニダゾール', 2, 'CBT', '嫌気性菌による腹腔内膿瘍や、アメーバ赤痢、腟トリコモナス症の治療に同じ薬が用いられる。この薬を内服中に飲酒すると、顔面紅潮、動悸、悪心などが起こることがある。この薬はどれか。', '[{"key": "A", "text": "メトロニダゾール"}, {"key": "B", "text": "アンピシリン"}, {"key": "C", "text": "レボフロキサシン"}, {"key": "D", "text": "ゲンタマイシン"}, {"key": "E", "text": "アジスロマイシン"}]'::jsonb, 'A', 'メトロニダゾールは嫌気性菌や原虫の中で還元されて活性化し、DNAを傷つけて殺菌的に作用する。バクテロイデスなどの嫌気性菌、クロストリディオイデス・ディフィシル、赤痢アメーバ、ランブル鞭毛虫、腟トリコモナスに有効で、ヘリコバクター・ピロリの二次除菌にも用いる。飲酒でジスルフィラム様の反応が起こることがあるため、服用中と服用後しばらくは飲酒を避ける。長期投与では末梢神経障害に注意する。', '{"B": "嫌気性菌の一部に効くが、原虫には効かない。", "C": "原虫には効かず、飲酒による特有の反応も典型ではない。", "D": "嫌気性菌には効かない。", "E": "原虫の治療薬ではなく、飲酒による特有の反応も典型ではない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'ホリナートによる救援', 2, 'CBT', '骨肉腫に対するメトトレキサートの大量療法では、投与の一定時間後にホリナート（ロイコボリン）を投与する。ホリナートを投与する目的として正しいのはどれか。', '[{"key": "A", "text": "メトトレキサートを活性型に変える"}, {"key": "B", "text": "葉酸の代謝の阻害による正常細胞の障害を救う"}, {"key": "C", "text": "メトトレキサートの腎からの排泄を止める"}, {"key": "D", "text": "腫瘍細胞へのメトトレキサートの取り込みを増やす"}, {"key": "E", "text": "メトトレキサートによる悪心を抑える"}]'::jsonb, 'B', 'メトトレキサートはジヒドロ葉酸還元酵素を阻害してテトラヒドロ葉酸を枯渇させ、DNA合成を妨げる。ホリナートは還元型の葉酸で、この酵素を経ずに一炭素単位の代謝に入れるため、正常細胞の障害（骨髄抑制、粘膜炎、肝障害）を救う（ロイコボリン救援療法）。大量療法では尿をアルカリ化して十分に輸液し、血中濃度を測定しながら投与する。', '{"A": "メトトレキサートは活性化を必要としない。", "C": "排泄はむしろ促す必要があり、ホリナートの目的ではない。", "D": "ホリナートの目的ではない。", "E": "制吐薬の目的で、ホリナートの目的ではない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'シスプラチン', 2, 'CBT', '肺癌や精巣腫瘍の治療に用いられるシスプラチンでは、大量の輸液を行いながら投与する。シスプラチンで特に注意すべき有害作用はどれか。', '[{"key": "A", "text": "肺線維症"}, {"key": "B", "text": "末梢神経障害だけで、腎への影響はない"}, {"key": "C", "text": "腎障害"}, {"key": "D", "text": "出血性膀胱炎"}, {"key": "E", "text": "心筋障害"}]'::jsonb, 'C', 'シスプラチンはDNAに結合して鎖の間や鎖の中に架橋をつくり、DNAの複製を妨げる白金製剤である。腎の近位尿細管を傷害するため、大量の輸液と利尿で尿中の濃度を下げて投与する。強い悪心・嘔吐が起こるため、5-HT3受容体拮抗薬やNK1受容体拮抗薬を予防的に使う。聴力障害、末梢神経障害、低マグネシウム血症にも注意する。', '{"A": "主にブレオマイシンで問題となる有害作用である。", "B": "末梢神経障害も起こるが、腎障害が特に問題となる。", "D": "シクロホスファミドやイホスファミドで起こる有害作用である。", "E": "主にアントラサイクリン系で問題となる有害作用である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'イマチニブ', 2, 'CBT', '慢性骨髄性白血病の治療は、分子標的薬の登場で大きく変わった。イマチニブが標的とする分子はどれか。', '[{"key": "A", "text": "HER2（ヒト上皮成長因子受容体2）"}, {"key": "B", "text": "血管内皮増殖因子（VEGF）"}, {"key": "C", "text": "PD-1"}, {"key": "D", "text": "BCR-ABLチロシンキナーゼ"}, {"key": "E", "text": "CD20抗原"}]'::jsonb, 'D', '慢性骨髄性白血病では、9番と22番染色体の転座でできたフィラデルフィア染色体上にBCR-ABL融合遺伝子が生じ、常に活性化したチロシンキナーゼが造血細胞を増殖させる。イマチニブはこのキナーゼのATP結合部位に結合して活性を抑える。KITも阻害するため消化管間質腫瘍にも有効である。耐性例には第二世代以降の阻害薬を用いる。', '{"A": "トラスツズマブなどの標的で、乳癌や胃癌に用いる。", "B": "ベバシズマブの標的である。", "C": "ニボルマブなどの免疫チェックポイント阻害薬の標的である。", "E": "リツキシマブの標的で、B細胞リンパ腫に用いる。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'ステロイドの急な中止', 2, 'CBT', '関節リウマチで数か月間プレドニゾロンを内服していた患者が、自己判断で内服を中止した。数日後に倦怠感、食欲不振、低血圧、低血糖が出現した。この病態の主な機序はどれか。', '[{"key": "A", "text": "副腎髄質のカテコラミンが過剰に分泌されている"}, {"key": "B", "text": "アルドステロンの過剰でナトリウムが貯留している"}, {"key": "C", "text": "リウマチの再燃で炎症性サイトカインが増えただけである"}, {"key": "D", "text": "甲状腺ホルモンの過剰で代謝が亢進している"}, {"key": "E", "text": "視床下部-下垂体-副腎系の抑制による副腎不全"}]'::jsonb, 'E', '副腎皮質ステロイドを長く使うと、負のフィードバックでCRHとACTHの分泌が抑えられ、副腎皮質が萎縮する。急に中止すると自らコルチゾールを十分に分泌できず、副腎不全（ステロイド離脱症候群）となる。長期投与後は時間をかけて減量し、手術や感染症などの強いストレスがかかるときは一時的に増量する（ステロイドカバー）。', '{"A": "この病態の主な機序ではない。", "B": "低血圧の機序と合わない。", "C": "低血糖や低血圧を伴う副腎不全の機序を説明できない。", "D": "この病態の主な機序ではない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '第一世代抗ヒスタミン薬', 2, 'CBT', '花粉症の治療でジフェンヒドラミンを内服した人が、強い眠気のため運転を控えるよう指導された。第一世代の抗ヒスタミン薬で眠気が強く出る理由として正しいのはどれか。', '[{"key": "A", "text": "脳のH1受容体を遮断するから"}, {"key": "B", "text": "末梢の血管のH1受容体だけを強く遮断するから"}, {"key": "C", "text": "胃のH2受容体を遮断するから"}, {"key": "D", "text": "脳のヒスタミンの産生を増やすから"}, {"key": "E", "text": "肝で代謝されずに血中濃度が高くなるから"}]'::jsonb, 'A', '脳内のヒスタミン神経系は覚醒の維持に働いている。脂溶性の高い第一世代の抗ヒスタミン薬は血液脳関門を通過して脳のH1受容体を遮断するため、眠気や集中力の低下を起こし、抗コリン作用による口渇や尿閉もある。第二世代の抗ヒスタミン薬は脳に移行しにくく、眠気が少ない。高齢者や緑内障、前立腺肥大症の患者では第一世代を避ける。', '{"B": "末梢での作用では眠気は説明できない。", "C": "H2受容体の遮断は胃酸の分泌を抑える作用である。", "D": "産生を増やすわけではなく、受容体を遮断する。", "E": "眠気の主な理由ではない。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'オピオイドの便秘', 2, 'CBT', '癌性疼痛に対してモルヒネを開始するときは、ある副作用に対する薬を最初から併用する。モルヒネを続けてもほとんど耐性が生じず、予防的な対策が必要な副作用はどれか。', '[{"key": "A", "text": "縮瞳"}, {"key": "B", "text": "便秘"}, {"key": "C", "text": "悪心・嘔吐"}, {"key": "D", "text": "眠気"}, {"key": "E", "text": "呼吸抑制"}]'::jsonb, 'B', 'オピオイドは腸管のμ受容体に作用して蠕動を抑え、分泌を減らすため、ほぼ全例で便秘が起こり、耐性がほとんど生じない。そのため開始時から緩下薬や末梢性μ受容体拮抗薬を併用する。悪心・嘔吐や眠気は数日から1週間ほどで軽くなることが多い。過量による呼吸抑制にはナロキソンで拮抗する。', '{"A": "耐性は生じにくいが、治療上の対策を要する副作用ではない。", "C": "投与の初期に多いが、数日〜1週間ほどで耐性が生じて軽くなることが多い。", "D": "投与の初期や増量時に多いが、耐性が生じて軽くなることが多い。", "E": "痛みがあるうちは起こりにくく、適切な増量では耐性も生じる。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'ベンゾジアゼピン系', 2, 'CBT', '不眠や不安の治療に広く使われるベンゾジアゼピン系薬は、特定の受容体の働きを強める。ベンゾジアゼピン系薬の作用機序として正しいのはどれか。', '[{"key": "A", "text": "セロトニンの再取り込みを阻害する"}, {"key": "B", "text": "ドパミンD2受容体を遮断する"}, {"key": "C", "text": "GABAA受容体の働きを強める"}, {"key": "D", "text": "GABAの再取り込みを阻害する"}, {"key": "E", "text": "グルタミン酸NMDA受容体を遮断する"}]'::jsonb, 'C', 'ベンゾジアゼピン系薬はGABAA受容体のベンゾジアゼピン結合部位に結合し、GABAが結合したときの塩化物イオンチャネルの開口頻度を高めて抑制を強める。GABAがないと単独ではほとんど作用しないため、単独の過量では比較的安全だが、アルコールなどと併用すると呼吸抑制が起こりうる。依存、離脱症状、高齢者での転倒やせん妄に注意し、過量にはフルマゼニルで拮抗する。', '{"A": "SSRIの作用機序である。", "B": "抗精神病薬の作用機序である。", "D": "ベンゾジアゼピン系薬の作用機序ではない。", "E": "ケタミンやメマンチンなどの作用機序である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', 'SSRIの作用機序', 2, 'CBT', 'うつ病の治療で、選択的セロトニン再取り込み阻害薬（SSRI）を開始した。SSRIが抗うつ効果を示す機序として正しいのはどれか。', '[{"key": "A", "text": "ドパミンD2受容体を遮断する"}, {"key": "B", "text": "セロトニンの合成酵素を活性化する"}, {"key": "C", "text": "ノルアドレナリンの放出を抑える"}, {"key": "D", "text": "セロトニンの再取り込みを阻害する"}, {"key": "E", "text": "モノアミン酸化酵素を阻害してセロトニンの分解を抑える"}]'::jsonb, 'D', 'SSRIは神経終末のセロトニントランスポーターを選択的に阻害し、シナプス間隙のセロトニンを増やす。効果が現れるまで2〜4週間かかる一方、悪心などの副作用は早く出るため、あらかじめ説明する。若年者では投与初期に不安や焦燥が強まる（賦活症候群）ことがある。他のセロトニン作動薬との併用では、発熱、ミオクローヌス、自律神経症状を示すセロトニン症候群に注意する。三環系抗うつ薬と比べて抗コリン作用や心毒性が少ない。', '{"A": "抗精神病薬の作用機序である。", "B": "SSRIの作用機序ではない。", "C": "抗うつ効果の機序とは逆の方向である。", "E": "モノアミン酸化酵素阻害薬の作用機序である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '第I相臨床試験', 2, 'CBT', '新しい医薬品は、非臨床試験のあと、段階を追った臨床試験（治験）を経て承認される。第I相試験の主な目的として正しいのはどれか。', '[{"key": "A", "text": "多数の患者で既存の治療と有効性を比較する"}, {"key": "B", "text": "少数の患者で有効性と適切な用量を探る"}, {"key": "C", "text": "市販後に多数の使用者でまれな副作用を調べる"}, {"key": "D", "text": "動物で毒性と薬理作用を調べる"}, {"key": "E", "text": "健康な成人で安全性と薬物動態を調べる"}]'::jsonb, 'E', '第I相試験は主に少数の健康な成人（抗癌薬では患者）を対象に、安全性、忍容性、薬物動態を調べる。第II相試験では少数の患者で有効性と用量を探り、第III相試験では多数の患者で既存の治療やプラセボと比較して有効性と安全性を確かめる。承認後も市販後調査でまれな副作用や長期の安全性を監視する。治験は被験者の自由意思による同意（インフォームドコンセント）と倫理審査委員会の承認のもとで行う。', '{"A": "第III相試験の主な目的である。", "B": "第II相試験の主な目的である。", "C": "第IV相（市販後）の調査の目的である。", "D": "ヒトでの臨床試験の前に行う非臨床試験の目的である。"}'::jsonb, 'public', 'M', 'C-3', '', 'pending', 'llm'),
('基礎医学', '虚血による細胞の膨化', 2, 'CBT', '虚血になった細胞では、まずATPが減少し、光学顕微鏡で細胞が腫れて見える変化が起こる。この細胞の膨化が起こる主な機序として正しいのはどれか。', '[{"key": "A", "text": "ナトリウムポンプの働きが落ち、細胞内にナトリウムと水がたまる"}, {"key": "B", "text": "細胞膜が破れて細胞外の蛋白質が流れ込む"}, {"key": "C", "text": "核が凝縮して細胞質の水分が増える"}, {"key": "D", "text": "カリウムが細胞内に大量に流れ込む"}, {"key": "E", "text": "ミトコンドリアでのATPの産生が増え、その代謝水が細胞内にたまる"}]'::jsonb, 'A', '酸素が不足すると酸化的リン酸化が止まってATPが減り、ナトリウムポンプが働かなくなる。細胞内にナトリウムがたまり、浸透圧に従って水が入って細胞と小胞体が膨化する（水腫変性）。嫌気的解糖で乳酸が増えてpHが下がり、リボソームが小胞体から離れて蛋白質の合成も落ちる。ここまでは血流が戻れば回復しうる可逆的な変化である。', '{"B": "膜の破綻は不可逆的な傷害の段階で、膨化の最初の機序ではない。", "C": "核の凝縮は不可逆的な傷害の所見で、膨化の機序ではない。", "D": "カリウムはむしろ細胞外へ失われる。", "E": "虚血ではATPの産生は低下する。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '不可逆的細胞傷害の所見', 2, 'CBT', '細胞傷害が一定の段階を超えると、血流が戻っても細胞は回復せず壊死に至る。不可逆的な細胞傷害を示す所見はどれか。', '[{"key": "A", "text": "細胞質内の小さな脂肪滴"}, {"key": "B", "text": "核濃縮、核崩壊、核融解などの核の変化"}, {"key": "C", "text": "細胞の膨化"}, {"key": "D", "text": "細胞膜の小さな突出（ブレブ）"}, {"key": "E", "text": "粗面小胞体の拡張と、リボソームの小胞体からの離脱"}]'::jsonb, 'B', '不可逆的な傷害では、ミトコンドリアの高度の障害（内部の無定形の高密度体）、細胞膜やリソソーム膜の破綻、核の変化（核濃縮、核崩壊、核融解）が起こる。膜が破れると細胞内の酵素が血中に漏れ出るため、心筋トロポニンやCK、ASTなどの上昇が細胞の壊死を示す指標となる。', '{"A": "可逆的な傷害でもみられる脂肪変性の所見である。", "C": "ナトリウムと水の貯留による変化で、可逆的な段階でもみられる。", "D": "可逆的な段階でもみられる。", "E": "可逆的な段階でみられる変化である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '心筋梗塞の壊死', 2, 'CBT', '急性心筋梗塞で亡くなった患者の心臓を調べると、梗塞部の心筋細胞は核が消失しているが、細胞の輪郭と組織の構造は数日間保たれていた。この壊死の型はどれか。', '[{"key": "A", "text": "脂肪壊死"}, {"key": "B", "text": "フィブリノイド壊死"}, {"key": "C", "text": "凝固壊死"}, {"key": "D", "text": "融解壊死"}, {"key": "E", "text": "乾酪壊死"}]'::jsonb, 'C', '凝固壊死は虚血による壊死の多くでみられる型で、細胞の蛋白質が変性して酵素も失活するため、細胞の輪郭と組織の構造がしばらく保たれる。心臓、腎臓、脾臓などの梗塞でみられる。脳は脂質に富み蛋白質が少なく、酵素による融解が進むため、梗塞は融解壊死となる。壊死巣はのちにマクロファージで除去され、肉芽組織を経て瘢痕となる。', '{"A": "脂肪組織が脂肪分解酵素で壊れる壊死で、急性膵炎にみられる。", "B": "血管壁にフィブリンなどが沈着する壊死で、血管炎や悪性高血圧にみられる。", "D": "組織が酵素で溶けて液状になる壊死で、脳梗塞や膿瘍にみられる。", "E": "チーズ様の無構造な壊死で、結核にみられる。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '脂肪壊死', 2, 'CBT', '急性膵炎で開腹した患者の腸間膜や大網に、白色でチョーク様の小さな斑点が多数みられた。この斑点ができる機序として正しいのはどれか。', '[{"key": "A", "text": "アミロイドが脂肪組織に沈着する"}, {"key": "B", "text": "尿酸塩の結晶が析出する"}, {"key": "C", "text": "コレステロールが脂肪組織に蓄積する"}, {"key": "D", "text": "膵リパーゼで生じた脂肪酸がカルシウムと結合する"}, {"key": "E", "text": "結核菌による乾酪壊死の小さな病巣が腹膜に多数散在する"}]'::jsonb, 'D', '急性膵炎では膵臓から漏れ出たリパーゼが周囲の脂肪組織のトリアシルグリセロールを分解し、生じた脂肪酸がカルシウムと結合して石鹸のような沈着物をつくる（鹸化）。肉眼では白色でチョーク様の斑点として見える（酵素的脂肪壊死）。カルシウムが消費されるため、重症の急性膵炎では低カルシウム血症をきたすことがある。乳房の外傷後には外傷性の脂肪壊死が起こり、腫瘤として触れることがある。', '{"A": "アミロイドーシスの所見で、この斑点の成因ではない。", "B": "痛風の病変でみられる。", "C": "この斑点の成因ではない。", "E": "結核の病変で、急性膵炎とは関係しない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'フィブリノイド壊死', 2, 'CBT', '拡張期血圧が130mmHgを超える悪性高血圧の患者で、腎の細動脈の壁が好酸性に染まる無構造な物質に置き換わっていた。この血管壁の変化はどれか。', '[{"key": "A", "text": "硝子様細動脈硬化"}, {"key": "B", "text": "乾酪壊死"}, {"key": "C", "text": "粥状硬化"}, {"key": "D", "text": "アミロイド沈着"}, {"key": "E", "text": "フィブリノイド壊死"}]'::jsonb, 'E', 'フィブリノイド壊死は、血管壁が傷害されて血漿蛋白が漏れ出し、フィブリンを含む好酸性で無構造な物質が沈着した状態である。悪性高血圧の細動脈、結節性多発動脈炎などの血管炎、全身性エリテマトーデスなどでみられる。悪性高血圧では細動脈の内膜が同心円状に増殖する（玉ねぎ状病変）こともあり、腎不全が急速に進む。', '{"A": "長年の高血圧や糖尿病でみられる、ゆっくり進む細動脈壁の均質な肥厚である。", "B": "結核の肉芽腫の中心にみられる壊死である。", "C": "大・中型の弾性・筋型動脈の内膜に起こる変化である。", "D": "Congo red染色で陽性となる線維状の蛋白質の沈着である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '脂肪肝で蓄積する脂質', 2, 'CBT', '大量飲酒を続けている患者の肝生検で、肝細胞の細胞質に大きな空胞が生じて核が端に押しやられていた。この空胞に蓄積している脂質はどれか。', '[{"key": "A", "text": "トリアシルグリセロール"}, {"key": "B", "text": "コレステロールエステル"}, {"key": "C", "text": "スフィンゴ糖脂質"}, {"key": "D", "text": "リン脂質"}, {"key": "E", "text": "リポフスチン"}]'::jsonb, 'A', '脂肪肝では肝細胞にトリアシルグリセロールが蓄積する。アルコールの代謝でNADHが増えると脂肪酸のβ酸化が抑えられ、脂肪酸の合成とトリアシルグリセロールの合成が進む。肥満、糖尿病、低栄養（蛋白質不足によるアポ蛋白の不足）、ステロイドの使用なども原因となる。飲酒をやめれば可逆的だが、炎症を伴うと線維化から肝硬変へ進むことがある。', '{"B": "動脈硬化の泡沫細胞などに蓄積する脂質である。", "C": "リソソーム病でリソソームに蓄積する脂質である。", "D": "細胞膜の主成分で、脂肪肝の空胞の主成分ではない。", "E": "脂質の過酸化で生じる褐色の色素で、空胞にはならない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'リポフスチン', 2, 'CBT', '高齢者の剖検で、心筋細胞の核の周囲や神経細胞の細胞質に、黄褐色の微細な顆粒が多数みられた。加齢とともに蓄積するこの消耗性色素はどれか。', '[{"key": "A", "text": "炭粉"}, {"key": "B", "text": "リポフスチン"}, {"key": "C", "text": "ヘモジデリン"}, {"key": "D", "text": "メラニン"}, {"key": "E", "text": "ビリルビン"}]'::jsonb, 'B', 'リポフスチンは細胞膜などの脂質が過酸化されて生じた物質が、リソソームで分解されきれずに残った褐色の色素である。分裂しない心筋細胞や神経細胞、肝細胞に加齢とともにたまる。萎縮した臓器に多く、肉眼で褐色に見える心臓の萎縮を褐色萎縮という。それ自体が細胞を傷害することはないとされる。', '{"A": "吸入された外来性の色素で、肺やリンパ節に沈着する。", "C": "鉄を含む色素で、ベルリン青染色で青く染まる。出血や鉄過剰で沈着する。", "D": "メラノサイトがつくる色素で、皮膚や網膜、黒質に存在する。", "E": "ヘムの分解産物で、胆汁のうっ滞などで組織に沈着する。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '遺伝性ヘモクロマトーシス', 2, 'CBT', '肝硬変、糖尿病、皮膚の色素沈着を示す中年男性で、血清フェリチンとトランスフェリン飽和度が著しく高かった。遺伝性ヘモクロマトーシスの主な病態はどれか。', '[{"key": "A", "text": "銅の胆汁への排泄が障害される"}, {"key": "B", "text": "鉄がヘムに取り込まれずミトコンドリアにたまる"}, {"key": "C", "text": "ヘプシジンが働かず、鉄の吸収が過剰になる"}, {"key": "D", "text": "鉄の尿中への排泄が止まる"}, {"key": "E", "text": "赤血球の破壊が亢進して鉄が放出される"}]'::jsonb, 'C', '遺伝性ヘモクロマトーシスは、HFE遺伝子などの異常でヘプシジンの産生が不十分となり、十二指腸からの鉄の吸収とマクロファージからの放出が過剰になる疾患である。鉄が肝、膵臓、心臓、皮膚、下垂体などに沈着し、肝硬変、糖尿病、心筋症、皮膚の色素沈着をきたす。瀉血で治療する。日本では輸血の繰り返しによる二次性の鉄過剰症のほうが多い。', '{"A": "Wilson病の病態である。", "B": "鉄芽球性貧血の病態である。", "D": "ヒトには鉄を積極的に排泄する仕組みがほとんどなく、主な病態は吸収の過剰である。", "E": "溶血は二次性の鉄過剰の原因となるが、遺伝性の病態ではない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '異栄養性石灰化', 2, 'CBT', '高齢者の大動脈弁や、壊死した組織、古い結核病巣には、しばしばカルシウム塩が沈着している。血清カルシウム値が正常でも、傷害された組織にカルシウム塩が沈着する現象はどれか。', '[{"key": "A", "text": "骨化生"}, {"key": "B", "text": "尿路結石"}, {"key": "C", "text": "痛風結節"}, {"key": "D", "text": "異栄養性石灰化"}, {"key": "E", "text": "転移性石灰化"}]'::jsonb, 'D', '異栄養性石灰化は、壊死巣、動脈硬化の粥腫、変性した心臓弁、古い結核病巣など、傷害を受けた組織に起こる石灰化で、血清カルシウム値は正常である。石灰化した大動脈弁は大動脈弁狭窄症の原因となる。転移性石灰化は副甲状腺機能亢進症、悪性腫瘍、ビタミンD過剰、慢性腎臓病などによる高カルシウム・高リン血症で、腎、肺、胃粘膜、血管などの正常な組織に起こる。', '{"A": "骨組織そのものがつくられる変化で、単なる塩の沈着とは異なる。", "B": "尿路で結晶が固まったもので、組織への沈着ではない。", "C": "尿酸塩の沈着で、カルシウム塩の沈着ではない。", "E": "高カルシウム血症や高リン血症のために正常な組織に沈着する石灰化である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '痛風の結晶', 2, 'CBT', '飲酒後の夜間に母趾の付け根が赤く腫れて激しく痛み、関節液の偏光顕微鏡検査で針状の結晶が見つかった。この結晶の成分はどれか。', '[{"key": "A", "text": "ピロリン酸カルシウム"}, {"key": "B", "text": "シュウ酸カルシウム"}, {"key": "C", "text": "コレステロール"}, {"key": "D", "text": "ハイドロキシアパタイト"}, {"key": "E", "text": "尿酸一ナトリウム"}]'::jsonb, 'E', '痛風は高尿酸血症が続き、関節内に析出した尿酸一ナトリウムの結晶を好中球が貪食して起こる急性関節炎である。結晶は針状で、偏光顕微鏡で負の複屈折を示す。母趾の中足趾節関節に好発し、長く続くと痛風結節や尿路結石、腎障害をきたす。偽痛風のピロリン酸カルシウム結晶は正の複屈折を示し、高齢者の膝関節に多い。', '{"A": "偽痛風の原因結晶で、短い棒状や菱形に見える。", "B": "尿路結石の主な成分である。", "C": "胆石や動脈硬化の粥腫の成分である。", "D": "骨や石灰化した組織の成分である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'Pompe病', 2, 'CBT', '乳児期から筋緊張の低下と著しい心肥大が進行し、筋生検でリソソーム内にグリコーゲンの蓄積を認めた。この疾患で欠損している酵素はどれか。', '[{"key": "A", "text": "酸性α-グルコシダーゼ"}, {"key": "B", "text": "グルコース-6-ホスファターゼ"}, {"key": "C", "text": "筋グリコーゲンホスホリラーゼ"}, {"key": "D", "text": "グルコセレブロシダーゼ"}, {"key": "E", "text": "α-ガラクトシダーゼA"}]'::jsonb, 'A', 'Pompe病（糖原病II型）は、リソソームでグリコーゲンを分解する酸性α-グルコシダーゼの欠損による常染色体潜性遺伝の疾患で、糖原病の中でリソソーム病でもある。乳児型では心筋と骨格筋にグリコーゲンが蓄積して心肥大と筋力低下が進み、呼吸不全や心不全に至る。遅発型は四肢や呼吸筋の筋力低下で発症する。酵素補充療法が行われる。', '{"B": "欠損すると肝にグリコーゲンがたまり、空腹時低血糖をきたす（糖原病I型）。", "C": "欠損すると運動時の筋痛や筋けいれんをきたす（糖原病V型）。", "D": "欠損するとGaucher病となる。", "E": "欠損するとFabry病となる。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'Gaucher病', 2, 'CBT', '肝脾腫と骨痛、貧血、血小板減少を示す小児で、骨髄に細胞質がしわくちゃの紙のように見える大型の細胞がみられた。この疾患で欠損している酵素はどれか。', '[{"key": "A", "text": "α-L-イズロニダーゼ"}, {"key": "B", "text": "グルコセレブロシダーゼ"}, {"key": "C", "text": "ヘキソサミニダーゼA"}, {"key": "D", "text": "α-ガラクトシダーゼA"}, {"key": "E", "text": "スフィンゴミエリナーゼ"}]'::jsonb, 'B', 'Gaucher病はグルコセレブロシダーゼの欠損によるリソソーム病で、マクロファージにグルコセレブロシドがたまり、Gaucher細胞とよばれる。肝脾腫、脾機能亢進による血球減少、骨痛や骨折などをきたし、神経型では神経症状を伴う。常染色体潜性遺伝で、酵素補充療法や基質合成抑制療法が行われる。', '{"A": "欠損するとムコ多糖症（Hurler症候群）となる。", "C": "欠損するとTay-Sachs病となり、GM2ガングリオシドが神経細胞にたまる。", "D": "欠損するとFabry病となり、四肢の痛みや被角血管腫、腎障害をきたす。", "E": "欠損するとNiemann-Pick病となる。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'Wilson病', 2, 'CBT', '肝機能障害と構音障害、振戦を示す15歳の生徒で、角膜の辺縁に茶褐色の輪を認めた。この疾患の病態として正しいのはどれか。', '[{"key": "A", "text": "腸管からの銅の吸収が障害され、銅が欠乏する"}, {"key": "B", "text": "リソソーム酵素の欠損で糖脂質がたまる"}, {"key": "C", "text": "胆汁への銅の排泄が障害され、肝や脳に銅がたまる"}, {"key": "D", "text": "腸管からの鉄の吸収が過剰になり、肝に鉄がたまる"}, {"key": "E", "text": "血清セルロプラスミンが高値となり、銅が尿中に失われる"}]'::jsonb, 'C', 'Wilson病はATP7B遺伝子の異常による常染色体潜性遺伝の疾患で、肝細胞で銅がセルロプラスミンに組み込まれず、胆汁中にも排泄されないため、肝に銅がたまり、さらに脳（大脳基底核）、角膜、腎にも沈着する。血清セルロプラスミンは低く、尿中の銅は増える。角膜のKayser-Fleischer輪が特徴で、銅キレート薬や亜鉛で治療する。', '{"A": "Menkes病の病態である。", "B": "リソソーム病の病態である。", "D": "遺伝性ヘモクロマトーシスの病態である。", "E": "Wilson病では血清セルロプラスミンは低値となる。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'フェニルケトン尿症', 2, 'CBT', '新生児マススクリーニングで高値を示し、早期から食事療法を行えば知的障害を防げる先天代謝異常がある。フェニルケトン尿症で血中に蓄積する物質はどれか。', '[{"key": "A", "text": "ロイシン"}, {"key": "B", "text": "ホモシステイン"}, {"key": "C", "text": "ガラクトース"}, {"key": "D", "text": "フェニルアラニン"}, {"key": "E", "text": "チロシン"}]'::jsonb, 'D', 'フェニルケトン尿症はフェニルアラニン水酸化酵素（またはその補酵素のテトラヒドロビオプテリン）の欠損で、フェニルアラニンが蓄積して脳の発達を障害する。チロシンが減るためメラニンが少なく、色白で毛髪が明るい色になる。新生児マススクリーニングで発見し、フェニルアラニンを制限した治療乳で治療する。母体の血中濃度が高いと胎児にも影響するため、患者の女性は妊娠前から厳格な管理が必要である。', '{"A": "メープルシロップ尿症で蓄積する分枝鎖アミノ酸の一つである。", "B": "ホモシスチン尿症で蓄積する物質である。", "C": "ガラクトース血症で蓄積する物質である。", "E": "フェニルアラニンから合成される側の物質で、この疾患ではむしろ低下する。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '終末糖化産物', 2, 'CBT', '糖尿病の血糖管理の指標であるHbA1cは、ヘモグロビンにブドウ糖が結合したものである。高血糖が長く続いて蛋白質とブドウ糖の結合がさらに進み、組織障害の一因となる物質はどれか。', '[{"key": "A", "text": "ケトン体"}, {"key": "B", "text": "乳酸"}, {"key": "C", "text": "ソルビトール（糖アルコール）"}, {"key": "D", "text": "グリコーゲン"}, {"key": "E", "text": "終末糖化産物（AGE）"}]'::jsonb, 'E', 'ブドウ糖は酵素を介さずに蛋白質のアミノ基と結合し、初期にはHbA1cのような可逆的な産物をつくるが、長く続くと不可逆的な終末糖化産物（AGE）となる。AGEはコラーゲンなどの基質蛋白を架橋して血管壁や基底膜を硬く厚くし、受容体を介して炎症を引き起こす。ポリオール経路でのソルビトールの蓄積とともに、網膜症、腎症、神経障害などの細小血管障害の一因と考えられている。', '{"A": "インスリンの欠乏で脂肪酸の分解から生じる物質である。", "B": "嫌気的解糖で生じる物質である。", "C": "アルドース還元酵素でブドウ糖から生じる糖アルコールで、蛋白質との結合物ではない。", "D": "ブドウ糖の貯蔵形態で、蛋白質との結合物ではない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '泡沫細胞', 2, 'CBT', '粥状動脈硬化の初期病変である脂肪線条では、内膜に脂質を大量に取り込んだ泡沫細胞が集まっている。泡沫細胞の主な由来はどれか。', '[{"key": "A", "text": "酸化LDLを取り込んだマクロファージ"}, {"key": "B", "text": "コレステロールを合成した血管内皮細胞"}, {"key": "C", "text": "脂肪を蓄えた外膜の脂肪細胞"}, {"key": "D", "text": "酸化された脂質を大量に取り込んだ好中球"}, {"key": "E", "text": "コレステロールを蓄えた赤血球"}]'::jsonb, 'A', '内膜に入り込んだLDLは酸化などの修飾を受け、単球から分化したマクロファージのスカベンジャー受容体に取り込まれる。この取り込みはLDL受容体と違って細胞内のコレステロールで抑えられないため、マクロファージは脂質で満たされた泡沫細胞となる。平滑筋細胞も内膜へ移動して泡沫化し、線維性被膜をつくる。被膜が薄い不安定な粥腫が破綻すると血栓ができ、急性冠症候群の原因となる。', '{"B": "内皮細胞は泡沫細胞の主な由来ではない。", "C": "泡沫細胞は内膜にみられ、脂肪細胞に由来するものではない。", "D": "好中球は泡沫細胞の主な由来ではない。", "E": "赤血球は泡沫細胞にならない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'くる病', 2, 'CBT', '日光に当たる機会が少なく、母乳だけで育てられた乳児に、O脚、肋骨の念珠状の膨隆、頭蓋骨の軟化がみられた。この疾患の骨の病態として正しいのはどれか。', '[{"key": "A", "text": "軟骨細胞の増殖が抑えられて四肢が短くなる"}, {"key": "B", "text": "骨基質（類骨）の石灰化が障害される"}, {"key": "C", "text": "骨基質も石灰化も保たれたまま骨量が減る"}, {"key": "D", "text": "I型コラーゲンの遺伝子異常で骨が脆くなる"}, {"key": "E", "text": "破骨細胞の機能不全で骨が硬く太くなる"}]'::jsonb, 'B', 'ビタミンDが欠乏すると腸からのカルシウムとリンの吸収が減り、骨基質（類骨）の石灰化が障害される。成長期の小児では骨端線の軟骨の石灰化も障害されてくる病となり、骨の変形、肋骨念珠、頭蓋癆などを示す。成人では骨軟化症となる。完全母乳栄養で日光に当たる機会が少ない乳児や、食物アレルギーによる除去食の児で起こりやすい。', '{"A": "軟骨無形成症の病態である。", "C": "骨粗鬆症の病態である。", "D": "骨形成不全症の病態である。", "E": "大理石骨病の病態である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'アディポネクチン', 2, 'CBT', '内臓脂肪が蓄積すると、脂肪組織から分泌される生理活性物質の量が変化し、インスリン抵抗性や動脈硬化が進む。内臓脂肪型肥満で血中濃度が低下する、インスリン感受性を高める物質はどれか。', '[{"key": "A", "text": "インターロイキン6"}, {"key": "B", "text": "プラスミノゲン活性化因子インヒビター1"}, {"key": "C", "text": "アディポネクチン"}, {"key": "D", "text": "レプチン"}, {"key": "E", "text": "腫瘍壊死因子α"}]'::jsonb, 'C', 'アディポネクチンは脂肪細胞が分泌し、肝や筋でAMPキナーゼを活性化して脂肪酸の燃焼とブドウ糖の取り込みを促し、抗動脈硬化作用ももつ。内臓脂肪が増えると分泌が減る。一方で腫瘍壊死因子α、インターロイキン6、PAI-1などは増え、インスリン抵抗性、高血圧、脂質異常、血栓傾向がそろったメタボリックシンドロームの病態につながる。', '{"A": "肥満した脂肪組織で増え、慢性の炎症に関わる。", "B": "内臓脂肪型肥満で増え、血栓をできやすくする。", "D": "肥満では血中濃度がむしろ上昇している（レプチン抵抗性）。", "E": "肥満した脂肪組織で増え、インスリン抵抗性を強める。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '過形成', 2, 'CBT', '妊娠中の乳腺では、授乳に備えて腺房を構成する細胞の数が増え、乳腺全体が大きくなる。細胞の数が増えることで臓器が大きくなるこの適応現象はどれか。', '[{"key": "A", "text": "化生"}, {"key": "B", "text": "異形成"}, {"key": "C", "text": "萎縮"}, {"key": "D", "text": "過形成"}, {"key": "E", "text": "肥大"}]'::jsonb, 'D', '過形成は刺激に応じて細胞が分裂して数を増やす適応で、ホルモンによる生理的な過形成（妊娠中の乳腺、月経周期の子宮内膜）や、肝の部分切除後の再生などがある。分裂できない心筋や骨格筋は、負荷に対して肥大で適応する。刺激が過剰に続く病的な過形成（エストロゲン過剰による子宮内膜増殖症など）は、癌の発生母地となることがある。', '{"A": "分化した組織が別の分化した組織に置き換わる変化である。", "B": "細胞の形や配列に異常が生じた前癌病変である。", "C": "細胞が小さくなったり数が減ったりして臓器が小さくなる変化である。", "E": "個々の細胞が大きくなる変化で、細胞の数は増えない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '抱合型ビリルビン優位の黄疸', 2, 'CBT', '黄疸のある患者で、血清の直接（抱合型）ビリルビンが優位に上昇し、尿が褐色で、便の色が薄くなっていた。最も考えられる病態はどれか。', '[{"key": "A", "text": "溶血性貧血"}, {"key": "B", "text": "Gilbert症候群"}, {"key": "C", "text": "生後数日の新生児の生理的黄疸"}, {"key": "D", "text": "Crigler-Najjar症候群"}, {"key": "E", "text": "総胆管結石による胆汁の流出障害"}]'::jsonb, 'E', '胆汁の流出が妨げられると、肝でつくられた抱合型ビリルビンが血中に逆流する。抱合型は水溶性なので尿中に出て尿が褐色になり、腸に届かないため便は灰白色に近くなる。胆汁酸もたまってかゆみが出る。溶血や抱合の障害では非抱合型が上昇し、非抱合型はアルブミンと結合しているため尿中には出ない。', '{"A": "非抱合型ビリルビンが優位に上昇し、尿中にビリルビンは出ない。", "B": "グルクロン酸抱合の軽い障害で、非抱合型ビリルビンが軽度に上昇する。", "C": "抱合能の未熟さによる非抱合型ビリルビンの上昇である。", "D": "グルクロン酸抱合酵素の欠損で、非抱合型ビリルビンが上昇する。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'クワシオルコル', 2, 'CBT', '食料が不足した地域で、離乳後に糖質中心の食事を続けた幼児が、全身の浮腫、腹部の膨満、皮膚炎を示した。蛋白質の摂取不足が主体の、この栄養障害の特徴として正しいのはどれか。', '[{"key": "A", "text": "低アルブミン血症による浮腫と脂肪肝を伴う"}, {"key": "B", "text": "皮下脂肪と筋が極度に失われ、浮腫を伴わない"}, {"key": "C", "text": "血清アルブミン値は正常に保たれる"}, {"key": "D", "text": "肝臓は萎縮して脂肪は蓄積しない"}, {"key": "E", "text": "感染症にかかりにくくなる"}]'::jsonb, 'A', 'クワシオルコルは、エネルギーはある程度とれていても蛋白質の摂取が不足する栄養障害で、低アルブミン血症による浮腫、腹水、脂肪肝、皮膚炎、毛髪の変化を示す。見かけ上の体重は浮腫で保たれることがある。マラスムスは総エネルギーの不足で、筋と皮下脂肪が失われて著しくやせるが、浮腫は目立たない。いずれも免疫が低下し、感染症で死亡しやすい。', '{"B": "エネルギーの不足が主体のマラスムスの特徴である。", "C": "蛋白質の不足で血清アルブミンは低下する。", "D": "アポ蛋白の不足でトリアシルグリセロールを送り出せず、脂肪肝となる。", "E": "細胞性免疫が低下し、感染症にかかりやすくなる。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'Lewy小体', 2, 'CBT', '安静時振戦と動作の緩慢さで発症した患者の剖検で、中脳の黒質の神経細胞に、好酸性の円形の封入体がみられた。この封入体の主な構成蛋白質はどれか。', '[{"key": "A", "text": "プリオン蛋白"}, {"key": "B", "text": "α-シヌクレイン"}, {"key": "C", "text": "タウ蛋白"}, {"key": "D", "text": "アミロイドβ"}, {"key": "E", "text": "TDP-43"}]'::jsonb, 'B', 'Parkinson病では黒質のドパミン神経細胞が脱落し、残った細胞にα-シヌクレインが凝集したLewy小体がみられる。Lewy小体が大脳皮質に広く出現するとLewy小体型認知症となり、幻視や症状の変動、レム睡眠行動障害を示す。神経変性疾患の多くは、特定の蛋白質の異常な凝集と蓄積を特徴とする。', '{"A": "Creutzfeldt-Jakob病などで異常型が蓄積する。", "C": "Alzheimer病の神経原線維変化や進行性核上性麻痺などで蓄積する。", "D": "Alzheimer病の老人斑の主成分である。", "E": "筋萎縮性側索硬化症や前頭側頭葉変性症で蓄積する。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '老人斑', 2, 'CBT', '進行性の記憶障害で亡くなった高齢者の脳に、海馬を中心とする萎縮と、細胞外の老人斑が多数みられた。老人斑の主な構成成分はどれか。', '[{"key": "A", "text": "ハンチンチン"}, {"key": "B", "text": "免疫グロブリン軽鎖"}, {"key": "C", "text": "アミロイドβ蛋白"}, {"key": "D", "text": "α-シヌクレイン"}, {"key": "E", "text": "リン酸化タウ蛋白"}]'::jsonb, 'C', 'Alzheimer病では、アミロイド前駆体蛋白から切り出されたアミロイドβが凝集して細胞外に老人斑をつくり、神経細胞内にはリン酸化したタウ蛋白が神経原線維変化をつくる。海馬と側頭葉内側から萎縮が始まり、記憶障害で発症する。アミロイドβの蓄積は発症の10〜20年前から始まるとされ、アミロイドβに対する抗体薬が早期の患者に用いられている。', '{"A": "Huntington病でポリグルタミンが伸長した蛋白質である。", "B": "ALアミロイドーシスで沈着する蛋白質である。", "D": "Parkinson病などのLewy小体の主成分である。", "E": "神経細胞内の神経原線維変化の主成分で、老人斑の主成分ではない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'Mallory-Denk小体', 2, 'CBT', 'アルコール性肝炎の患者の肝生検で、腫大した肝細胞の細胞質に好酸性で不整形の封入体がみられた。この封入体の主な構成成分はどれか。', '[{"key": "A", "text": "リソソームにたまったリポフスチン"}, {"key": "B", "text": "鉄を含むヘモジデリン"}, {"key": "C", "text": "細胞質に集まった肝炎ウイルスの粒子の集塊"}, {"key": "D", "text": "凝集した中間径フィラメント（ケラチン）"}, {"key": "E", "text": "変性したミトコンドリア"}]'::jsonb, 'D', 'Mallory-Denk小体は、傷害を受けた肝細胞の中でケラチン8/18の中間径フィラメントがユビキチンなどとともに凝集した好酸性の封入体である。アルコール性肝炎で特徴的だが、非アルコール性脂肪肝炎、Wilson病、原発性胆汁性胆管炎などでもみられる。アルコール性肝炎では肝細胞の風船様の腫大、好中球の浸潤、中心静脈周囲の線維化を伴う。', '{"A": "褐色の消耗性色素で、この封入体ではない。", "B": "鉄の沈着で、ベルリン青染色で青く染まる。", "C": "ウイルス感染の封入体で、この病態にはあたらない。", "E": "巨大ミトコンドリアもみられるが、この封入体の主成分ではない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '硝子様細動脈硬化', 2, 'CBT', '長年の高血圧と糖尿病のある患者の腎生検で、細動脈の壁が均質な好酸性の物質で厚くなり、内腔が狭くなっていた。この細動脈の変化はどれか。', '[{"key": "A", "text": "粥状硬化"}, {"key": "B", "text": "フィブリノイド壊死"}, {"key": "C", "text": "Mönckeberg型中膜石灰化"}, {"key": "D", "text": "血管炎"}, {"key": "E", "text": "硝子様細動脈硬化"}]'::jsonb, 'E', '硝子様細動脈硬化は、血漿蛋白が内皮を通って壁に漏れ出し、基底膜の成分も増えて細動脈の壁が均質で好酸性に厚くなる変化である。良性の高血圧や糖尿病、加齢でみられ、腎では細動脈が狭くなって糸球体が虚血に陥り、腎硬化症の原因となる。糖尿病では輸入細動脈と輸出細動脈の両方に起こりやすい。', '{"A": "大・中型の動脈の内膜に脂質がたまる変化である。", "B": "悪性高血圧などで急速に起こる、血管壁の壊死である。", "C": "筋型動脈の中膜に起こる石灰化で、内腔はあまり狭くならない。", "D": "血管壁への炎症細胞の浸潤を伴う病変である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '急性間欠性ポルフィリン症', 2, 'CBT', '若い女性が、月経前や新しい薬剤の内服後に、激しい腹痛、便秘、頻脈、四肢の脱力、精神症状を繰り返している。発作時の尿は放置すると赤褐色になる。この疾患の病態として正しいのはどれか。', '[{"key": "A", "text": "δ-アミノレブリン酸とポルホビリノーゲンの蓄積"}, {"key": "B", "text": "肝でのビリルビンのグルクロン酸抱合が遺伝的に障害される"}, {"key": "C", "text": "ヘモグロビンのβ鎖の合成が低下する"}, {"key": "D", "text": "鉄の吸収が過剰になり組織に沈着する"}, {"key": "E", "text": "尿酸の産生が亢進して関節に結晶が析出する"}]'::jsonb, 'A', '急性間欠性ポルフィリン症はヘム合成のポルホビリノーゲン脱アミノ酵素の活性低下による常染色体顕性遺伝の疾患である。薬剤（バルビツール酸系など）、飲酒、絶食、月経などでδ-アミノレブリン酸合成酵素が誘導されると、δ-アミノレブリン酸とポルホビリノーゲンが蓄積し、腹痛、自律神経症状、末梢神経障害、精神症状の発作を起こす。光線過敏はない。治療にはヘミンの投与やブドウ糖の補給を行う。', '{"B": "体質性黄疸の病態である。", "C": "βサラセミアの病態である。", "D": "ヘモクロマトーシスの病態である。", "E": "痛風の病態である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '骨粗鬆症の骨', 2, 'CBT', '閉経後の女性が、軽い尻もちで腰椎の圧迫骨折をきたした。骨密度は若年成人の平均の60%であった。この疾患の骨の特徴として正しいのはどれか。', '[{"key": "A", "text": "骨に腫瘍が転移して、溶骨性の変化が生じている"}, {"key": "B", "text": "骨の石灰化は保たれたまま、骨量が減少している"}, {"key": "C", "text": "類骨が増えて、骨の石灰化が障害されている"}, {"key": "D", "text": "骨形成が骨吸収を上回って、骨量が増えている"}, {"key": "E", "text": "破骨細胞が機能しないため、骨が硬く太くなっている"}]'::jsonb, 'B', '骨粗鬆症は骨量の減少と骨の微細構造の劣化によって骨がもろくなり、骨折しやすくなる疾患で、骨の石灰化そのものは保たれている。閉経後はエストロゲンの低下で骨吸収が亢進し、骨吸収が骨形成を上回る。椎体、大腿骨近位部、橈骨遠位端の骨折が多い。ステロイドの長期使用、甲状腺機能亢進症、副甲状腺機能亢進症、喫煙なども危険因子である。', '{"A": "骨転移の特徴である。", "C": "骨軟化症やくる病の特徴である。", "D": "骨吸収が骨形成を上回り、骨量が減っている。", "E": "大理石骨病の特徴である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '急速代謝回転蛋白', 2, 'CBT', '入院中の患者の栄養状態を評価し、栄養療法の効果を短期間で判定したい。血中の半減期が短く、数日間の栄養状態の変化を鋭敏に反映する蛋白質はどれか。', '[{"key": "A", "text": "フィブリノゲン"}, {"key": "B", "text": "フェリチン"}, {"key": "C", "text": "トランスサイレチン"}, {"key": "D", "text": "アルブミン"}, {"key": "E", "text": "免疫グロブリンG（IgG）"}]'::jsonb, 'C', 'トランスサイレチン（プレアルブミン、半減期約2日）、トランスフェリン（約7〜10日）、レチノール結合蛋白（約半日）は、肝で合成される半減期の短い蛋白質で、短期間の栄養状態の変化を反映する。アルブミンは半減期が約3週間と長く、慢性の栄養状態の目安となる。いずれも炎症や肝機能障害でも低下するため、CRPなどとあわせて解釈する。', '{"A": "炎症で増える急性期蛋白で、栄養の指標にはならない。", "B": "鉄の貯蔵を反映し、炎症でも上昇する。", "D": "半減期が約3週間と長く、短期間の変化を反映しにくい。", "E": "感染や炎症の影響を受け、栄養の指標にはならない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'ムコ多糖症', 2, 'CBT', '3歳の男児。粗な顔貌、関節の拘縮、肝脾腫、発達の遅れを示し、尿中のムコ多糖（グリコサミノグリカン）が増えていた。角膜の混濁はない。母方の伯父にも同じ症状があった。最も考えられる疾患はどれか。', '[{"key": "A", "text": "Gaucher病"}, {"key": "B", "text": "Pompe病"}, {"key": "C", "text": "Tay-Sachs病"}, {"key": "D", "text": "Hunter症候群"}, {"key": "E", "text": "Hurler症候群"}]'::jsonb, 'D', 'ムコ多糖症はグリコサミノグリカンを分解するリソソーム酵素の欠損で、全身の組織にムコ多糖がたまる。Hunter症候群（II型、イズロン酸-2-スルファターゼ欠損）はX連鎖潜性遺伝で男児に発症し、角膜の混濁がないことがHurler症候群（I型、α-L-イズロニダーゼ欠損、常染色体潜性遺伝）との違いである。酵素補充療法や造血幹細胞移植が行われる。', '{"A": "糖脂質の蓄積症で、ムコ多糖は増えない。", "B": "グリコーゲンの蓄積症で、ムコ多糖は増えない。", "C": "ガングリオシドの蓄積症で、ムコ多糖は増えない。", "E": "常染色体潜性遺伝で、角膜の混濁を伴うことが多い。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '乾性壊疽', 2, 'CBT', '糖尿病と閉塞性動脈硬化症のある患者の足趾が、黒く乾燥して硬くなり、周囲の健常部との境界がはっきりしていた。この状態はどれか。', '[{"key": "A", "text": "湿性壊疽"}, {"key": "B", "text": "ガス壊疽"}, {"key": "C", "text": "褥瘡"}, {"key": "D", "text": "凍傷"}, {"key": "E", "text": "乾性壊疽"}]'::jsonb, 'E', '壊疽は壊死した組織が二次的な変化を受けた状態である。乾性壊疽は動脈の閉塞による凝固壊死の組織が乾燥して黒く硬くなったもので、健常部との境界がはっきりする。細菌感染が加わって融解が進むと湿性壊疽となり、全身状態を悪化させるため緊急の処置が必要となる。糖尿病では神経障害と血流障害、易感染性が重なり、足の潰瘍や壊疽が起こりやすい。', '{"A": "感染を伴って組織が腐敗し、湿って悪臭を放つ状態である。", "B": "クロストリジウム属などの感染で組織内にガスが生じる状態である。", "C": "持続的な圧迫による皮膚と皮下組織の壊死である。", "D": "寒冷による組織の傷害である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'ニクズク肝', 2, 'CBT', '右心不全が長く続いた患者の剖検で、肝臓の割面に暗赤色と黄色の部分が網目状に入り混じる模様がみられた。この変化の主な成因はどれか。', '[{"key": "A", "text": "小葉中心部のうっ血と周辺の脂肪化"}, {"key": "B", "text": "門脈域の周囲へのリンパ球などの炎症細胞の浸潤"}, {"key": "C", "text": "肝動脈の閉塞による広い範囲の梗塞"}, {"key": "D", "text": "肝細胞とKupffer細胞への鉄の大量の沈着"}, {"key": "E", "text": "肝細胞への銅の沈着"}]'::jsonb, 'A', '右心不全では中心静脈から下大静脈への流れが滞り、小葉の中心部に血液がたまる（うっ血）。うっ血した暗赤色の中心部と、低酸素で脂肪化した黄色の周辺部が網目状に入り混じり、ナツメグ（ニクズク）の割面に似るためニクズク肝とよばれる。長く続くと中心静脈の周囲に線維化が生じ、心臓性肝硬変に至ることがある。', '{"B": "慢性肝炎などでみられる変化で、この模様の成因ではない。", "C": "肝は二重の血液供給を受けるため梗塞は起こりにくく、この模様の成因ではない。", "D": "ヘモクロマトーシスでみられる変化で、肝は褐色になる。", "E": "Wilson病でみられる変化である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '心不全細胞', 2, 'CBT', '左心不全が長く続いた患者の喀痰や肺の組織で、褐色の色素を貪食したマクロファージが多数みられた。心不全細胞とよばれるこの細胞が貪食している色素はどれか。', '[{"key": "A", "text": "ビリルビン"}, {"key": "B", "text": "ヘモジデリン"}, {"key": "C", "text": "リポフスチン"}, {"key": "D", "text": "メラニン"}, {"key": "E", "text": "炭粉"}]'::jsonb, 'B', '左心不全では肺静脈圧が上がって肺がうっ血し、毛細血管から肺胞へ赤血球が漏れ出る。肺胞マクロファージが赤血球を貪食して分解すると、鉄を含むヘモジデリンが残る。この細胞を心不全細胞といい、ベルリン青染色で青く染まる。慢性の肺うっ血では肺が硬く褐色になる（褐色硬化）。', '{"A": "黄疸の原因となる色素で、心不全細胞の色素ではない。", "C": "加齢で細胞内にたまる消耗性色素で、心不全細胞の色素ではない。", "D": "メラノサイトがつくる色素で、心不全細胞の色素ではない。", "E": "喫煙者や大気汚染で肺に沈着するが、心不全細胞の色素ではない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '動脈の血栓', 2, 'CBT', '冠動脈の粥腫が破綻した部位にできる血栓は、静脈の深部静脈血栓とは組成が異なる。血流の速い動脈にできる血栓の主な構成成分はどれか。', '[{"key": "A", "text": "好中球とマクロファージ"}, {"key": "B", "text": "アミロイド線維"}, {"key": "C", "text": "血小板とフィブリン"}, {"key": "D", "text": "大量の赤血球とフィブリン"}, {"key": "E", "text": "コレステロールの結晶"}]'::jsonb, 'C', '血流の速い動脈では、傷ついた内皮に血小板が粘着・凝集し、フィブリンで補強された白色血栓ができる。抗血小板薬が動脈の血栓の予防に用いられるのはこのためである。血流の遅い静脈では、凝固系の活性化でフィブリンの網に赤血球が多く取り込まれた赤色血栓ができ、抗凝固薬が予防と治療に用いられる。', '{"A": "膿瘍などの炎症巣を構成する細胞である。", "B": "アミロイドーシスで沈着する線維である。", "D": "血流の遅い静脈にできる赤色血栓の主な構成である。", "E": "粥腫の中に含まれるが、血栓の主な構成成分ではない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'Zahn線条', 2, 'CBT', '剖検で血管内に見つかった凝血塊が、生前にできた血栓か死後にできた凝血かを見分ける必要がある。生前にできた血栓にみられる特徴はどれか。', '[{"key": "A", "text": "上層が黄色の血漿の成分、下層が暗赤色の赤血球の層に分かれる"}, {"key": "B", "text": "ゼリー状で柔らかく、血管の形どおりに抜ける"}, {"key": "C", "text": "フィブリンを含まず、赤血球だけからなる"}, {"key": "D", "text": "血小板とフィブリンの層と赤血球の層が交互に重なる縞模様"}, {"key": "E", "text": "表面が滑らかで光沢があり、血管壁に付着していない"}]'::jsonb, 'D', '生前にできた血栓は、流れる血液の中で血小板とフィブリンが層をつくり、その間に赤血球が捕らえられて、明暗の縞模様（Zahn線条）を示す。血管壁に付着し、もろく乾いた割面をもつ。死後の凝血は血流がない中でできるため層構造がなく、赤血球の沈んだ暗赤色の部分と、黄色いゼリー状の部分（鶏脂様凝血）に分かれ、血管壁に付着しない。', '{"A": "死後に赤血球が沈んでできる凝血の特徴である。", "B": "死後にできた凝血の特徴である。", "C": "生前の血栓はフィブリンを含む。", "E": "死後にできた凝血の特徴である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '肺血栓塞栓症の塞栓源', 2, 'CBT', '手術後に長く臥床していた患者が、歩き始めた直後に突然の呼吸困難と胸痛を訴え、肺血栓塞栓症と診断された。肺血栓塞栓症の塞栓源として最も多いものはどれか。', '[{"key": "A", "text": "左心房にできた血栓"}, {"key": "B", "text": "大動脈の粥腫が崩れたもの"}, {"key": "C", "text": "左心室の壁在血栓"}, {"key": "D", "text": "肺静脈にできた血栓"}, {"key": "E", "text": "下肢の深部静脈血栓"}]'::jsonb, 'E', '肺血栓塞栓症の塞栓源の大部分は下肢や骨盤の深部静脈血栓で、長期臥床、手術、妊娠、悪性腫瘍、経口避妊薬、先天性の血栓性素因などが危険因子となる。血栓は右心系を通って肺動脈を塞ぐ。臥床から歩き始めたときや排便時に発症しやすい。予防には早期離床、弾性ストッキング、間欠的空気圧迫法、抗凝固薬を用いる。', '{"A": "体循環に流れて脳や腎、四肢の動脈を塞ぐ。", "B": "下流の体循環の動脈を塞ぐ（コレステロール塞栓）。", "C": "体循環に流れて脳梗塞などを起こす。", "D": "肺血栓塞栓症の主な塞栓源ではない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '奇異性塞栓', 2, 'CBT', '深部静脈血栓症のある若年の患者が、突然の片麻痺をきたし、脳梗塞と診断された。静脈にできた血栓が脳の動脈を塞いだ経路として最も考えられるのはどれか。', '[{"key": "A", "text": "卵円孔開存などの右左短絡"}, {"key": "B", "text": "肺の毛細血管を通り抜けて左心系に入った"}, {"key": "C", "text": "門脈を経由して肝から脳へ運ばれた"}, {"key": "D", "text": "リンパ管を経由して脳へ運ばれた"}, {"key": "E", "text": "下大静脈から直接脳の動脈へ流れ込んだ"}]'::jsonb, 'A', '静脈の血栓は通常は肺の血管で捕らえられるが、卵円孔開存や心房中隔欠損、肺動静脈瘻などの右左短絡があると、肺を経ずに体循環に入り、脳梗塞などを起こす（奇異性塞栓）。咳やいきみで右心房の圧が一時的に上がると短絡が起こりやすい。原因のはっきりしない若年者の脳梗塞では、経食道心エコーなどで短絡の有無を調べる。', '{"B": "肺の毛細血管は血栓を捕らえるため、通常は通り抜けられない。", "C": "門脈は脳へ血液を送らない。", "D": "リンパ管は血栓を脳の動脈へ運ばない。", "E": "静脈から動脈へ直接つながる経路はない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '脂肪塞栓症候群', 2, 'CBT', '大腿骨骨幹部を骨折した若年者が、受傷の2日後に呼吸困難、意識障害、前胸部や結膜の点状出血をきたした。最も考えられる病態はどれか。', '[{"key": "A", "text": "コレステロール塞栓症"}, {"key": "B", "text": "脂肪塞栓症候群"}, {"key": "C", "text": "空気塞栓症"}, {"key": "D", "text": "羊水塞栓症"}, {"key": "E", "text": "腫瘍塞栓症"}]'::jsonb, 'B', '長管骨や骨盤の骨折では、骨髄の脂肪滴が静脈に入り、肺や脳、皮膚の毛細血管を塞ぐ。脂肪から生じる遊離脂肪酸による血管内皮の傷害も加わり、受傷後1〜3日で呼吸不全、意識障害、点状出血を三徴とする脂肪塞栓症候群が起こる。骨折の早期の固定が予防となり、治療は呼吸管理などの支持療法が中心となる。', '{"A": "カテーテル操作などで大動脈の粥腫が崩れて起こる。", "C": "静脈に空気が入って起こり、中心静脈カテーテルの操作などで生じる。", "D": "分娩時に羊水が母体の血中に入って起こる。", "E": "腫瘍細胞の塊が血管を塞ぐもので、骨折とは関係しない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '出血性梗塞', 2, 'CBT', '腸間膜静脈の血栓症で壊死した小腸は、暗赤色で出血を伴っていた。このように静脈の閉塞や二重の血液供給のある臓器で起こりやすい梗塞の型はどれか。', '[{"key": "A", "text": "脂肪壊死"}, {"key": "B", "text": "フィブリノイド壊死"}, {"key": "C", "text": "出血性梗塞（赤色梗塞）"}, {"key": "D", "text": "貧血性梗塞（白色梗塞）"}, {"key": "E", "text": "乾酪壊死"}]'::jsonb, 'C', '出血性梗塞は、静脈の閉塞、肺や腸のような二重の血液供給がある臓器、閉塞した動脈に血流が戻った場合、疎な組織などで起こりやすく、壊死した組織に血液があふれて暗赤色となる。肺梗塞、腸間膜の静脈血栓症、精巣捻転などが例である。終動脈で栄養される心臓、腎臓、脾臓の梗塞は、境界のはっきりした蒼白な貧血性梗塞となる。', '{"A": "脂肪分解酵素で脂肪組織が壊れる壊死である。", "B": "血管壁にみられる壊死である。", "D": "終動脈の閉塞で心臓、腎臓、脾臓などに起こる蒼白な梗塞である。", "E": "結核でみられる壊死である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '敗血症性ショックの初期', 2, 'CBT', '肺炎から敗血症性ショックに陥った患者の初期には、血圧が低いのに四肢が温かく、心拍出量はむしろ増えていた。この状態の主な病態として正しいのはどれか。', '[{"key": "A", "text": "大量の出血で循環血液量が減る"}, {"key": "B", "text": "緊張性気胸で静脈還流が妨げられる"}, {"key": "C", "text": "交感神経の緊張で末梢血管が強く収縮する"}, {"key": "D", "text": "末梢血管が拡張し血管抵抗が下がる"}, {"key": "E", "text": "心筋の収縮力が失われ、心拍出量が著しく低下する"}]'::jsonb, 'D', '敗血症では、病原体の成分に反応して放出されたサイトカインや一酸化窒素などで末梢血管が拡張し、血管の透過性も高まる。血管抵抗が下がって血圧が低下するが、初期には心拍出量が増え、四肢は温かい（ウォームショック）。進行すると心機能も低下して四肢が冷たくなる。初期治療は十分な輸液と早期の抗菌薬で、血圧が保てなければノルアドレナリンを用いる。', '{"A": "出血性ショック（循環血液量減少性ショック）の病態である。", "B": "閉塞性ショックの病態である。", "C": "循環血液量減少性ショックなどの代償反応で、四肢は冷たくなる。", "E": "心原性ショックの主な病態である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '出血性ショックの代償反応', 2, 'CBT', '交通事故で大量に出血した患者は、頻脈で四肢が冷たく湿っていた。出血によって循環血液量が減ったときに起こる代償反応として正しいのはどれか。', '[{"key": "A", "text": "迷走神経が興奮して心拍数が減る"}, {"key": "B", "text": "バソプレシンの分泌が減って尿量が増える"}, {"key": "C", "text": "レニン-アンジオテンシン系が抑えられる"}, {"key": "D", "text": "皮膚の血管が拡張して四肢が温かくなる"}, {"key": "E", "text": "頻脈と末梢血管の収縮"}]'::jsonb, 'E', '循環血液量が減ると、圧受容器反射で交感神経が興奮し、頻脈、心収縮力の増強、皮膚・腎・消化管の血管収縮で脳と心臓の血流を守る。レニン-アンジオテンシン-アルドステロン系とバソプレシンで水とナトリウムが保持され、尿量が減る。出血量が多くなると代償しきれず血圧が下がる。四肢が冷たく湿っているのは血管収縮と交感神経による発汗のためである。', '{"A": "代償反応では交感神経が優位となり、頻脈になる。", "B": "バソプレシンの分泌は増え、尿量は減る。", "C": "腎血流の低下でレニン-アンジオテンシン系は活性化する。", "D": "皮膚の血管は収縮し、四肢は冷たくなる。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '急性炎症の血管反応', 2, 'CBT', '皮膚をひっかくと、しばらくして赤く腫れてくる。急性炎症の初期に起こる血管の変化として正しいのはどれか。', '[{"key": "A", "text": "細動脈が拡張して血流が増え、血管の透過性が高まる"}, {"key": "B", "text": "細動脈が持続的に収縮して血流が途絶える"}, {"key": "C", "text": "血管の透過性が低下して、組織の間にある液体がむしろ減る"}, {"key": "D", "text": "リンパ管が閉塞して炎症の成分が組織から出なくなる"}, {"key": "E", "text": "毛細血管が新たにつくられて組織が赤くなる"}]'::jsonb, 'A', '急性炎症では、一過性の細動脈の収縮のあと、ヒスタミンや一酸化窒素などで細動脈が拡張して血流が増え、発赤と熱感が生じる（充血）。細静脈の内皮細胞が収縮して隙間ができ、蛋白質に富む液が漏れ出て腫脹が起こる。血流が遅くなると白血球が血管壁に沿って並び、内皮に接着して血管外へ出ていく。', '{"B": "一過性の収縮のあと、すぐに拡張して血流が増える。", "C": "透過性は高まり、蛋白質を含む液が組織に漏れ出る。", "D": "リンパの流れはむしろ増える。", "E": "血管の新生は修復の段階で起こる変化である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '白血球のローリング', 2, 'CBT', '炎症の場では、血流に乗って流れてきた好中球が血管内皮の上を転がるように速度を落とし、やがて強く接着して血管外へ出る。好中球の転がり（ローリング）を主に担う接着分子はどれか。', '[{"key": "A", "text": "フィブリン"}, {"key": "B", "text": "セレクチン"}, {"key": "C", "text": "インテグリン"}, {"key": "D", "text": "カドヘリン"}, {"key": "E", "text": "コネキシン"}]'::jsonb, 'B', '炎症性サイトカインで活性化された内皮にE-セレクチンやP-セレクチンが現れ、好中球の糖鎖と弱く結合と解離を繰り返して転がらせる。次にケモカインで活性化された好中球のインテグリン（LFA-1など）が内皮のICAM-1に強く結合し、内皮細胞の間を通って血管外へ出る。インテグリンの異常による白血球接着不全症では、好中球が血管から出られず、膿をつくれない重い感染症を繰り返す。', '{"A": "凝固でできる線維で、白血球の接着分子ではない。", "C": "ローリングのあとの強固な接着を担う。", "D": "同じ種類の細胞どうしを接着させる分子で、白血球の遊出の主役ではない。", "E": "ギャップ結合をつくる蛋白質である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'プロスタグランジンE2', 2, 'CBT', '発熱や関節の腫れと痛みには、非ステロイド性抗炎症薬（NSAIDs）がよく効く。NSAIDsがその産生を抑えることで発熱と疼痛を和らげる主な炎症のメディエーターはどれか。', '[{"key": "A", "text": "ブラジキニン"}, {"key": "B", "text": "補体C5a"}, {"key": "C", "text": "プロスタグランジンE2"}, {"key": "D", "text": "ヒスタミン"}, {"key": "E", "text": "ロイコトリエンB4"}]'::jsonb, 'C', 'アラキドン酸はシクロオキシゲナーゼでプロスタグランジンやトロンボキサンに、リポキシゲナーゼでロイコトリエンになる。プロスタグランジンE2は視床下部で体温のセットポイントを上げ、痛みの受容器を過敏にし、血管を拡張させる。NSAIDsはシクロオキシゲナーゼを阻害してこれらを抑える一方、胃粘膜の保護や腎血流の維持に働くプロスタグランジンも減らすため、消化性潰瘍や腎障害を起こしうる。', '{"A": "キニン系で生じるペプチドで、NSAIDsでは産生は抑えられない。", "B": "補体の活性化で生じる走化因子で、NSAIDsでは抑えられない。", "D": "マスト細胞から放出され、血管透過性を高める。NSAIDsでは産生は抑えられない。", "E": "リポキシゲナーゼ経路で生じる好中球の走化因子で、NSAIDsでは抑えられない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'CRPの産生', 2, 'CBT', '感染症や外傷のあと、血中のCRPが数時間から上昇し、2〜3日で最高値に達する。肝でのCRPの産生を誘導する主なサイトカインはどれか。', '[{"key": "A", "text": "インターロイキン4"}, {"key": "B", "text": "インターロイキン10"}, {"key": "C", "text": "インターフェロンα"}, {"key": "D", "text": "インターロイキン6"}, {"key": "E", "text": "インターロイキン2"}]'::jsonb, 'D', '炎症の場のマクロファージなどが産生するインターロイキン6は、肝に作用してCRP、フィブリノゲン、ハプトグロビン、血清アミロイドA、ヘプシジンなどの急性期蛋白の産生を増やす（急性期反応）。アルブミンやトランスフェリンは逆に減る。インターロイキン6受容体に対する抗体（トシリズマブ）を使うと、感染症があってもCRPが上がりにくくなることに注意する。', '{"A": "Th2細胞が産生し、IgEへのクラススイッチを促す。", "B": "炎症を抑える方向に働くサイトカインである。", "C": "ウイルス感染で産生され、抗ウイルス作用を示す。", "E": "T細胞の増殖を促すサイトカインである。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '赤血球沈降速度', 2, 'CBT', '炎症性疾患の経過を見るために赤血球沈降速度（赤沈）を測定する。赤沈を亢進させる要因として正しいのはどれか。', '[{"key": "A", "text": "血漿のアルブミンの増加"}, {"key": "B", "text": "赤血球数の増加（多血症）"}, {"key": "C", "text": "赤血球の球状化や鎌状化"}, {"key": "D", "text": "血漿の粘度の上昇だけ"}, {"key": "E", "text": "フィブリノゲンの増加"}]'::jsonb, 'E', '赤血球の表面は負に荷電して互いに反発しているが、フィブリノゲンや免疫グロブリンが増えると反発が弱まり、赤血球が連銭を形成して速く沈む。そのため炎症、多発性骨髄腫、貧血、妊娠で赤沈は亢進する。多血症、低フィブリノゲン血症、赤血球の形態異常では遅くなる。CRPより変化がゆっくりで、慢性炎症の経過をみるのに用いられる。', '{"A": "アルブミンの増加は赤沈を遅らせる方向に働く。", "B": "赤血球が多いと沈降は遅くなる。", "C": "赤血球が連銭を形成しにくくなり、沈降は遅くなる。", "D": "粘度の上昇自体は沈降を遅らせる方向に働く。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '滲出液の特徴', 2, 'CBT', '胸水が貯留した患者で、胸腔穿刺を行って滲出液か漏出液かを判定する。炎症による滲出液の特徴として正しいのはどれか。', '[{"key": "A", "text": "蛋白質と細胞を多く含み、比重が高い"}, {"key": "B", "text": "蛋白質が少なく、比重が低い"}, {"key": "C", "text": "細胞をほとんど含まず、透明である"}, {"key": "D", "text": "乳酸脱水素酵素の値が血清よりはるかに低い"}, {"key": "E", "text": "静水圧の上昇だけが原因で生じる"}]'::jsonb, 'A', '滲出液は炎症による血管透過性の亢進で生じ、蛋白質、乳酸脱水素酵素、白血球などに富み、比重が高い。肺炎、結核、悪性腫瘍、膠原病などでみられる。漏出液は静水圧の上昇や膠質浸透圧の低下で生じ、蛋白質が少なく比重が低い。胸水ではLightの基準（胸水と血清の蛋白質比、乳酸脱水素酵素の比と値）で両者を区別する。', '{"B": "心不全やネフローゼ症候群などでみられる漏出液の特徴である。", "C": "漏出液の特徴である。", "D": "滲出液では乳酸脱水素酵素が高い。", "E": "漏出液の成因で、滲出液は血管透過性の亢進による。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '膿瘍', 2, 'CBT', '黄色ブドウ球菌による皮膚の感染症で、組織の中に膿がたまり、周囲を線維性の壁で囲まれた病変ができた。この病変はどれか。', '[{"key": "A", "text": "潰瘍"}, {"key": "B", "text": "膿瘍"}, {"key": "C", "text": "蜂窩織炎"}, {"key": "D", "text": "蓄膿"}, {"key": "E", "text": "肉芽腫"}]'::jsonb, 'B', '膿瘍は、好中球が集まって組織が融解壊死し、膿が組織の中に限局してたまったもので、周囲に肉芽組織や線維性の壁ができる。黄色ブドウ球菌は凝固を促すコアグラーゼで病変を限局させやすい。膿瘍の中は抗菌薬が届きにくいため、切開して排膿することが治療の基本である。化膿レンサ球菌は組織を溶かす酵素をもち、蜂窩織炎のように広がりやすい。', '{"A": "表面の組織が欠損した状態である。", "C": "膿が組織の間にびまん性に広がった化膿性炎症で、壁で囲まれていない。", "D": "胸腔や副鼻腔など、もともとある体腔に膿がたまった状態である。", "E": "類上皮細胞などが集まった慢性炎症の病変で、膿の貯留ではない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '線維素性炎', 2, 'CBT', '急性心筋梗塞の数日後や尿毒症の患者で、心膜の表面がざらざらした毛羽立った物質で覆われていた。このように滲出物にフィブリンが多く含まれる炎症はどれか。', '[{"key": "A", "text": "カタル性炎"}, {"key": "B", "text": "出血性炎"}, {"key": "C", "text": "線維素性炎"}, {"key": "D", "text": "漿液性炎"}, {"key": "E", "text": "化膿性炎"}]'::jsonb, 'C', '線維素性炎は血管透過性の亢進が強く、フィブリノゲンが漏れ出てフィブリンとなって沈着する炎症である。心膜炎では心膜の表面がパンにバターを塗って剥がしたように見え、聴診で心膜摩擦音が聴こえる。ジフテリアの偽膜も線維素性炎の例である。フィブリンが吸収されずに器質化すると、癒着や心膜の肥厚が残る。', '{"A": "粘膜から粘液を多く分泌する炎症で、鼻かぜなどでみられる。", "B": "滲出物に赤血球が多く含まれる炎症である。", "D": "蛋白質の少ないさらさらした液が滲出する炎症で、水疱などでみられる。", "E": "好中球が主体の炎症で、膿を形成する。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '潰瘍とびらん', 2, 'CBT', '消化管の粘膜の組織欠損は、深さによって呼び方が変わる。組織の欠損が粘膜筋板を越えて粘膜下層より深く達したものはどれか。', '[{"key": "A", "text": "瘻孔"}, {"key": "B", "text": "憩室"}, {"key": "C", "text": "ポリープ"}, {"key": "D", "text": "潰瘍"}, {"key": "E", "text": "びらん"}]'::jsonb, 'D', '粘膜の層にとどまる浅い欠損をびらんといい、瘢痕を残さずに再生する。粘膜筋板を越えて深く達したものを潰瘍といい、胃潰瘍では深さによってUl-IIからUl-IVに分類される。深い潰瘍は治るときに瘢痕を残し、変形や狭窄の原因となる。筋層を貫くと穿孔を起こし、腹膜炎となる。', '{"A": "臓器どうしや臓器と皮膚が管でつながった状態である。", "B": "管腔の壁の一部が外へ袋状に突出したものである。", "C": "粘膜から内腔へ突出した隆起である。", "E": "組織の欠損が粘膜の層にとどまるもので、瘢痕を残さずに治りやすい。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '肉芽組織', 2, 'CBT', '深い創が治る過程では、欠損した部分を埋める柔らかく赤い組織が底から盛り上がってくる。この肉芽組織の主な構成として正しいのはどれか。', '[{"key": "A", "text": "成熟した膠原線維の厚い束だけ"}, {"key": "B", "text": "類上皮細胞と多核巨細胞の集まり"}, {"key": "C", "text": "増殖した表皮の角化細胞だけ"}, {"key": "D", "text": "脂肪細胞と骨格筋細胞"}, {"key": "E", "text": "新生血管と線維芽細胞"}]'::jsonb, 'E', '肉芽組織は、新しくできた毛細血管、増殖した線維芽細胞、マクロファージなどの炎症細胞、浮腫性の細胞外基質からなり、表面が赤い顆粒状に見える。血管の新生はVEGFなどで促される。線維芽細胞がコラーゲンをつくって次第に血管と細胞が減り、白く硬い瘢痕に変わる。肉芽腫（類上皮細胞の結節）とは名前が似ているが別のものである。', '{"A": "肉芽組織が成熟して瘢痕になった状態である。", "B": "肉芽腫の構成で、肉芽組織とは異なる。", "C": "表皮は肉芽組織の表面を覆うように再生するが、肉芽組織の本体ではない。", "D": "肉芽組織の主な構成ではない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '一次治癒', 2, 'CBT', '清潔な手術創を縫合して閉じた場合と、大きく開いた創を開放したまま治した場合では、治り方が異なる。縫合した手術創の治り方として正しいのはどれか。', '[{"key": "A", "text": "少量の肉芽組織で速やかに治り、瘢痕が小さい"}, {"key": "B", "text": "大量の肉芽組織で欠損を埋め、創が大きく収縮する"}, {"key": "C", "text": "表皮の再生が起こらず、肉芽組織が露出したままになる"}, {"key": "D", "text": "必ず感染を起こしてから治る"}, {"key": "E", "text": "数か月たたないと上皮化しない"}]'::jsonb, 'A', '創の縁が密着した清潔な縫合創では、少量のフィブリンと肉芽組織でつながり、表皮は1〜2日で創を覆い、瘢痕も小さく治る（一次治癒）。組織の欠損が大きい創や感染した創では、大量の肉芽組織で欠損を埋め、筋線維芽細胞によって創が大きく収縮し、大きな瘢痕を残す（二次治癒）。いずれも瘢痕の強度は数か月かけて増すが、元の皮膚の強度には戻らない。', '{"B": "開放創の二次治癒の特徴である。", "C": "縫合創では表皮が速やかに再生して創を覆う。", "D": "感染がないことが一次治癒の前提である。", "E": "縫合創は数日で上皮化する。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'ケロイド', 2, 'CBT', '胸部の小さな傷のあとに、もとの傷の範囲を越えて赤く盛り上がった硬い瘢痕が広がり、かゆみと痛みを伴っている。この病変として最も考えられるのはどれか。', '[{"key": "A", "text": "脂肪腫"}, {"key": "B", "text": "ケロイド"}, {"key": "C", "text": "肥厚性瘢痕"}, {"key": "D", "text": "萎縮性瘢痕"}, {"key": "E", "text": "肉芽腫"}]'::jsonb, 'B', 'ケロイドはコラーゲンが過剰につくられ、もとの傷の範囲を越えて周囲の正常な皮膚にまで広がる瘢痕で、自然には平坦になりにくい。前胸部、肩、耳垂などに生じやすく、体質の影響が大きい。肥厚性瘢痕は傷の範囲にとどまり、数年で平坦になりやすい。治療にはステロイドの局所注射、圧迫、手術と術後の放射線治療などを組み合わせる。', '{"A": "脂肪細胞からなる良性腫瘍である。", "C": "盛り上がるがもとの傷の範囲にとどまり、時間とともに平坦になりやすい。", "D": "周囲より陥凹した瘢痕である。", "E": "類上皮細胞の結節で、瘢痕の異常ではない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '永久細胞', 2, 'CBT', '組織が傷害されたあとに元どおりに再生できるかどうかは、その組織の細胞が分裂できるかどうかで決まる。成人でほとんど分裂せず、失われると再生しない細胞はどれか。', '[{"key": "A", "text": "腸管の陰窩の上皮細胞"}, {"key": "B", "text": "骨髄の造血細胞"}, {"key": "C", "text": "心筋細胞"}, {"key": "D", "text": "肝細胞"}, {"key": "E", "text": "表皮の基底細胞"}]'::jsonb, 'C', '細胞は分裂能によって、常に分裂する不安定細胞（表皮、腸上皮、骨髄など）、ふだんは休止しているが刺激で分裂できる安定細胞（肝細胞、腎尿細管上皮、線維芽細胞など）、ほとんど分裂しない永久細胞（神経細胞、心筋細胞）に分けられる。永久細胞が失われると瘢痕や神経膠で置き換わる。肝は部分切除の後にも元の大きさ近くまで再生する。', '{"A": "常に分裂して数日で入れ替わる不安定細胞である。", "B": "常に分裂して血球を供給する不安定細胞である。", "D": "ふだんは分裂しないが、刺激を受けると分裂して再生できる安定細胞である。", "E": "常に分裂して入れ替わる不安定細胞である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '筋線維芽細胞', 2, 'CBT', '開放創を治療していると、創の面積が肉芽組織の増生とともに周囲から縮んでいく。創の収縮を担う細胞はどれか。', '[{"key": "A", "text": "好中球"}, {"key": "B", "text": "血管内皮細胞"}, {"key": "C", "text": "表皮の角化細胞"}, {"key": "D", "text": "筋線維芽細胞"}, {"key": "E", "text": "マクロファージ"}]'::jsonb, 'D', '筋線維芽細胞は線維芽細胞が分化したもので、平滑筋型のアクチンをもち、収縮して創の縁を中心へ引き寄せる。大きな欠損の治癒に役立つが、過剰になると関節の拘縮や熱傷後の瘢痕拘縮、肝や肺の線維化の原因となる。TGF-βは線維芽細胞の筋線維芽細胞への分化とコラーゲンの産生を強く促す。', '{"A": "創の初期に集まって細菌を貪食する。", "B": "新しい毛細血管をつくる。", "C": "創の表面を覆って上皮化を担う。", "E": "壊死組織の除去と、増殖因子の産生を担う。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '類上皮細胞', 2, 'CBT', '肉芽腫は、結核やサルコイドーシスなどで形成される慢性炎症の特殊な形である。肉芽腫の主な構成細胞である類上皮細胞の由来はどれか。', '[{"key": "A", "text": "粘膜や皮膚の上皮細胞"}, {"key": "B", "text": "抗体を産生する形質細胞"}, {"key": "C", "text": "急性炎症で集まる好中球"}, {"key": "D", "text": "コラーゲンをつくる線維芽細胞"}, {"key": "E", "text": "活性化したマクロファージ"}]'::jsonb, 'E', '類上皮細胞はインターフェロンγなどで活性化されたマクロファージで、細胞質が広く上皮細胞のように並ぶ。類上皮細胞が融合すると多核巨細胞となり、核が馬蹄形に並ぶものをLanghans巨細胞という。肉芽腫の周りにはリンパ球が集まり、外側を線維が囲む。消化しにくい病原体や異物を封じ込めるための反応である。', '{"A": "上皮に似た形をしているが、上皮細胞に由来するものではない。", "B": "類上皮細胞にはならない。", "C": "類上皮細胞にはならない。", "D": "肉芽腫の周囲を線維で囲むが、類上皮細胞の由来ではない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '非乾酪性肉芽腫', 2, 'CBT', '両側の肺門リンパ節腫脹とぶどう膜炎を示す患者で、リンパ節の生検で乾酪壊死を伴わない類上皮細胞肉芽腫がみられた。最も考えられる疾患はどれか。', '[{"key": "A", "text": "サルコイドーシス"}, {"key": "B", "text": "肺結核"}, {"key": "C", "text": "悪性リンパ腫"}, {"key": "D", "text": "細菌性肺炎"}, {"key": "E", "text": "サルコーマ"}]'::jsonb, 'A', 'サルコイドーシスは原因不明の全身性の肉芽腫性疾患で、乾酪壊死を伴わない類上皮細胞肉芽腫が、肺門リンパ節、肺、眼、皮膚、心臓などに生じる。血清アンジオテンシン変換酵素やリゾチームが高値となり、ツベルクリン反応が陰性化しやすい。肉芽腫のマクロファージが活性型ビタミンDをつくるため、高カルシウム血症をきたすことがある。心臓の病変は不整脈や突然死の原因となる。', '{"B": "肉芽腫の中心に乾酪壊死を伴うことが多い。", "C": "腫瘍性のリンパ球の増殖で、肉芽腫が主体の病変ではない。", "D": "好中球が主体の急性炎症である。", "E": "間葉系の悪性腫瘍で、肉芽腫ではない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '心筋梗塞後の組織変化', 2, 'CBT', '急性心筋梗塞の患者の組織では、発症からの時間によって出現する細胞が変わる。発症から1〜3日の梗塞巣で最も目立つ細胞はどれか。', '[{"key": "A", "text": "再生した心筋細胞"}, {"key": "B", "text": "好中球"}, {"key": "C", "text": "マクロファージ"}, {"key": "D", "text": "線維芽細胞"}, {"key": "E", "text": "形質細胞"}]'::jsonb, 'B', '心筋梗塞では、発症から数時間で心筋の凝固壊死が始まり、1〜3日で辺縁から好中球が浸潤する。3〜7日ではマクロファージが壊死物を除去して梗塞巣が最も柔らかくなるため、心破裂や乳頭筋断裂、心室中隔穿孔が起こりやすい。1〜2週で肉芽組織ができ、数週から数か月で瘢痕に置き換わる。', '{"A": "心筋細胞はほとんど再生しない。", "C": "発症から3〜7日ごろに増え、壊死した心筋を除去する。", "D": "1〜2週以降に肉芽組織を経て瘢痕をつくる。", "E": "急性の梗塞巣で目立つ細胞ではない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'リンパ浮腫', 2, 'CBT', '乳癌の手術で腋窩のリンパ節を郭清した女性が、数か月後から患側の上肢のむくみを訴えるようになった。この浮腫の主な成因はどれか。', '[{"key": "A", "text": "アレルギーによる血管透過性の亢進"}, {"key": "B", "text": "腎でのナトリウムの貯留"}, {"key": "C", "text": "リンパ流の障害"}, {"key": "D", "text": "毛細血管の静水圧の上昇"}, {"key": "E", "text": "血漿の膠質浸透圧の低下"}]'::jsonb, 'C', 'リンパ管は毛細血管から漏れた組織液と蛋白質を回収して静脈に戻す。リンパ節の郭清や放射線治療、腫瘍の浸潤、フィラリア症などでリンパの流れが妨げられると、蛋白質に富む組織液がたまってリンパ浮腫となる。長く続くと皮下の線維化が進んで硬くなり、蜂窩織炎を繰り返しやすい。圧迫療法やリンパドレナージで管理する。', '{"A": "血管性浮腫などの成因で、この患者の浮腫の主な成因ではない。", "B": "腎不全や心不全での全身性浮腫の成因である。", "D": "心不全や静脈の閉塞でみられる浮腫の主な成因である。", "E": "低アルブミン血症でみられる浮腫の主な成因である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '炎症で透過性が高まる血管', 2, 'CBT', 'ヒスタミンやブラジキニンが作用すると、血管の内皮細胞が収縮して細胞の間に隙間ができ、血漿が漏れ出る。急性炎症でこの透過性の亢進が主に起こる血管はどれか。', '[{"key": "A", "text": "細動脈"}, {"key": "B", "text": "太い静脈"}, {"key": "C", "text": "リンパ管"}, {"key": "D", "text": "毛細血管の後の細静脈"}, {"key": "E", "text": "弾性型動脈である大動脈"}]'::jsonb, 'D', 'ヒスタミン、ブラジキニン、ロイコトリエンなどによる速やかな透過性の亢進は、主に毛細血管の後の細静脈で起こる。細静脈の内皮細胞にはこれらの受容体が多く、収縮して細胞の間に隙間ができる。白血球が血管外へ出ていくのも主に細静脈である。熱傷のように内皮が直接傷ついた場合は、毛細血管を含むあらゆる血管から漏れ出る。', '{"A": "拡張して血流を増やすが、透過性の亢進の主な部位ではない。", "B": "透過性の亢進の主な部位ではない。", "C": "漏れ出た組織液を回収する側の管である。", "E": "内皮の隙間から血漿が漏れる主な部位ではない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '分布異常性ショック', 2, 'CBT', 'ハチに刺された直後に全身の蕁麻疹、喘鳴、血圧低下をきたした患者がいる。このショックの主な病態として正しいのはどれか。', '[{"key": "A", "text": "心筋の収縮力が失われて心拍出量が低下する"}, {"key": "B", "text": "大量の出血で循環血液量が減る"}, {"key": "C", "text": "心タンポナーデで心室への流入が妨げられる"}, {"key": "D", "text": "交感神経の緊張で末梢血管が強く収縮する"}, {"key": "E", "text": "血管拡張と血漿の漏出"}]'::jsonb, 'E', 'アナフィラキシーでは、マスト細胞から放出されたヒスタミンなどで全身の血管が拡張し、透過性が高まって血漿が血管外に漏れるため、有効な循環血液量が急に減る（分布異常性ショック）。気道の浮腫や気管支の収縮も起こる。治療の第一選択はアドレナリンの筋肉内注射で、α1作用で血管を収縮させ、β作用で心収縮と気管支拡張を促す。大量の輸液も必要となる。', '{"A": "心原性ショックの病態である。", "B": "循環血液量減少性ショックの病態である。", "C": "閉塞性ショックの病態である。", "D": "代償反応の一部で、アナフィラキシーの主な病態ではない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '悪性腫瘍の特徴', 2, 'CBT', '腫瘍は、発生した臓器や患者に及ぼす影響によって良性と悪性に分けられる。良性腫瘍と比較した悪性腫瘍の特徴として正しいのはどれか。', '[{"key": "A", "text": "周囲の組織に浸潤しながら増殖し、転移する"}, {"key": "B", "text": "被膜に包まれ、周囲を押しのけるように膨張性に増殖する"}, {"key": "C", "text": "分化の程度が高く、もとの組織によく似ている"}, {"key": "D", "text": "核分裂像がほとんどみられない"}, {"key": "E", "text": "完全に切除しなくても再発することはない"}]'::jsonb, 'A', '悪性腫瘍は、細胞と構造の異型が強く、増殖が速く、周囲の組織に浸潤し、血管やリンパ管を通って遠くの臓器に転移する。良性腫瘍は被膜に包まれて膨張性に増殖し、転移しない。ただし良性でも、脳や心臓など部位によっては周囲を圧迫して生命に関わることがある。上皮性の悪性腫瘍を癌腫、非上皮性の悪性腫瘍を肉腫とよぶ。', '{"B": "良性腫瘍の特徴である。", "C": "良性腫瘍や高分化な腫瘍の特徴である。", "D": "悪性腫瘍では核分裂像が多く、異常な分裂像もみられる。", "E": "悪性腫瘍は取り残しがあると再発しやすい。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '肉腫', 2, 'CBT', '腫瘍の名称は、発生した組織の種類と良性・悪性の別によって決まる。非上皮性（間葉系）の悪性腫瘍に当たるものはどれか。', '[{"key": "A", "text": "大腸の腺腫"}, {"key": "B", "text": "骨肉腫"}, {"key": "C", "text": "胃の腺癌"}, {"key": "D", "text": "食道の扁平上皮癌"}, {"key": "E", "text": "膀胱の尿路上皮癌"}]'::jsonb, 'B', '骨、軟骨、筋、脂肪、血管などの間葉系の組織から発生する悪性腫瘍を肉腫といい、骨肉腫、軟骨肉腫、横紋筋肉腫、脂肪肉腫、平滑筋肉腫などがある。癌腫より若年に多いものがあり、主に血行性に肺へ転移する。骨肉腫は10歳代の膝関節の周囲に好発し、血清アルカリホスファターゼが上昇する。', '{"A": "上皮性の良性腫瘍である。", "C": "上皮性の悪性腫瘍（癌腫）である。", "D": "上皮性の悪性腫瘍（癌腫）である。", "E": "上皮性の悪性腫瘍（癌腫）である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '奇形腫', 2, 'CBT', '20歳代の女性の卵巣に嚢胞性の腫瘍があり、内部に毛髪、皮脂、歯、骨を含んでいた。このように三胚葉のさまざまな組織を含む腫瘍はどれか。', '[{"key": "A", "text": "絨毛癌"}, {"key": "B", "text": "未分化胚細胞腫"}, {"key": "C", "text": "奇形腫"}, {"key": "D", "text": "過誤腫"}, {"key": "E", "text": "腺腫"}]'::jsonb, 'C', '奇形腫は、多分化能をもつ胚細胞から発生し、外胚葉（皮膚、毛髪、歯、神経組織）、中胚葉（骨、軟骨、筋）、内胚葉（気道や消化管の上皮）の組織を含む。卵巣の成熟嚢胞性奇形腫（皮様嚢腫）は若い女性に多く、ほとんどが良性だが、茎捻転や破裂を起こすことがある。未熟な神経組織を含む未熟奇形腫は悪性である。精巣や縦隔、仙尾部にも発生する。', '{"A": "栄養膜細胞から発生する悪性腫瘍で、hCGを産生する。", "B": "未分化な胚細胞からなる悪性腫瘍で、成熟した組織は含まない。", "D": "その臓器に本来ある組織が無秩序に増えた腫瘍様の病変で、三胚葉の組織は含まない。", "E": "腺上皮から発生する良性腫瘍である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '過誤腫', 2, 'CBT', '胸部CTで偶然見つかった肺の小さな結節を切除すると、軟骨、脂肪、気管支の上皮が無秩序に混ざった組織であった。このように、その臓器に本来ある組織が異常な配列で増えた腫瘍様の病変はどれか。', '[{"key": "A", "text": "奇形腫"}, {"key": "B", "text": "肉芽腫"}, {"key": "C", "text": "転移性腫瘍"}, {"key": "D", "text": "過誤腫"}, {"key": "E", "text": "分離腫"}]'::jsonb, 'D', '過誤腫は、その臓器を構成する成熟した組織が、量や配列の異常を伴って増えた腫瘍様の病変である。肺の過誤腫は軟骨を主体とし、ポップコーン様の石灰化がみられることがある。結節性硬化症では脳、腎（血管筋脂肪腫）、心臓などに過誤腫が多発する。本来その臓器にない組織が迷入したものは分離腫とよび、区別する。', '{"A": "三胚葉の組織を含む胚細胞由来の腫瘍である。", "B": "類上皮細胞が集まった慢性炎症の病変である。", "C": "他の臓器の癌が転移したもので、軟骨や脂肪が無秩序に混ざるものではない。", "E": "本来その臓器にない正常な組織が異所性に存在するもので、胃粘膜にできた異所性膵などが例である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '低分化な腫瘍', 2, 'CBT', '病理診断では、腫瘍の組織がもとの正常組織にどれだけ似ているかを分化度として評価する。低分化な悪性腫瘍の特徴として正しいのはどれか。', '[{"key": "A", "text": "もとの組織によく似た腺管の形成や角化を明らかに示す"}, {"key": "B", "text": "核と細胞質の比率が小さく、核が均一である"}, {"key": "C", "text": "増殖が遅く、核分裂像がまれである"}, {"key": "D", "text": "悪性度が低く、転移をきたすことはない"}, {"key": "E", "text": "核の不ぞろいが強く、もとの組織に似ていない"}]'::jsonb, 'E', '分化度は腫瘍がもとの組織にどれだけ似ているかを示し、高分化な腫瘍は腺管や角化などの特徴をよく保つ。低分化や未分化な腫瘍は核の大小不同や濃染、核と細胞質の比率の増大、異常な核分裂像などの異型が強く、一般に悪性度が高い。組織の起源がわからない場合は免疫組織化学で特定する。分化度（組織学的異型度）は、広がりを示す病期とは別の指標である。', '{"A": "高分化な腫瘍の特徴である。", "B": "異型が乏しい細胞の特徴である。", "C": "低分化な腫瘍は一般に増殖が速い。", "D": "低分化な腫瘍は悪性度が高い傾向にある。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'TNM分類', 2, 'CBT', '癌の病期はTNM分類によって決められ、治療方針や予後の判断に用いられる。TNM分類のNが表すものはどれか。', '[{"key": "A", "text": "所属リンパ節への転移の有無と程度"}, {"key": "B", "text": "原発巣の大きさと周囲への広がり"}, {"key": "C", "text": "遠隔臓器への転移の有無"}, {"key": "D", "text": "腫瘍細胞の分化度"}, {"key": "E", "text": "患者の全身状態"}]'::jsonb, 'A', 'TNM分類は、T（原発巣の大きさと周囲への浸潤の程度）、N（所属リンパ節への転移）、M（遠隔転移）の組合せで癌の解剖学的な広がりを表し、それをもとに病期（ステージ）を決める。臓器ごとに基準が定められている。病期は予後と強く関係し、手術、化学療法、放射線療法などの治療方針の選択に用いられる。', '{"B": "Tが表すものである。", "C": "Mが表すものである。", "D": "組織学的異型度（グレード）で、TNM分類には含まれない。", "E": "パフォーマンスステータスなどで評価し、TNM分類には含まれない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '肉腫の転移経路', 2, 'CBT', '上皮性の悪性腫瘍と非上皮性の悪性腫瘍では、転移の経路に傾向の違いがある。肉腫が主に転移する経路はどれか。', '[{"key": "A", "text": "神経周囲への浸潤"}, {"key": "B", "text": "血行性"}, {"key": "C", "text": "リンパ行性"}, {"key": "D", "text": "体腔内への播種"}, {"key": "E", "text": "管腔内の進展"}]'::jsonb, 'B', '癌腫はリンパ管に入りやすく、まず所属リンパ節へ転移することが多い。肉腫は血管に入りやすく、血行性に肺へ転移しやすい。ただし例外もあり、腎細胞癌、肝細胞癌、濾胞性甲状腺癌、絨毛癌などの癌腫は血行性の転移が目立つ。腹腔や胸腔に面した臓器の癌は、体腔内に播種して腹膜炎や胸膜炎を起こす。', '{"A": "膵癌や前立腺癌などでみられる局所の進展である。", "C": "癌腫で多い転移の経路で、肉腫では比較的少ない。", "D": "胃癌や卵巣癌などの癌腫で起こりやすい。", "E": "尿路上皮癌などでみられる経路である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'Krukenberg腫瘍', 2, 'CBT', '胃の印環細胞癌の患者に、両側の卵巣の充実性の腫大がみられ、卵巣にも印環細胞がみられた。この卵巣の転移性腫瘍の名称はどれか。', '[{"key": "A", "text": "Sister Mary Joseph結節"}, {"key": "B", "text": "Brenner腫瘍"}, {"key": "C", "text": "Krukenberg腫瘍"}, {"key": "D", "text": "Virchow転移"}, {"key": "E", "text": "Schnitzler転移"}]'::jsonb, 'C', 'Krukenberg腫瘍は、胃癌などの印環細胞癌が卵巣に転移したもので、両側性のことが多い。転移の経路には腹膜播種、リンパ行性、血行性の説がある。胃癌では、胸管を経た左鎖骨上窩リンパ節への転移（Virchow転移）、Douglas窩への播種（Schnitzler転移）、臍への転移（Sister Mary Joseph結節）も知られ、いずれも進行した状態を示す。', '{"A": "臍への転移である。", "B": "卵巣原発の上皮性腫瘍で、転移性腫瘍ではない。", "D": "左の鎖骨上窩リンパ節への転移である。", "E": "Douglas窩への腹膜播種で、直腸指診で触れる。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '造骨性の骨転移', 2, 'CBT', '腰痛を訴える高齢の男性で、脊椎と骨盤のエックス線写真に多発する骨硬化像があり、血清アルカリホスファターゼが高値であった。造骨性の骨転移をきたしやすい原発巣はどれか。', '[{"key": "A", "text": "甲状腺癌"}, {"key": "B", "text": "多発性骨髄腫"}, {"key": "C", "text": "肝細胞癌"}, {"key": "D", "text": "前立腺癌"}, {"key": "E", "text": "腎細胞癌"}]'::jsonb, 'D', '骨転移は脊椎、骨盤、大腿骨の近位部、肋骨などに多い。多くは破骨細胞を活性化する溶骨性の転移だが、前立腺癌は骨芽細胞を刺激して骨をつくる造骨性の転移をきたしやすく、エックス線写真で骨硬化像を示す。乳癌は溶骨性と造骨性が混在することがある。骨転移は痛み、病的骨折、脊髄圧迫、高カルシウム血症の原因となる。', '{"A": "溶骨性の骨転移をきたしやすい。", "B": "骨髄の形質細胞の腫瘍で、打ち抜き像を示す溶骨性の病変をきたす。", "C": "溶骨性の骨転移をきたしやすい。", "E": "溶骨性の骨転移をきたしやすい。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'N-MYC遺伝子の増幅', 2, 'CBT', '2歳の小児の副腎に腫瘍がみられ、尿中のバニリルマンデル酸とホモバニリン酸が高値であった。この腫瘍でN-MYC遺伝子の増幅がみられると予後が悪い。この腫瘍はどれか。', '[{"key": "A", "text": "Wilms腫瘍"}, {"key": "B", "text": "網膜芽細胞腫"}, {"key": "C", "text": "肝芽腫"}, {"key": "D", "text": "褐色細胞腫"}, {"key": "E", "text": "神経芽腫"}]'::jsonb, 'E', '神経芽腫は神経堤由来の交感神経系の細胞から発生する小児の代表的な固形腫瘍で、副腎髄質に多い。カテコラミンの代謝物である尿中のバニリルマンデル酸とホモバニリン酸が上昇する。癌遺伝子のN-MYCが増幅していると増殖が速く、予後が悪い。乳児期に発見されたものは自然に退縮することもある。癌遺伝子は増幅、点変異、転座によって活性化される。', '{"A": "腎臓に発生する小児の腫瘍で、WT1遺伝子の異常などが関わる。", "B": "網膜に発生し、RB1遺伝子の異常で生じる。", "C": "肝臓に発生する小児の腫瘍で、血清AFPが高値となる。", "D": "成人に多いカテコラミン産生腫瘍で、N-MYCの増幅は予後因子ではない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'RASの点変異', 2, 'CBT', '膵癌の大多数や大腸癌の一部では、RAS遺伝子に点変異がみられる。RAS遺伝子の点変異によって起こる変化として正しいのはどれか。', '[{"key": "A", "text": "活性型のまま信号を送り続ける"}, {"key": "B", "text": "RAS蛋白がまったく産生されなくなる"}, {"key": "C", "text": "RAS蛋白が核内で転写因子として働く"}, {"key": "D", "text": "細胞周期が停止してアポトーシスが起こる"}, {"key": "E", "text": "受容体型チロシンキナーゼの発現が消失する"}]'::jsonb, 'A', 'RASはGTPと結合すると活性型となり、RAF-MEK-ERKなどの経路で増殖の信号を伝え、自らのGTPase活性でGTPをGDPに分解して不活性型に戻る。点変異でGTPase活性が失われると、上流からの刺激がなくても活性型のまま信号を送り続ける。大腸癌ではRAS変異があると抗EGFR抗体薬が効かないため、治療前に遺伝子検査を行う。', '{"B": "機能獲得型の変異で、活性化した蛋白がつくられる。", "C": "RASは細胞膜の内側で信号を伝える低分子量G蛋白質である。", "D": "増殖の信号が続くため、細胞増殖が促される。", "E": "RASの変異は受容体の下流で起こり、受容体の発現を消失させない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'HER2の過剰発現', 2, 'CBT', '乳癌の一部では、腫瘍細胞の膜にHER2蛋白が過剰に発現しており、抗HER2薬の治療対象となる。HER2蛋白が過剰に発現する主な機序はどれか。', '[{"key": "A", "text": "HER2遺伝子を含む染色体の部分欠失"}, {"key": "B", "text": "HER2遺伝子の増幅"}, {"key": "C", "text": "HER2遺伝子の点変異による活性化"}, {"key": "D", "text": "HER2遺伝子と別の遺伝子の染色体転座"}, {"key": "E", "text": "HER2遺伝子のプロモーターの脱メチル化"}]'::jsonb, 'B', 'HER2陽性乳癌では、17番染色体上のHER2（ERBB2）遺伝子の領域が何十コピーにも増幅し、受容体型チロシンキナーゼのHER2が過剰につくられて増殖の信号が強まる。免疫組織化学で蛋白質の過剰発現を、FISH法などで遺伝子の増幅を確かめる。トラスツズマブなどの抗HER2薬が有効である。胃癌の一部もHER2陽性となる。', '{"A": "欠失では発現はむしろ減る。", "C": "HER2陽性乳癌の主な機序は点変異ではなく、遺伝子の増幅である。", "D": "HER2陽性乳癌の主な機序ではない。", "E": "HER2陽性乳癌の主な機序ではない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'Burkittリンパ腫の転座', 2, 'CBT', '顎の腫瘤を主訴とした小児のリンパ腫で、組織は星空像を示し、8番染色体と14番染色体の転座がみられた。この転座によって活性化される遺伝子はどれか。', '[{"key": "A", "text": "PML-RARA"}, {"key": "B", "text": "CCND1"}, {"key": "C", "text": "MYC"}, {"key": "D", "text": "BCL2"}, {"key": "E", "text": "BCR-ABL"}]'::jsonb, 'C', 'Burkittリンパ腫では、t(8;14)転座によってMYC遺伝子が免疫グロブリン重鎖遺伝子の強力なエンハンサーの近くに移り、過剰に発現する。細胞増殖がきわめて速く、腫瘍細胞の間にアポトーシス細胞を貪食したマクロファージが散在して星空像を示す。アフリカの流行地の症例はEBウイルスとの関連が強い。増殖が速いため、治療開始時の腫瘍崩壊症候群に注意する。', '{"A": "t(15;17)転座で生じ、急性前骨髄球性白血病でみられる。", "B": "t(11;14)転座で活性化し、マントル細胞リンパ腫でみられる。", "D": "t(14;18)転座で活性化し、濾胞性リンパ腫でみられる。", "E": "t(9;22)転座で生じ、慢性骨髄性白血病でみられる。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '急性前骨髄球性白血病', 2, 'CBT', '歯肉出血と皮下出血で発症した白血病で、骨髄にアズール顆粒の豊富な前骨髄球が増え、播種性血管内凝固を伴っていた。この白血病に特徴的な染色体異常と、分化を誘導する治療薬の組合せはどれか。', '[{"key": "A", "text": "t(15;17) — イマチニブ"}, {"key": "B", "text": "t(8;14) — リツキシマブ"}, {"key": "C", "text": "t(14;18) — 全トランス型レチノイン酸"}, {"key": "D", "text": "t(15;17) — 全トランス型レチノイン酸"}, {"key": "E", "text": "t(9;22) — 全トランス型レチノイン酸"}]'::jsonb, 'D', '急性前骨髄球性白血病では、t(15;17)転座でPML-RARA融合遺伝子が生じ、レチノイン酸受容体の働きが妨げられて前骨髄球の段階で分化が止まる。全トランス型レチノイン酸は大量に投与すると分化の阻害を解除し、白血病細胞を成熟させる（分化誘導療法）。亜ヒ酸も有効である。診断時から播種性血管内凝固を伴いやすく、出血が早期の死因となるため、速やかに治療を始める。', '{"A": "イマチニブはBCR-ABLを阻害する薬で、この白血病の分化誘導薬ではない。", "B": "Burkittリンパ腫の転座と、B細胞腫瘍に用いる抗体薬の組合せである。", "C": "t(14;18)は濾胞性リンパ腫の転座である。", "E": "t(9;22)は慢性骨髄性白血病などでみられる転座である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '家族性大腸腺腫症', 2, 'CBT', '20歳代で大腸に数百個以上の腺腫が多発し、親も若くして大腸癌で亡くなっていた。この疾患の原因となる遺伝子はどれか。', '[{"key": "A", "text": "RB1"}, {"key": "B", "text": "VHL"}, {"key": "C", "text": "BRCA1"}, {"key": "D", "text": "NF1"}, {"key": "E", "text": "APC"}]'::jsonb, 'E', '家族性大腸腺腫症はAPC遺伝子の生殖細胞系列変異による常染色体顕性遺伝の疾患で、10歳代から大腸に多数の腺腫が生じ、放置すればほぼ全例が大腸癌になるため、予防的な大腸全摘が検討される。APC蛋白はβ-カテニンの分解を促しており、その異常でWntシグナルが過剰になる。散発性の大腸癌でも、APCの異常は腺腫の発生の初期にみられる。', '{"A": "網膜芽細胞腫の原因遺伝子である。", "B": "von Hippel-Lindau病の原因遺伝子である。", "C": "遺伝性乳癌卵巣癌症候群の原因遺伝子である。", "D": "神経線維腫症1型の原因遺伝子である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'von Hippel-Lindau病', 2, 'CBT', '小脳の血管芽腫の切除歴がある若年者に、両側の腎腫瘍と網膜の血管腫がみられた。この疾患で発生しやすい腎腫瘍はどれか。', '[{"key": "A", "text": "淡明細胞型腎細胞癌"}, {"key": "B", "text": "腎芽腫（Wilms腫瘍）"}, {"key": "C", "text": "腎盂の尿路上皮癌"}, {"key": "D", "text": "オンコサイトーマ"}, {"key": "E", "text": "腎血管筋脂肪腫"}]'::jsonb, 'A', 'von Hippel-Lindau病はVHL遺伝子の異常による常染色体顕性遺伝の疾患で、中枢神経と網膜の血管芽腫、淡明細胞型腎細胞癌、褐色細胞腫、膵の嚢胞や腫瘍などが多発する。VHL蛋白は低酸素誘導因子（HIF）の分解を担い、その異常でHIFが蓄積してVEGFなどが増え、血管に富む腫瘍ができる。散発性の淡明細胞型腎細胞癌の多くでもVHLの不活化がみられる。', '{"B": "小児に多い腎腫瘍で、この疾患に特徴的ではない。", "C": "喫煙などと関連する腫瘍で、この疾患に特徴的ではない。", "D": "良性の腎腫瘍で、この疾患に特徴的ではない。", "E": "結節性硬化症で多発する腫瘍である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '多発性内分泌腫瘍症1型', 2, 'CBT', '尿路結石を繰り返す患者に高カルシウム血症があり、さらに難治性の消化性潰瘍と下垂体腫瘍が見つかった。多発性内分泌腫瘍症1型で生じる腫瘍の組合せはどれか。', '[{"key": "A", "text": "網膜芽細胞腫、骨肉腫、軟部肉腫"}, {"key": "B", "text": "副甲状腺、膵内分泌腫瘍、下垂体"}, {"key": "C", "text": "甲状腺髄様癌、褐色細胞腫、副甲状腺"}, {"key": "D", "text": "甲状腺髄様癌、褐色細胞腫、粘膜神経腫"}, {"key": "E", "text": "副腎皮質癌、乳癌、脳腫瘍"}]'::jsonb, 'B', '多発性内分泌腫瘍症1型はMEN1遺伝子（メニン）の異常による常染色体顕性遺伝の疾患で、副甲状腺の過形成や腺腫、膵・十二指腸の神経内分泌腫瘍（ガストリノーマ、インスリノーマなど）、下垂体腺腫が生じる。ガストリノーマは難治性の消化性潰瘍の原因となる（Zollinger-Ellison症候群）。2型はRET遺伝子の異常で、甲状腺髄様癌と褐色細胞腫が特徴である。', '{"A": "遺伝性網膜芽細胞腫で多い腫瘍である。", "C": "多発性内分泌腫瘍症2A型の組合せである。", "D": "多発性内分泌腫瘍症2B型の組合せである。", "E": "Li-Fraumeni症候群で多い腫瘍である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'HTLV-1', 2, 'CBT', '九州出身の高齢者に、花弁状の核をもつ異常リンパ球の増加と高カルシウム血症がみられた。この疾患の原因ウイルスと主な感染経路の組合せはどれか。', '[{"key": "A", "text": "ヒトパピローマウイルス — 母乳"}, {"key": "B", "text": "B型肝炎ウイルス — 飛沫"}, {"key": "C", "text": "HTLV-1 — 母乳"}, {"key": "D", "text": "EBウイルス — 母乳"}, {"key": "E", "text": "HTLV-1 — 飛沫"}]'::jsonb, 'C', '成人T細胞白血病・リンパ腫はHTLV-1の感染が原因で、日本では九州・沖縄に感染者が多い。主な感染経路は母乳による母子感染で、ほかに性行為や輸血がある。感染者の一部が数十年の潜伏期ののちに発症し、花弁状の核をもつ異常リンパ球、高カルシウム血症、皮膚病変などを示す。妊婦の抗体検査で陽性の場合、人工乳の使用などで母子感染を減らす。HTLV-1は脊髄症（HAM）の原因にもなる。', '{"A": "ヒトパピローマウイルスは主に性行為で感染する。", "B": "B型肝炎ウイルスは血液や体液で感染する。", "D": "EBウイルスは主に唾液で感染する。", "E": "HTLV-1は飛沫では感染しない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'アフラトキシン', 2, 'CBT', '温暖多湿な地域で、カビの生えたピーナッツやトウモロコシを長期に摂取していると、ある悪性腫瘍が増える。カビ毒のアフラトキシンと最も関連が深い悪性腫瘍はどれか。', '[{"key": "A", "text": "悪性胸膜中皮腫"}, {"key": "B", "text": "膀胱癌"}, {"key": "C", "text": "肝血管肉腫"}, {"key": "D", "text": "肝細胞癌"}, {"key": "E", "text": "急性骨髄性白血病"}]'::jsonb, 'D', 'アフラトキシンB1はアスペルギルス属のカビがつくる毒素で、肝で代謝されて活性化し、DNAに結合してTP53遺伝子の特定の部位に変異を起こす。B型肝炎ウイルスの感染と重なると肝細胞癌の危険が大きく高まる。化学発癌物質の多くは、体内で代謝されて初めて発癌性をもつ前駆物質である。', '{"A": "石綿の吸入と関連する。", "B": "芳香族アミンの曝露や喫煙と関連する。", "C": "塩化ビニルの曝露と関連する。", "E": "ベンゼンや抗癌薬の曝露と関連する。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '石綿と悪性腫瘍', 2, 'CBT', '40年前に造船所で断熱材を扱う仕事をしていた男性に、胸膜の不整な肥厚と胸水がみられた。石綿（アスベスト）の吸入と最も関連が深い悪性腫瘍はどれか。', '[{"key": "A", "text": "肝細胞癌"}, {"key": "B", "text": "甲状腺乳頭癌"}, {"key": "C", "text": "膀胱癌"}, {"key": "D", "text": "悪性黒色腫"}, {"key": "E", "text": "悪性胸膜中皮腫"}]'::jsonb, 'E', '石綿の吸入は、胸膜プラーク、石綿肺、肺癌、悪性胸膜中皮腫の原因となる。中皮腫は曝露から30〜40年の長い潜伏期を経て発症し、胸膜がびまん性に肥厚して胸水を伴い、予後が悪い。喫煙は石綿による肺癌の危険を相乗的に高める。職業上の曝露による中皮腫は労災補償や石綿健康被害救済制度の対象となる。', '{"A": "肝炎ウイルスやアフラトキシンなどと関連する。", "B": "小児期の放射線被曝などと関連する。", "C": "芳香族アミンの曝露や喫煙と関連する。", "D": "紫外線の曝露と関連する。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'α-フェトプロテイン', 2, 'CBT', '慢性B型肝炎で経過観察中の患者の血液検査で、ある腫瘍マーカーが上昇してきた。血清α-フェトプロテイン（AFP）が上昇する腫瘍はどれか。', '[{"key": "A", "text": "肝細胞癌"}, {"key": "B", "text": "前立腺癌"}, {"key": "C", "text": "膵癌"}, {"key": "D", "text": "卵巣の漿液性癌"}, {"key": "E", "text": "甲状腺髄様癌"}]'::jsonb, 'A', 'AFPは胎児期に肝と卵黄嚢でつくられる蛋白質で、肝細胞癌や卵黄嚢腫瘍（胚細胞腫瘍）で上昇する。肝細胞癌ではPIVKA-IIも腫瘍マーカーとなる。妊娠中や肝炎の活動期、新生児でも上昇するため解釈に注意する。腫瘍マーカーは早期発見には感度が十分でないものが多く、主に治療効果の判定や再発の監視に用いられる。', '{"B": "前立腺特異抗原（PSA）が上昇する。", "C": "CA19-9が上昇することが多い。", "D": "CA125が上昇することが多い。", "E": "カルシトニンとCEAが上昇する。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'PTHrPによる高カルシウム血症', 2, 'CBT', '肺の扁平上皮癌の患者が、意識障害と口渇、多尿をきたし、血清カルシウム値が著明に高く、PTHは低値であった。この高カルシウム血症の主な機序はどれか。', '[{"key": "A", "text": "腫瘍が活性型ビタミンDを分解する"}, {"key": "B", "text": "腫瘍によるPTHrPの産生"}, {"key": "C", "text": "腫瘍が副甲状腺に転移してPTHを過剰に分泌させる"}, {"key": "D", "text": "腫瘍が抗利尿ホルモンを産生する"}, {"key": "E", "text": "腫瘍がACTHを産生する"}]'::jsonb, 'B', '悪性腫瘍に伴う高カルシウム血症の多くは、腫瘍が産生する副甲状腺ホルモン関連蛋白（PTHrP）による（体液性の高カルシウム血症）。PTHrPはPTHと同じ受容体に作用して骨吸収と腎でのカルシウムの再吸収を促す。肺や頭頸部、食道の扁平上皮癌、成人T細胞白血病・リンパ腫などでみられる。骨転移による局所の骨破壊でも起こる。治療は大量の輸液、ビスホスホネート、デノスマブなどである。', '{"A": "高カルシウム血症の機序ではない。", "C": "血清PTHは低値であり、この機序と合わない。", "D": "SIADHの機序で、低ナトリウム血症をきたす。", "E": "異所性ACTH症候群の機序で、低カリウム血症などをきたす。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '癌悪液質', 2, 'CBT', '進行癌の患者で、十分に食事をとっても体重が減り続け、骨格筋と脂肪が著しく失われていた。癌悪液質の病態に関わる主な物質はどれか。', '[{"key": "A", "text": "成長ホルモンの過剰な分泌"}, {"key": "B", "text": "アディポネクチンの欠乏だけ"}, {"key": "C", "text": "TNF-αなどの炎症性サイトカイン"}, {"key": "D", "text": "膵β細胞からのインスリンの過剰な分泌"}, {"key": "E", "text": "甲状腺ホルモンの著しい低下"}]'::jsonb, 'C', '癌悪液質は、食事の摂取を増やしても元に戻らない骨格筋の減少を中心とする代謝の異常で、体重減少、食欲不振、倦怠感を伴う。腫瘍や宿主の免疫細胞が産生する腫瘍壊死因子α（TNF-α）、インターロイキン6、インターロイキン1などが、筋蛋白の分解、脂肪の分解、食欲の低下、インスリン抵抗性を引き起こす。腫瘍壊死因子αはかつてカケクチンともよばれた。', '{"A": "悪液質の主な原因ではない。", "B": "悪液質の主な原因ではない。", "D": "インスリンは同化を促すホルモンで、悪液質の主な原因ではない。", "E": "悪液質の主な原因ではない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '腫瘍の血管新生', 2, 'CBT', '腫瘍は径1〜2mmを超えて大きくなるために、新しい血管を呼び込む必要がある。腫瘍の血管新生を促す主な因子で、分子標的薬の標的にもなっているものはどれか。', '[{"key": "A", "text": "トロンボポエチン"}, {"key": "B", "text": "インスリン"}, {"key": "C", "text": "カルシトニン"}, {"key": "D", "text": "血管内皮増殖因子（VEGF）"}, {"key": "E", "text": "腎でつくられるエリスロポエチン"}]'::jsonb, 'D', '腫瘍が大きくなると内部が低酸素になり、HIFを介してVEGFなどの血管新生因子が産生され、周囲から新しい血管が伸びてくる。新生血管は構造が不完全で漏れやすい。VEGFに対する抗体のベバシズマブや、VEGF受容体のチロシンキナーゼ阻害薬が大腸癌や肺癌、腎細胞癌などの治療に用いられる。副作用として高血圧、蛋白尿、出血、創傷治癒の遅延などがある。', '{"A": "血小板の産生を促す因子である。", "B": "血糖を下げるホルモンで、血管新生の主な因子ではない。", "C": "骨吸収を抑えるホルモンである。", "E": "赤血球の産生を促すホルモンで、腫瘍の血管新生の主な因子ではない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '上皮内癌', 2, 'CBT', '子宮頸部の円錐切除標本で、癌細胞が上皮の全層を置き換えていたが、基底膜を越えた浸潤はなかった。この病変はどれか。', '[{"key": "A", "text": "微小浸潤癌"}, {"key": "B", "text": "軽度異形成"}, {"key": "C", "text": "扁平上皮化生"}, {"key": "D", "text": "転移性癌"}, {"key": "E", "text": "上皮内癌"}]'::jsonb, 'E', '上皮内癌は、癌細胞が上皮の全層を置き換えているが基底膜を越えていない状態で、血管やリンパ管に達していないため転移しない。完全に切除すれば治癒が期待できる。基底膜を越えて間質に浸潤すると浸潤癌となり、転移の可能性が生じる。子宮頸部では異形成から上皮内癌を経て浸潤癌へと進むことが多く、細胞診による検診で早期に発見できる。', '{"A": "わずかに基底膜を越えて浸潤した癌である。", "B": "上皮の下層の3分の1程度に異型細胞がとどまる病変である。", "C": "円柱上皮が扁平上皮に置き換わった可逆的な変化である。", "D": "他の臓器から転移した癌である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'Marfan症候群', 2, 'CBT', '高身長で手足と指が長く、水晶体の偏位と大動脈基部の拡張がみられる若年者がいる。この疾患の原因となる遺伝子がコードする蛋白質はどれか。', '[{"key": "A", "text": "フィブリリン1"}, {"key": "B", "text": "I型コラーゲン"}, {"key": "C", "text": "ジストロフィン"}, {"key": "D", "text": "エラスチン"}, {"key": "E", "text": "IV型コラーゲン"}]'::jsonb, 'A', 'Marfan症候群はFBN1遺伝子の異常による常染色体顕性遺伝の疾患で、弾性線維の骨格となるフィブリリン1が異常になる。フィブリリン1はTGF-βの働きの調節にも関わる。骨格（高身長、くも状指、漏斗胸）、眼（水晶体偏位）、心血管（大動脈基部の拡張、大動脈解離、僧帽弁逸脱）に異常が現れる。大動脈解離が主な死因となるため、定期的な画像検査とβ遮断薬などで管理する。', '{"B": "骨形成不全症の原因となる蛋白質である。", "C": "Duchenne型筋ジストロフィーの原因となる蛋白質である。", "D": "Williams症候群などで異常がみられる蛋白質である。", "E": "Alport症候群の原因となる蛋白質である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'Duchenne型筋ジストロフィー', 2, 'CBT', '4歳の男児が転びやすく、床から立ち上がるときに手を膝について体を押し上げる。ふくらはぎが肥大し、血清CKが著明に高い。この疾患について正しいのはどれか。', '[{"key": "A", "text": "女児に多く発症する"}, {"key": "B", "text": "X連鎖潜性遺伝で、ジストロフィンが欠損する"}, {"key": "C", "text": "常染色体顕性遺伝で、ジストロフィンが過剰につくられる"}, {"key": "D", "text": "神経筋接合部の自己抗体が原因である"}, {"key": "E", "text": "脊髄前角細胞の変性が原因である"}]'::jsonb, 'B', 'Duchenne型筋ジストロフィーはジストロフィン遺伝子の欠失などによるX連鎖潜性遺伝の疾患で、筋細胞膜を裏打ちするジストロフィンが欠損して筋線維が壊死と再生を繰り返す。幼児期に歩行の異常で発症し、登攀性起立（Gowers徴候）、腓腹筋の仮性肥大を示し、10歳ごろに歩行ができなくなる。心筋症と呼吸不全が主な死因となる。ジストロフィンが部分的につくられるものは軽症のBecker型である。', '{"A": "X連鎖潜性遺伝のため、ほとんどが男児に発症する。", "C": "X連鎖潜性遺伝で、ジストロフィンは欠損する。", "D": "重症筋無力症の病態である。", "E": "脊髄性筋萎縮症などの病態である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'Turner症候群', 2, 'CBT', '低身長と原発性無月経を主訴に受診した15歳の女子で、翼状頸と外反肘がみられた。最も考えられる染色体の核型はどれか。', '[{"key": "A", "text": "46,XY"}, {"key": "B", "text": "47,XX,+21"}, {"key": "C", "text": "45,X"}, {"key": "D", "text": "47,XXY"}, {"key": "E", "text": "47,XXX"}]'::jsonb, 'C', 'Turner症候群はX染色体の1本が欠けた45,Xやそのモザイクによるもので、低身長、卵巣の形成不全による原発性無月経と二次性徴の欠如、翼状頸、外反肘、大動脈縮窄症や大動脈二尖弁、馬蹄腎などを伴う。知能は通常正常である。成長ホルモンで身長を伸ばし、思春期の年齢に女性ホルモンを補充する。', '{"A": "正常男性の核型である。", "B": "21トリソミー（Down症候群）の女性の核型である。", "D": "Klinefelter症候群の核型で、男性の表現型を示す。", "E": "トリプルX症候群の核型で、多くは目立った症状がない。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'Klinefelter症候群', 2, 'CBT', '不妊を主訴に受診した男性が、高身長で、女性化乳房と小さく硬い精巣を示し、精液中に精子がみられなかった。最も考えられる染色体の核型はどれか。', '[{"key": "A", "text": "47,XYY"}, {"key": "B", "text": "46,XX"}, {"key": "C", "text": "47,XY,+18"}, {"key": "D", "text": "47,XXY"}, {"key": "E", "text": "45,X"}]'::jsonb, 'D', 'Klinefelter症候群は男性の約500〜1,000人に1人と頻度の高い性染色体異常で、47,XXYが代表的である。精巣が小さく硬く、精細管の硝子化によって無精子症となり、テストステロンが低く、LHとFSHが高い。高身長、女性化乳房、体毛の減少を示すが、思春期まで気づかれないことが多い。テストステロンの補充や、精巣内精子採取術による生殖補助医療が行われる。', '{"A": "高身長となることがあるが、精巣の萎縮や女性化乳房は典型ではない。", "B": "正常女性の核型である。", "C": "18トリソミーの核型で、重い先天異常を伴う。", "E": "Turner症候群の核型で、女性の表現型を示す。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', 'X連鎖潜性遺伝', 2, 'CBT', 'ある家系で、母方の祖父と叔父が同じ病気を発症しているが、母親は発症していない。X連鎖潜性（劣性）遺伝の特徴として正しいのはどれか。', '[{"key": "A", "text": "男女とも同じ頻度で発症する"}, {"key": "B", "text": "罹患した男性の娘は必ず発症する"}, {"key": "C", "text": "保因者の女性から生まれた息子はすべて発症する"}, {"key": "D", "text": "親から子へ各世代で連続して発症する"}, {"key": "E", "text": "罹患した男性から息子には遺伝しない"}]'::jsonb, 'E', 'X連鎖潜性遺伝の疾患は、X染色体を1本しかもたない男性に主に発症する。罹患した男性はX染色体を娘にだけ渡すので、息子には遺伝せず、娘はすべて保因者となる。保因者の女性の子は、息子の1/2が発症し、娘の1/2が保因者となる。血友病、Duchenne型筋ジストロフィー、G6PD欠損症、赤緑色覚異常などがある。', '{"A": "X連鎖潜性遺伝の疾患は主に男性に発症する。", "B": "娘は必ず保因者となるが、通常は発症しない。", "C": "保因者の女性の息子が発症する確率は1/2である。", "D": "世代を飛ばして現れることが多く、各世代で続くのは常染色体顕性遺伝の特徴である。"}'::jsonb, 'public', 'M', 'C-4', '', 'pending', 'llm'),
('基礎医学', '古典的条件づけ', 2, 'CBT', '抗癌薬の治療で強い悪心・嘔吐を経験した患者が、次の治療の日に病院の建物を見ただけで吐き気を催すようになった。この現象を説明する学習の仕組みはどれか。', '[{"key": "A", "text": "古典的条件づけ"}, {"key": "B", "text": "オペラント条件づけ"}, {"key": "C", "text": "観察学習"}, {"key": "D", "text": "洞察学習"}, {"key": "E", "text": "馴化"}]'::jsonb, 'A', '古典的条件づけ（レスポンデント条件づけ）は、もともと反応を起こさない刺激（病院の建物）が、反応を起こす刺激（抗癌薬）と繰り返し対になることで、同じ反応（吐き気）を起こすようになる学習で、Pavlovの犬の実験で知られる。化学療法の予期性嘔吐はその例で、初回から十分な制吐療法を行うことが予防になる。恐怖症の成り立ちの説明にも使われる。', '{"B": "自発的な行動が、その結果（報酬や罰）によって増えたり減ったりする学習である。", "C": "他者の行動とその結果を見ることで起こる学習である。", "D": "試行錯誤によらず、問題の構造を見抜いて解決に至る学習である。", "E": "同じ刺激を繰り返し受けるうちに反応が弱まる現象である。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '負の強化', 2, 'CBT', '頭痛のある患者が鎮痛薬を飲むと痛みが消えるので、痛みを感じるとすぐに薬を飲むようになった。嫌な刺激が取り除かれることで、その直前の行動が増えるこの仕組みはどれか。', '[{"key": "A", "text": "消去"}, {"key": "B", "text": "負の強化"}, {"key": "C", "text": "正の強化"}, {"key": "D", "text": "正の罰"}, {"key": "E", "text": "負の罰"}]'::jsonb, 'B', 'オペラント条件づけでは、行動の後に何が起こるかで行動の頻度が変わる。好ましいものが与えられて行動が増えるのが正の強化、嫌なものが取り除かれて行動が増えるのが負の強化である。罰は行動を減らす。負の強化は「罰」と混同されやすいが、行動を増やす仕組みである。鎮痛薬の頻回の使用は、薬剤の使用過多による頭痛の一因となりうる。', '{"A": "行動に結果が伴わなくなることで、行動が減っていく現象である。", "C": "好ましい刺激が与えられることで、行動が増える仕組みである。", "D": "嫌な刺激が与えられることで、行動が減る仕組みである。", "E": "好ましい刺激が取り除かれることで、行動が減る仕組みである。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '消去', 2, 'CBT', 'スーパーで泣いて騒ぐと親がお菓子を買い与えていた幼児に、泣いても買い与えないことを一貫して続けたところ、一時的に泣き方が激しくなったあと、泣いて騒ぐ行動が減っていった。この変化はどれか。', '[{"key": "A", "text": "刷り込み"}, {"key": "B", "text": "鋭敏化"}, {"key": "C", "text": "消去"}, {"key": "D", "text": "般化"}, {"key": "E", "text": "正の強化"}]'::jsonb, 'C', '強化されていた行動に強化が伴わなくなると、その行動は次第に減っていく（消去）。消去の初期には一時的に行動が激しくなることがあり（消去バースト）、ここで強化してしまうと、より激しい行動が強化される。一貫した対応が重要である。消去された行動が時間をおいて再び現れることもある（自発的回復）。', '{"A": "発達の早い時期の限られた期間にだけ成立する特殊な学習である。", "B": "刺激を繰り返し受けるうちに反応が強まる現象である。", "D": "学習した反応が、似た別の刺激に対しても起こるようになる現象である。", "E": "好ましい刺激が与えられて行動が増える仕組みで、行動は減らない。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '系統的脱感作法', 2, 'CBT', 'エレベーターに乗ることを強く恐れる患者に、不安の程度で場面を段階づけた表をつくり、リラクセーションを行いながら弱い場面から順に想像させて慣らしていく治療を行った。この治療法はどれか。', '[{"key": "A", "text": "来談者中心療法"}, {"key": "B", "text": "森田療法"}, {"key": "C", "text": "自律訓練法"}, {"key": "D", "text": "系統的脱感作法"}, {"key": "E", "text": "精神分析療法"}]'::jsonb, 'D', '系統的脱感作法は古典的条件づけの原理にもとづく行動療法で、不安と両立しないリラックスした状態で、不安階層表の弱い場面から順に想像や実際の場面にさらしていき、不安の反応を弱める（逆制止）。恐怖症や不安症に用いられる。実際の場面に段階的に向き合う曝露療法も同じ考え方にもとづく。', '{"A": "受容、共感的理解、自己一致を重視して自己成長を支える治療法である。", "B": "不安をあるがままに受け入れて行動することを目指す、日本で生まれた治療法である。", "C": "自己暗示で心身をリラックスさせる方法で、段階的に不安場面に慣らす治療法そのものではない。", "E": "無意識の葛藤を自由連想などで明らかにする治療法である。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '観察学習', 2, 'CBT', '糖尿病の教室で、ほかの患者がインスリンの自己注射を上手に行い、医療者にほめられる様子を見た患者が、自分でも注射に取り組めるようになった。このような学習はどれか。', '[{"key": "A", "text": "古典的条件づけ"}, {"key": "B", "text": "試行錯誤学習"}, {"key": "C", "text": "刷り込み"}, {"key": "D", "text": "馴化"}, {"key": "E", "text": "観察学習"}]'::jsonb, 'E', '観察学習（モデリング）はBanduraが示した学習で、他者（モデル）の行動とその結果を観察するだけで、自分では直接の報酬を受けなくても行動を身につける。モデルが自分と似ているほど、また行動がうまくいく様子を見るほど効果が高い。患者教室やピアサポートで同じ病気の人の経験を聞くことは、観察学習と自己効力感の向上に役立つ。', '{"A": "刺激と反応の対応が結びつく学習で、他者を見て学ぶものではない。", "B": "自分で繰り返し試しながら成功した行動を身につける学習である。", "C": "発達の早い時期に限って成立する特殊な学習である。", "D": "同じ刺激に繰り返しさらされて反応が弱まる現象である。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '自己効力感', 2, 'CBT', '禁煙を目指す患者が「自分なら禁煙をやり遂げられる」と感じられるほど、禁煙に成功しやすい。このように、ある行動をうまく行えるという本人の見込みを表す概念はどれか。', '[{"key": "A", "text": "自己効力感"}, {"key": "B", "text": "自尊感情"}, {"key": "C", "text": "学習性無力感"}, {"key": "D", "text": "内的統制"}, {"key": "E", "text": "結果予期"}]'::jsonb, 'A', '自己効力感はBanduraが提唱した概念で、ある行動をうまく行えるという本人の確信である。自己効力感を高めるには、小さな成功体験を積み重ねること（遂行行動の達成）が最も有効で、他者の成功を見ること（代理体験）、励まし（言語的説得）、体調や気分の改善（生理的・情動的状態）も役立つ。行動変容の支援では、達成可能な小さな目標を立てることが勧められる。', '{"B": "自分自身を価値ある存在と感じる感覚で、特定の行動についての見込みではない。", "C": "何をしても結果を変えられないと学習して、行動しなくなる状態である。", "D": "結果が自分の行動で決まると考える傾向で、特定の行動をやり遂げられる見込みとは異なる。", "E": "ある行動がどのような結果につながるかについての見込みである。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', 'Maslowの欲求階層', 2, 'CBT', 'Maslowは、人の欲求を階層として捉え、下位の欲求が満たされると上位の欲求が現れると考えた。Maslowの欲求階層で最上位に位置づけられる欲求はどれか。', '[{"key": "A", "text": "承認の欲求"}, {"key": "B", "text": "自己実現の欲求"}, {"key": "C", "text": "生理的欲求"}, {"key": "D", "text": "安全の欲求"}, {"key": "E", "text": "所属と愛の欲求"}]'::jsonb, 'B', 'Maslowの欲求階層は、下から生理的欲求、安全の欲求、所属と愛の欲求、承認（自尊）の欲求、自己実現の欲求の順に並ぶ。下位の欠乏欲求が満たされると、自分の可能性を実現しようとする成長欲求が現れるとした。医療の場では、痛みや不安など基本的な欲求が満たされていない患者に、先に高次の目標を求めても受け入れられにくいことを理解する助けになる。', '{"A": "他者から認められ、自分を価値ある存在と感じたい欲求である。", "C": "食事、睡眠など生命の維持に関わる、最も基本的な欲求である。", "D": "危険から身を守り、安定を求める欲求で、生理的欲求の次に位置する。", "E": "集団に属し、他者と愛情でつながることを求める欲求である。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '内発的動機づけ', 2, 'CBT', '医学生が、試験のためではなく、疾患の仕組みを理解すること自体が面白くて自主的に勉強を続けている。このような動機づけはどれか。', '[{"key": "A", "text": "回避動機づけ"}, {"key": "B", "text": "達成動機づけの欠如"}, {"key": "C", "text": "内発的動機づけ"}, {"key": "D", "text": "外発的動機づけ"}, {"key": "E", "text": "生理的動機づけ"}]'::jsonb, 'C', '内発的動機づけは、興味や関心、知的好奇心など、活動そのものから得られる満足によって行動が続く状態である。外発的動機づけは報酬や評価などの外的な目的による。もともと内発的に行っていた活動に外的な報酬を与えると、報酬がなくなったときに意欲が下がることがある（アンダーマイニング効果）。自律性、有能感、他者との関係性が満たされると内発的動機づけが高まるとされる。', '{"A": "失敗や罰を避けるために行動する動機づけである。", "B": "学習を続けている状態とは合わない。", "D": "報酬や罰、評価など、行動の外にある目的によって行動が引き起こされる動機づけである。", "E": "空腹や渇きなど、生理的な欠乏によって生じる動機づけである。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '汎適応症候群', 2, 'CBT', 'Selyeは、生体がストレッサーにさらされ続けたときに、ストレッサーの種類によらず共通の反応が段階的に進むと考えた。この反応の段階の順序として正しいのはどれか。', '[{"key": "A", "text": "疲憊期、抵抗期、警告反応期"}, {"key": "B", "text": "警告反応期、疲憊期、抵抗期"}, {"key": "C", "text": "否認期、怒りの期、受容期"}, {"key": "D", "text": "警告反応期、抵抗期、疲憊期"}, {"key": "E", "text": "抵抗期、警告反応期、疲憊期"}]'::jsonb, 'D', '汎適応症候群では、ストレッサーにさらされると、まず一時的に抵抗力が落ちたのちに交感神経と副腎髄質、視床下部-下垂体-副腎系が働いて警告反応期となる。続く抵抗期ではストレッサーに適応して抵抗力が高まった状態が保たれる。さらに長く続くと適応の力が尽きて疲憊期となり、病気や死に至ることがある。副腎の肥大、胸腺の萎縮、胃潰瘍が特徴的な変化として示された。', '{"A": "順序が逆である。", "B": "抵抗期のあとに、適応の力が尽きて疲憊期となる。", "C": "死にゆく患者の心理の過程として述べられたもので、汎適応症候群ではない。", "E": "最初に起こるのは警告反応期である。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '学習性無力感', 2, 'CBT', '長期の療養で、何度努力しても症状が改善しなかった患者が、改善の見込みのある新しい治療を勧められても取り組もうとしなくなった。この状態を説明する概念はどれか。', '[{"key": "A", "text": "自己効力感"}, {"key": "B", "text": "認知的不協和"}, {"key": "C", "text": "防衛機制の昇華"}, {"key": "D", "text": "社会的促進"}, {"key": "E", "text": "学習性無力感"}]'::jsonb, 'E', '学習性無力感はSeligmanが示した現象で、自分の行動では避けられない不快な出来事を繰り返し経験すると、「何をしても無駄だ」と学習し、状況が変わって回避できるようになっても行動しなくなる。うつ病のモデルの一つとされる。小さな成功体験を積んで「自分の行動で結果を変えられる」と感じられるように支援することが回復の助けになる。', '{"A": "行動をうまく行えるという確信で、行動を起こす方向に働く。", "B": "矛盾する認知を抱えたときの不快な状態で、この状態の説明には当たらない。", "C": "受け入れがたい衝動を、社会的に価値のある活動に向け変える働きである。", "D": "他者がいることで、よく慣れた作業の成績が上がる現象である。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', 'タイプA行動パターン', 2, 'CBT', 'Friedmanらは、ある特徴的な行動様式をもつ人に冠動脈疾患が多いことを報告した。この行動様式（タイプA行動パターン）の特徴はどれか。', '[{"key": "A", "text": "競争心が強く、せっかちで敵意をもちやすい"}, {"key": "B", "text": "おだやかでのんびりしており、競争を好まない"}, {"key": "C", "text": "否定的な感情を抱きやすいが、それを表に出さずに抑える"}, {"key": "D", "text": "感情を抑えて他者に合わせ、自己主張を避ける"}, {"key": "E", "text": "新しい経験を好み、想像力が豊かである"}]'::jsonb, 'A', 'タイプA行動パターンは、強い達成意欲と競争心、時間の切迫感、せっかちさ、攻撃性や敵意を特徴とする。冠動脈疾患の危険因子として報告され、その後の研究では特に敵意や怒りの要素が関連すると考えられている。否定的な感情を抱きながらそれを抑えるタイプDの性格傾向も心疾患の予後との関連が指摘されている。', '{"B": "タイプBの行動様式の特徴である。", "C": "タイプDとよばれる性格傾向の特徴である。", "D": "癌との関連が議論されたタイプCの特徴である。", "E": "性格の5因子モデルの開放性の特徴である。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', 'Piagetの具体的操作期', 2, 'CBT', 'Piagetは子どもの認知発達を4つの段階に分けた。形が変わっても量は変わらないという保存の概念を獲得し、具体的な事物についてなら論理的に考えられるようになる段階はどれか。', '[{"key": "A", "text": "潜伏期"}, {"key": "B", "text": "具体的操作期"}, {"key": "C", "text": "感覚運動期"}, {"key": "D", "text": "前操作期"}, {"key": "E", "text": "形式的操作期"}]'::jsonb, 'B', 'Piagetの認知発達段階は、感覚運動期（0〜2歳）、前操作期（2〜7歳）、具体的操作期（7〜11歳）、形式的操作期（11歳以降）の順に進む。具体的操作期には保存の概念や分類、系列化ができるようになるが、抽象的な思考はまだ難しい。子どもに病気や治療を説明するときは、発達段階に合わせて具体的なものや絵を使うと理解されやすい。', '{"A": "Freudの心理性的発達段階の用語で、Piagetの段階ではない。", "C": "0〜2歳ごろの段階で、感覚と運動を通して外界を理解し、対象の永続性を獲得する。", "D": "2〜7歳ごろの段階で、言葉やイメージを使えるが、自己中心性が強く保存の概念はまだない。", "E": "11歳ごろ以降の段階で、抽象的、仮説的な事柄について論理的に考えられる。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', 'Eriksonの青年期の課題', 2, 'CBT', 'Eriksonは、人の一生を8つの段階に分け、段階ごとに乗り越えるべき心理社会的な課題があるとした。青年期の心理社会的な課題はどれか。', '[{"key": "A", "text": "親密性 対 孤立"}, {"key": "B", "text": "統合 対 絶望"}, {"key": "C", "text": "同一性の確立 対 同一性の拡散"}, {"key": "D", "text": "基本的信頼 対 不信"}, {"key": "E", "text": "勤勉性 対 劣等感"}]'::jsonb, 'C', 'Eriksonの心理社会的発達段階では、乳児期の基本的信頼、幼児期前期の自律性、幼児期後期の自主性、学童期の勤勉性、青年期の同一性、成人期初期の親密性、成人期の生殖性（世代性）、老年期の統合が課題となる。青年期には「自分は何者か」を問い、社会の中での自分の役割を見いだす。慢性疾患をもつ思春期の患者では、病気と自己像の折り合いが課題になりやすい。', '{"A": "成人期初期の課題である。", "B": "老年期の課題である。", "D": "乳児期の課題である。", "E": "学童期の課題である。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '安定型の愛着', 2, 'CBT', '1歳の子どもと母親を見知らぬ部屋に入れ、母親が退室したり戻ったりする場面を観察した（ストレンジ・シチュエーション法）。母親が退室すると泣いて探し、戻ると喜んで近づいてすぐに落ち着き、再び遊び始めた。この子どもの愛着の型はどれか。', '[{"key": "A", "text": "アンビバレント型"}, {"key": "B", "text": "無秩序型"}, {"key": "C", "text": "脱抑制型"}, {"key": "D", "text": "安定型"}, {"key": "E", "text": "回避型"}]'::jsonb, 'D', 'Bowlbyは、乳児が特定の養育者との間に情緒的な結びつき（愛着）を形成し、それが安心の基地となると考えた。Ainsworthはストレンジ・シチュエーション法で愛着の型を分類し、安定型の子どもは養育者を安全基地として探索し、分離で不安を示しても再会で速やかに安心する。養育者が子どもの合図に敏感に応答することが、安定した愛着の形成に関わる。', '{"A": "分離で強く混乱し、再会しても母親に接近しながら怒りを示し、なかなか落ち着かない。", "B": "近づきながら顔をそむけるなど、一貫しない奇妙な行動を示す。", "C": "見知らぬ大人にもためらいなく近づく状態で、この観察の型の分類ではない。", "E": "母親との分離でも再会でも、母親を避けたり無関心であったりする。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '人見知り', 2, 'CBT', '生後8か月の乳児が、母親には笑顔を見せるが、初めて会う医師が近づくと泣き出して母親にしがみついた。この反応の説明として正しいのはどれか。', '[{"key": "A", "text": "発達の遅れを示す徴候である"}, {"key": "B", "text": "聴覚障害を疑う所見である"}, {"key": "C", "text": "視力が低下していることを示す"}, {"key": "D", "text": "生後すぐから一生続く反応である"}, {"key": "E", "text": "愛着が形成されたことを示す"}]'::jsonb, 'E', '生後6〜8か月ごろになると、乳児は養育者とそれ以外の人を見分け、見知らぬ人に不安を示すようになる（人見知り、8か月不安）。これは特定の養育者への愛着が形成された証拠で、同じころから養育者と離れることへの不安（分離不安）もみられる。乳児の診察では保護者の膝の上で行うなど、不安を和らげる工夫をする。', '{"A": "この時期の正常な発達の現れである。", "B": "聴覚の障害を示すものではない。", "C": "人の顔を見分けられるようになったことを示す。", "D": "生後半年ごろから現れ、2歳ごろにかけて和らいでいく。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '手続き記憶', 2, 'CBT', '重い健忘のある患者が、新しい出来事は覚えられないのに、練習を重ねた鏡映描写などの作業は日ごとに上達した。意識しなくても体で覚えているこのような記憶はどれか。', '[{"key": "A", "text": "手続き記憶"}, {"key": "B", "text": "エピソード記憶"}, {"key": "C", "text": "意味記憶"}, {"key": "D", "text": "作業記憶（ワーキングメモリ）"}, {"key": "E", "text": "感覚記憶"}]'::jsonb, 'A', '長期記憶は、言葉で説明できる陳述記憶（エピソード記憶と意味記憶）と、言葉で説明しにくい非陳述記憶に分けられる。手続き記憶は非陳述記憶の一つで、自転車の乗り方や楽器の演奏のような技能の記憶であり、大脳基底核や小脳が関わる。海馬が障害された健忘の患者でも、手続き記憶は保たれて新たな技能を学習できる。', '{"B": "いつ、どこで、何があったかという個人の出来事の記憶で、健忘で障害されやすい。", "C": "言葉の意味や一般的な知識の記憶である。", "D": "情報を一時的に保持しながら操作する記憶である。", "E": "感覚器から入った情報がごく短時間だけ保たれる記憶である。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '利用可能性ヒューリスティック', 2, 'CBT', '先週まれな疾患の患者を診察した研修医が、今週、似た症状の患者を診て、よくある疾患を検討する前にまずその疾患を疑った。思い出しやすい事例ほど起こりやすいと判断してしまうこの思考の偏りはどれか。', '[{"key": "A", "text": "フレーミング効果"}, {"key": "B", "text": "利用可能性ヒューリスティック"}, {"key": "C", "text": "代表性ヒューリスティック"}, {"key": "D", "text": "アンカリング"}, {"key": "E", "text": "後知恵バイアス"}]'::jsonb, 'B', 'ヒューリスティックは経験にもとづく近道の思考で、素早く判断できる反面、系統的な偏りを生む。利用可能性ヒューリスティックでは、最近経験した印象的な症例や思い出しやすい事例を、実際より多いと見積もってしまう。診断の誤りを防ぐには、鑑別診断を系統的に挙げ、疾患の頻度を意識し、自分の思考の過程を振り返ることが大切である。', '{"A": "同じ内容でも、表現の仕方によって判断が変わる偏りである。", "C": "典型像に似ているかどうかで判断し、疾患の頻度（事前確率）を無視しやすい偏りである。", "D": "最初に得た情報や最初の診断にとらわれて、判断を十分に修正できない偏りである。", "E": "結果を知ったあとで、初めから予測できたと思い込む偏りである。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', 'アンカリング', 2, 'CBT', '救急外来で「胃腸炎」として紹介された腹痛の患者を、担当医が最初からその診断で診療を進め、途中で得られた虫垂炎を示す所見を軽視してしまった。この思考の偏りはどれか。', '[{"key": "A", "text": "ハロー効果"}, {"key": "B", "text": "ピグマリオン効果"}, {"key": "C", "text": "アンカリング"}, {"key": "D", "text": "利用可能性ヒューリスティック"}, {"key": "E", "text": "フレーミング効果"}]'::jsonb, 'C', 'アンカリングは、最初に得た情報（紹介状の診断など）に判断が引きずられ、新しい情報が得られても十分に修正できない偏りである。自分の仮説を支持する情報ばかり集める確証バイアスや、診断が早く決まると他の可能性を考えなくなる早期閉鎖と重なって診断の誤りを生む。「ほかに考えるべき疾患はないか」と意識的に問い直すことが対策となる。', '{"A": "ある目立つ特徴に引きずられて、全体の評価がゆがむ偏りである。", "B": "期待をかけられた人が、その期待に沿って成果を上げる現象である。", "D": "思い出しやすい事例を起こりやすいと判断する偏りである。", "E": "同じ内容でも、表現の仕方によって判断が変わる偏りである。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '認知的不協和', 2, 'CBT', '喫煙が健康に悪いことを知っている喫煙者が、「喫煙の害は誇張されている」「祖父は喫煙者でも長生きした」と考えて喫煙を続けている。この心理を説明する概念はどれか。', '[{"key": "A", "text": "他者を手本にした観察学習"}, {"key": "B", "text": "社会的促進"}, {"key": "C", "text": "単純接触効果"}, {"key": "D", "text": "認知的不協和の低減"}, {"key": "E", "text": "学習性無力感"}]'::jsonb, 'D', 'Festingerの認知的不協和理論では、互いに矛盾する認知（喫煙は体に悪い、自分は喫煙している）を抱えると不快な緊張が生じ、人は行動を変えるか、認知の方を変えてこれを減らそうとする。行動を変えるのが難しいと、害を過小評価するなど認知をゆがめることが多い。禁煙の支援では、こうした心理を責めずに受け止め、行動を変えるほうへ導くことが大切である。', '{"A": "他者の行動を見て学ぶことで、この心理の説明には当たらない。", "B": "他者の存在で作業の成績が上がる現象である。", "C": "繰り返し接するだけで対象への好意が高まる現象である。", "E": "何をしても結果を変えられないと学習した状態である。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '同調', 2, 'CBT', '明らかに長さの違う線分の比較で、周りの複数の人がそろって誤った答えを言うと、それに合わせて誤答する人が少なくなかった。Aschの実験で示されたこの現象はどれか。', '[{"key": "A", "text": "服従"}, {"key": "B", "text": "社会的手抜き"}, {"key": "C", "text": "傍観者効果"}, {"key": "D", "text": "集団極性化"}, {"key": "E", "text": "同調"}]'::jsonb, 'E', '同調は、集団の多数派の意見や行動に合わせて自分の判断や行動を変えることである。Aschの実験では、明らかに誤った多数派の答えに多くの人が少なくとも一度は同調した。1人でも異なる意見の人がいると同調は大きく減る。医療チームでは、上位者や多数の意見に異を唱えにくい雰囲気が医療安全を損なうことがあり、誰でも懸念を口にできる環境づくりが重要である。', '{"A": "権威のある人の命令に従って行動することで、Milgramの実験で示された。", "B": "集団で作業すると一人あたりの努力が減る現象である。", "C": "周りに人が多いほど、困っている人を助ける行動が起こりにくくなる現象である。", "D": "集団で話し合うと、意見が個人のときより極端な方向に偏る現象である。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '基本的な帰属の誤り', 2, 'CBT', '予約の時刻に何度も遅れる患者を、職員が「だらしない性格だ」と決めつけていたが、実は介護と仕事のため通院の時間が取りにくい事情があった。他者の行動の原因を状況よりも本人の性格に求めやすいこの傾向はどれか。', '[{"key": "A", "text": "基本的な帰属の誤り"}, {"key": "B", "text": "自己奉仕バイアス"}, {"key": "C", "text": "ハロー効果"}, {"key": "D", "text": "確証バイアス"}, {"key": "E", "text": "投影"}]'::jsonb, 'A', '人は他者の行動を説明するとき、置かれた状況の影響を軽く見て、性格や態度などの内的な原因を過大に見積もりやすい（基本的な帰属の誤り）。受診行動や服薬の問題も、本人の意欲の問題と決めつける前に、経済的な事情、家族の状況、交通手段などの社会的な背景を確かめることが、適切な支援につながる。', '{"B": "自分の成功は自分の能力に、失敗は状況に帰属させる傾向である。", "C": "目立つ特徴に引きずられて、全体の評価がゆがむ偏りである。", "D": "自分の考えを支持する情報ばかりを集める偏りである。", "E": "自分の受け入れがたい感情を他者のものとみなす防衛機制である。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', 'プラセボ効果', 2, 'CBT', '新しい鎮痛薬の臨床試験で、有効成分を含まない錠剤を飲んだ群でも、痛みがかなり改善した人が多かった。この現象はどれか。', '[{"key": "A", "text": "耐性"}, {"key": "B", "text": "プラセボ効果"}, {"key": "C", "text": "ノセボ効果"}, {"key": "D", "text": "Hawthorne効果"}, {"key": "E", "text": "平均への回帰"}]'::jsonb, 'B', 'プラセボ効果は、有効成分を含まない偽薬でも、治療を受けているという期待や医療者との関係などによって症状が改善する現象で、痛みや不安、消化器症状などの主観的な症状で大きい。薬の効果を正しく評価するため、臨床試験ではプラセボを対照とし、患者も評価者も割り付けを知らない二重盲検で行う。副作用の説明によって症状が現れるノセボ効果もある。', '{"A": "薬を続けると効果が弱まる現象である。", "C": "有効成分がないのに、副作用などの好ましくない症状が現れる現象である。", "D": "観察されていることを意識して、行動が変わる現象である。", "E": "極端な値のあとの測定が平均に近づく統計的な現象で、薬の期待による効果ではない。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', 'Hawthorne効果', 2, 'CBT', '病棟で転倒予防の手順が守られているかを調べるために、観察者が病棟に立って記録を始めたところ、観察している期間だけ手順の遵守率が上がった。この現象はどれか。', '[{"key": "A", "text": "単純接触効果"}, {"key": "B", "text": "傍観者効果"}, {"key": "C", "text": "Hawthorne効果"}, {"key": "D", "text": "プラセボ効果"}, {"key": "E", "text": "ピグマリオン効果"}]'::jsonb, 'C', 'Hawthorne効果は、人が観察されていることや研究の対象になっていることを意識して、ふだんと異なる行動をとる現象で、工場の作業効率の研究から名づけられた。直接観察による評価では実態より良い結果が出やすいため、観察の方法を工夫したり、長期間観察して慣れを待ったりする。研究の結果を解釈するときの注意点の一つである。', '{"A": "繰り返し接するだけで好意が高まる現象である。", "B": "周りに人が多いほど、援助行動が起こりにくくなる現象である。", "D": "偽薬への期待などで症状が改善する現象である。", "E": "期待をかけられた人が、その期待に沿って成果を上げる現象である。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '健康信念モデル', 2, 'CBT', '乳癌検診を受けるかどうかは、自分が乳癌にかかる可能性や、かかったときの重大さをどう感じるか、検診の利益と負担をどう比べるかによって左右される。この考え方にもとづく保健行動の理論はどれか。', '[{"key": "A", "text": "汎適応症候群"}, {"key": "B", "text": "欲求階層説"}, {"key": "C", "text": "愛着理論"}, {"key": "D", "text": "健康信念モデル"}, {"key": "E", "text": "行動変容ステージモデル"}]'::jsonb, 'D', '健康信念モデルでは、人は病気へのかかりやすさ（罹患性）と重大さ（重大性）を強く感じ、予防行動の利益が障害（費用、手間、痛みなど）を上回ると感じるときに行動をとるとされる。行動のきっかけ（家族の病気や医師の勧め）や自己効力感も影響する。検診の受診勧奨では、利益を具体的に伝え、受診の障害を減らす工夫が有効である。', '{"A": "ストレッサーに対する生体の反応を段階的に捉えた理論である。", "B": "人の欲求を5つの階層として捉えた理論である。", "C": "乳幼児と養育者の情緒的な結びつきについての理論である。", "E": "行動の変化を、無関心期から維持期までの段階として捉える理論である。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '病者役割', 2, 'CBT', 'Parsonsは、病気になった人が社会の中で担う役割を病者役割として説明した。病者役割の内容として正しいのはどれか。', '[{"key": "A", "text": "病気になったことについて本人が責任を問われる"}, {"key": "B", "text": "社会的な役割はすべて病前と同じように果たし続ける"}, {"key": "C", "text": "回復に向けて努力する義務は負わない"}, {"key": "D", "text": "専門家に援助を求めずに自分だけで治す"}, {"key": "E", "text": "社会的役割を免除され、回復に努める義務を負う"}]'::jsonb, 'E', 'Parsonsの病者役割には、2つの権利（通常の社会的役割の免除、病気になったことの責任を問われない）と、2つの義務（回復しようと努める、専門家に援助を求めて協力する）がある。急性の疾患の説明には合うが、治ることを前提としているため、慢性疾患や障害のように病気とともに生きる人には当てはまりにくいと批判されている。', '{"A": "病気は本人の責任ではないとみなされる。", "B": "病者役割では通常の役割が一時的に免除される。", "C": "回復に努めることが病者の義務とされる。", "D": "専門家に援助を求めて協力することが義務とされる。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '統制の所在', 2, 'CBT', '「健康でいられるかどうかは自分の生活習慣しだいだ」と考える人と、「運や医師しだいだ」と考える人がいる。結果が自分の行動によって決まると考える傾向を表す概念はどれか。', '[{"key": "A", "text": "内的統制（内的な統制の所在）"}, {"key": "B", "text": "外的統制"}, {"key": "C", "text": "学習性無力感"}, {"key": "D", "text": "外発的動機づけ"}, {"key": "E", "text": "基本的な帰属の誤り"}]'::jsonb, 'A', '統制の所在（ローカス・オブ・コントロール）はRotterが提唱した概念で、結果を自分の努力や能力によるものと考える傾向を内的統制、運や他者によるものと考える傾向を外的統制という。健康に関する内的統制が強い人は、生活習慣の改善などの保健行動をとりやすいとされる。外的統制の強い人には、小さな成功体験で自分の行動の効果を実感してもらう支援が役立つ。', '{"B": "結果が運や他者など自分以外のものによって決まると考える傾向である。", "C": "何をしても結果を変えられないと学習して、行動しなくなる状態である。", "D": "報酬や評価など外的な目的によって行動が引き起こされることである。", "E": "他者の行動の原因を本人の性格に求めやすい偏りである。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '道具的サポート', 2, 'CBT', '骨折で自宅療養中の高齢者のために、近所に住む娘が毎日の買い物と食事の支度を引き受けている。ソーシャルサポートの分類で、このような支援はどれか。', '[{"key": "A", "text": "自己効力感"}, {"key": "B", "text": "道具的サポート"}, {"key": "C", "text": "情緒的サポート"}, {"key": "D", "text": "情報的サポート"}, {"key": "E", "text": "評価的サポート"}]'::jsonb, 'B', 'ソーシャルサポートは、情緒的サポート（共感、励まし）、道具的サポート（家事、介護、金銭などの実際的な援助）、情報的サポート（助言、情報）、評価的サポート（肯定的な評価）などに分けられる。ソーシャルサポートが豊かな人は、ストレスの影響を受けにくく、疾患の予後もよいことが知られている。退院支援では、患者の周囲にどのような支援があるかを確かめる。', '{"A": "本人の行動の見込みで、他者からの支援の分類ではない。", "C": "話を聞いて共感し、励ましたり安心させたりする支援である。", "D": "問題の解決に役立つ助言や情報を与える支援である。", "E": "本人の考えや行動を認め、肯定的に評価する支援である。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '転移', 2, 'CBT', '長く通院している患者が、担当医に対して、かつて厳しかった父親に向けていたのと同じような反発や恐れの感情を向けるようになった。この現象はどれか。', '[{"key": "A", "text": "同一視"}, {"key": "B", "text": "反動形成"}, {"key": "C", "text": "転移"}, {"key": "D", "text": "逆転移"}, {"key": "E", "text": "投影"}]'::jsonb, 'C', '転移は、患者が過去の重要な人物（親など）に向けていた感情や態度を、治療者に向ける現象で、精神分析の概念である。陽性の転移（信頼、好意）も陰性の転移（反発、敵意）もある。治療者が患者に同じように向ける感情は逆転移とよばれる。医療者は、患者から向けられる強い感情や自分の中に湧く感情に気づき、振り回されずに関わることが大切である。', '{"A": "他者の特徴を取り入れて自分と一体化させる防衛機制である。", "B": "受け入れがたい感情と正反対の態度をとる防衛機制である。", "D": "治療者が患者に対して、自分の過去の人間関係に由来する感情を向けることである。", "E": "自分の受け入れがたい感情を、他者がもっているとみなす防衛機制である。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '退行', 2, 'CBT', '入院した5歳の男児が、それまでできていたトイレでの排尿ができなくなり、指しゃぶりや赤ちゃん言葉が目立つようになった。この心理的な反応として最も適切なのはどれか。', '[{"key": "A", "text": "合理化"}, {"key": "B", "text": "否認"}, {"key": "C", "text": "知性化"}, {"key": "D", "text": "退行"}, {"key": "E", "text": "昇華"}]'::jsonb, 'D', '退行は、強い不安やストレスにさらされたときに、より幼い発達段階の行動に戻る防衛機制である。入院や弟妹の誕生を契機に小児によくみられ、成人でも重い病気の際に依存的になることがある。多くは一時的なもので、叱らずに安心できる環境を整え、できていることを認めることで回復しやすい。', '{"A": "もっともらしい理由をつけて自分の失敗や行動を正当化する働きである。", "B": "受け入れがたい現実を事実として認めない働きである。", "C": "感情を切り離し、知的な理屈や情報で問題を扱おうとする働きである。", "E": "受け入れがたい衝動を、スポーツや芸術など社会的に価値のある活動に向け変える働きである。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm'),
('基礎医学', '合理化', 2, 'CBT', '志望していた大学に不合格となった受験生が「あの大学は本当は自分に合っていなかったから、落ちてよかった」と話している。この心理的な反応として最も適切なのはどれか。', '[{"key": "A", "text": "退行"}, {"key": "B", "text": "投影"}, {"key": "C", "text": "抑圧"}, {"key": "D", "text": "置き換え"}, {"key": "E", "text": "合理化"}]'::jsonb, 'E', '合理化は、失敗や受け入れがたい行動に、もっともらしい理由をつけて自分を納得させる防衛機制で、手に入らなかったものの価値を下げる「すっぱいブドウ」の論理が代表例である。防衛機制は不安から自分を守る無意識の働きで、適度であれば適応に役立つ。患者の言動に防衛機制を見て取ったときは、否定せずに背景にある不安に目を向ける。', '{"A": "より幼い発達段階の行動に戻る防衛機制である。", "B": "自分の受け入れがたい感情を、他者のものとみなす防衛機制である。", "C": "受け入れがたい考えや記憶を、意識から締め出す防衛機制である。", "D": "ある対象への感情を、より安全な別の対象に向ける防衛機制である。"}'::jsonb, 'public', 'M', 'C-5', '', 'pending', 'llm')
),
added AS (
    INSERT INTO quiz_question (category, topic, difficulty, exam_type, question_text, choices, correct_choice_key, explanation, choice_explanations, visibility, question_type, blueprint_code, class_group, status, source, correct_rate, answer_count, created_at)
    SELECT v.category, v.topic, v.difficulty, v.exam_type, v.question_text, v.choices, v.correct_choice_key, v.explanation, v.choice_explanations, v.visibility, v.question_type, v.blueprint_code, v.class_group, v.status, v.source, 0, 0, now()
    FROM v
    WHERE NOT EXISTS (
        SELECT 1 FROM quiz_question q
        WHERE q.exam_type = v.exam_type
          AND q.question_text = v.question_text
          AND q.choices = v.choices)
    RETURNING 1
)
SELECT (SELECT count(*) FROM added) AS "追加した問題",
       (SELECT count(*) FROM v) - (SELECT count(*) FROM added) AS "すでにあった問題",
       (SELECT count(*) FROM v) AS "このファイルの問題";
